Here is a complete Countdown Latch utility in Python supporting thread synchronization and timeouts.

```python
import threading
import time

class CountDownLatch:
    def __init__(self, count: int):
        if count < 0:
            raise ValueError("Count cannot be negative")
        self._count = count
        self._lock = threading.Lock()
        self._condition = threading.Condition(self._lock)

    def countDown(self) -> None:
        with self._lock:
            if self._count > 0:
                self._count -= 1
                if self._count == 0:
                    self._condition.notify_all()

    def await_latch(self, timeout: float | None = None) -> bool:
        with self._condition:
            endtime = time.time() + timeout if timeout is not None else None
            while self._count > 0:
                if timeout is not None:
                    remaining = endtime - time.time()
                    if remaining <= 0:
                        return False
                    self._condition.wait(timeout=remaining)
                else:
                    self._condition.wait()
            return True

    @property
    def count(self) -> int:
        with self._lock:
            return self._count

if __name__ == "__main__":
    latch = CountDownLatch(2)

    def worker():
        time.sleep(0.1)
        latch.countDown()

    threading.Thread(target=worker).start()
    threading.Thread(target=worker).start()

    assert latch.await_latch(timeout=1.0) == True
    print("Countdown latch test passed successfully.")
```

