```cpp
#include <atomic>
#include <cstddef>
#include <new>
#include <optional>
#include <vector>

template <typename T, size_t Capacity>
class SPSCRingBuffer {
private:
    static_assert(Capacity > 0, "Capacity must be greater than zero");

    // Align to hardware cache line size to prevent false sharing
    alignas(hardware_destructive_interference_size) std::atomic<size_t> m_head{0};
    alignas(hardware_destructive_interference_size) std::atomic<size_t> m_tail{0};

    // Storage for elements
    alignas(hardware_destructive_interference_size) T m_buffer[Capacity];

    size_t increment(size_t idx) const noexcept {
        return (idx + 1) % Capacity;
    }

public:
    SPSCRingBuffer() = default;
    ~SPSCRingBuffer() {
        // Drain remaining elements to ensure destructors are called correctly
        T dummy;
        while (try_pop(dummy));
    }

    SPSCRingBuffer(const SPSCRingBuffer&) = delete;
    SPSCRingBuffer& operator=(const SPSCRingBuffer&) = delete;
    SPSCRingBuffer(SPSCRingBuffer&&) = delete;
    SPSCRingBuffer& operator=(SPSCRingBuffer&&) = delete;

    bool try_push(const T& item) noexcept {
        const size_t current_tail = m_tail.load(std::memory_order_relaxed);
        const size_t current_head = m_head.load(std::memory_order_acquire);

        if (increment(current_tail) == current_head) {
            return false; // Buffer is full
        }

        m_buffer[current_tail] = item;
        m_tail.store(increment(current_tail), std::memory_order_release);
        return true;
    }

    bool try_push(T&& item) noexcept {
        const size_t current_tail = m_tail.load(std::memory_order_relaxed);
        const size_t current_head = m_head.load(std::memory_order_acquire);

        if (increment(current_tail) == current_head) {
            return false; // Buffer is full
        }

        m_buffer[current_tail] = std::move(item);
        m_tail.store(increment(current_tail), std::memory_order_release);
        return true;
    }

    bool try_pop(T& item) noexcept {
        const size_t current_head = m_head.load(std::memory_order_relaxed);
        const size_t current_tail = m_tail.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Buffer is empty
        }

        item = std::move(m_buffer[current_head]);
        m_head.store(increment(current_head), std::memory_order_release);
        return true;
    }

    [[nodiscard]] bool empty() const noexcept {
        return m_head.load(std::memory_order_acquire) == m_tail.load(std::memory_order_acquire);
    }

    [[nodiscard]] size_t size() const noexcept {
        size_t head = m_head.load(std::memory_order_acquire);
        size_t tail = m_tail.load(std::memory_order_acquire);
        if (tail >= head) {
            return tail - head;
        }
        return Capacity - (head - tail);
    }
};
```

