```cpp
#include <atomic>
#include <memory>
#include <optional>

template <typename T>
class TreiberStack {
private:
    struct Node {
        T data;
        Node* next;
        explicit Node(T&& val) : data(std::move(val)), next(nullptr) {}
    };

    struct TaggedNodePtr {
        Node* ptr;
        uint64_t tag;
    };

    // Using a 128-bit atomic if available on the platform, or packing pointer + tag
    // For broad portability, we utilize standard atomic struct where lock-free is checked.
    struct PackedPointer {
        Node* ptr;
        uintptr_t tag;
    };

    std::atomic<PackedPointer> m_head;

public:
    TreiberStack() noexcept {
        m_head.store({nullptr, 0}, std::memory_order_relaxed);
        static_assert(std::atomic<PackedPointer>::is_always_lock_free, "PackedPointer must be lock-free");
    }

    ~TreiberStack() {
        T dummy;
        while (try_pop(dummy));
    }

    TreiberStack(const TreiberStack&) = delete;
    TreiberStack& operator=(const TreiberStack&) = delete;
    TreiberStack(TreiberStack&&) = delete;
    TreiberStack& operator=(TreiberStack&&) = delete;

    void push(T item) {
        Node* new_node = new Node(std::move(item));
        PackedPointer old_head = m_head.load(std::memory_order_relaxed);

        do {
            new_node->next = old_head.ptr;
        } while (!m_head.compare_exchange_weak(
            old_head,
            PackedPointer{new_node, old_head.tag + 1},
            std::memory_order_release,
            std::memory_order_relaxed));
    }

    bool try_pop(T& item) {
        PackedPointer old_head = m_head.load(std::memory_order_acquire);

        do {
            if (old_head.ptr == nullptr) {
                return false;
            }
        } while (!m_head.compare_exchange_weak(
            old_head,
            PackedPointer{old_head.ptr->next, old_head.tag + 1},
            std::memory_order_acquire,
            std::memory_order_relaxed));

        std::unique_ptr<Node> guard(old_head.ptr);
        item = std::move(old_head.ptr->data);
        return true;
    }

    [[nodiscard]] bool empty() const noexcept {
        return m_head.load(std::memory_order_acquire).ptr == nullptr;
    }
};
