#include <atomic>
#include <vector>
#include <thread>
#include <memory>

class HazardPointerRegistry {
private:
    struct HazardNode {
        std::atomic<const void*> ptr{nullptr};
    };

    static constexpr size_t MAX_HAZARD_POINTERS = 64;
    inline static std::atomic<HazardNode> s_hazard_pointers[MAX_HAZARD_POINTERS];

public:
    class ScopedHazardPointer {
    private:
        size_t m_index;
    public:
        explicit ScopedHazardPointer(size_t index) : m_index(index) {}

        template <typename T>
        const T* protect(const std::atomic<const T*>& src) {
            const T* ptr;
            do {
                ptr = src.load(std::memory_order_acquire);
                HazardPointerRegistry::s_hazard_pointers[m_index].ptr.store(ptr, std::memory_order_release);
            } while (ptr != src.load(std::memory_order_acquire));
            return ptr;
        }

        ~ScopedHazardPointer() {
            HazardPointerRegistry::s_hazard_pointers[m_index].ptr.store(nullptr, std::memory_order_release);
        }
    };

    static size_t acquire_slot() {
        for (size_t i = 0; i < MAX_HAZARD_POINTERS; ++i) {
            const void* expected = nullptr;
            // Simple linear slot allocator for demonstration purposes
            if (s_hazard_pointers[i].ptr.compare_exchange_strong(expected, reinterpret_cast<void*>(1), std::memory_order_acq_rel)) {
                s_hazard_pointers[i].ptr.store(nullptr, std::memory_order_release);
                return i;
            }
        }
        throw std::runtime_error("Out of hazard pointer slots");
    }

    static bool is_protected(const void* ptr) {
        for (size_t i = 0; i < MAX_HAZARD_POINTERS; ++i) {
            if (s_hazard_pointers[i].ptr.load(std::memory_order_acquire) == ptr) {
                return true;
            }
        }
        return false;
    }
};
