```cpp
#include <atomic>
#include <cassert>
#include <iostream>
#include <memory>
#include <thread>
#include <vector>

template <typename T>
class TreiberStack {
private:
    struct Node {
        T data;
        Node* next;
        explicit Node(T val) : data(std::move(val)), next(nullptr) {}
    };

    std::atomic<Node*> head_{nullptr};

public:
    TreiberStack() = default;
    ~TreiberStack() {
        // Drain the stack to prevent memory leaks
        T dummy;
        while (pop(dummy));
    }

    TreiberStack(const TreiberStack&) = delete;
    TreiberStack& operator=(const TreiberStack&) = delete;

    void push(T item) {
        Node* new_node = new Node(std::move(item));
        new_node->next = head_.load(std::memory_order_relaxed);

        // CAS loop with release semantics on success and acquire on failure
        while (!head_.compare_exchange_weak(
            new_node->next,
            new_node,
            std::memory_order_release,
            std::memory_order_acquire))
        {
            // Loop body empty; compare_exchange_weak updates new_node->next on failure
        }
    }

    bool pop(T& result) {
        Node* old_head = head_.load(std::memory_order_acquire);

        while (old_head != nullptr) {
            Node* next_node = old_head->next;

            // Try to swing head to next_node using CAS
            if (head_.compare_exchange_weak(
                old_head,
                next_node,
                std::memory_order_release,
                std::memory_order_acquire))
            {
                result = std::move(old_head->data);
                delete old_head;
                return true;
            }
        }
        return false;
    }

    [[nodiscard]] bool empty() const noexcept {
        return head_.load(std::memory_order_acquire) == nullptr;
    }
};

int main() {
    TreiberStack<int> stack;

    std::cout << "Pushing items concurrently/sequentially...\n";
    stack.push(10);
    stack.push(20);
    stack.push(30);

    int val = 0;
    bool success = stack.pop(val);
    assert(success);
    assert(val == 30);
    std::cout << "Popped: " << val << "\n";

    success = stack.pop(val);
    assert(success);
    assert(val == 20);
    std::cout << "Popped: " << val << "\n";

    stack.push(40);

    success = stack.pop(val);
    assert(success);
    assert(val == 40);
    std::cout << "Popped: " << val << "\n";

    success = stack.pop(val);
    assert(success);
    assert(val == 10);
    std::cout << "Popped: " << val << "\n";

    assert(stack.empty());
    std::cout << "Stack is successfully emptied.\n";

    return 0;
}
