```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/epoll.h>

#define MAX_EVENTS 64
#define PORT 8080

static int make_socket_non_blocking(int sfd) {
    int flags = fcntl(sfd, F_GETFL, 0);
    if (flags == -1) {
        perror("fcntl F_GETFL");
        return -1;
    }
    if (fcntl(sfd, F_SETFL, flags | O_NONBLOCK) == -1) {
        perror("fcntl F_SETFL O_NONBLOCK");
        return -1;
    }
    return 0;
}

int main(void) {
    int sfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sfd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    int optval = 1;
    if (setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval)) == -1) {
        perror("setsockopt SO_REUSEADDR");
        close(sfd);
        exit(EXIT_FAILURE);
    }

    if (make_socket_non_blocking(sfd) == -1) {
        close(sfd);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(PORT);

    if (bind(sfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("bind");
        close(sfd);
        exit(EXIT_FAILURE);
    }

    if (listen(sfd, SOMAXCONN) == -1) {
        perror("listen");
        close(sfd);
        exit(EXIT_FAILURE);
    }

    int efd = epoll_create1(EPOLL_CLOEXEC);
    if (efd == -1) {
        perror("epoll_create1");
        close(sfd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN | EPOLLET;
    ev.data.fd = sfd;

    if (epoll_ctl(efd, EPOLL_CTL_ADD, sfd, &ev) == -1) {
        perror("epoll_ctl sfd");
        close(sfd);
        close(efd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event *events = calloc(MAX_EVENTS, sizeof(struct epoll_event));
    if (!events) {
        perror("calloc events");
        close(sfd);
        close(efd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d with epoll edge-triggered mode...\n", PORT);

    for (;;) {
        int n = epoll_wait(efd, events, MAX_EVENTS, -1);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < n; i++) {
            if ((events[i].events & EPOLLERR) ||
                (events[i].events & EPOLLHUP) ||
                (!(events[i].events & EPOLLIN))) {
                fprintf(stderr, "epoll error on fd %d\n", events[i].data.fd);
                close(events[i].data.fd);
                continue;
            }

            if (sfd == events[i].data.fd) {
                /* We have a notification on the listening socket, which means one or more incoming connections. */
                while (1) {
                    struct sockaddr in_addr;
                    socklen_t in_len = sizeof(in_addr);
                    int infd = accept(sfd, &in_addr, &in_len);
                    if (infd == -1) {
                        if (errno == EAGAIN || errno == EWOULDBLOCK) {
                            /* We have processed all incoming connections. */
                            break;
                        } else {
                            perror("accept");
                            break;
                        }
                    }

                    if (make_socket_non_blocking(infd) == -1) {
                        close(infd);
                        continue;
                    }

                    struct epoll_event peer_ev;
                    memset(&peer_ev, 0, sizeof(peer_ev));
                    peer_ev.events = EPOLLIN | EPOLLET | EPOLLONESHOT;
                    peer_ev.data.fd = infd;

                    if (epoll_ctl(efd, EPOLL_CTL_ADD, infd, &peer_ev) == -1) {
                        perror("epoll_ctl infd");
                        close(infd);
                        continue;
                    }
                    printf("Accepted new connection on fd %d\n", infd);
                }
            } else {
                /* Handle client data read */
                int client_fd = events[i].data.fd;
                char buf[512];
                int done = 0;

                while (1) {
                    ssize_t count = read(client_fd, buf, sizeof(buf));
                    if (count == -1) {
                        if (errno == EAGAIN || errno == EWOULDBLOCK) {
                            /* Read all data for this event cycle. Re-arm if EPOLLONESHOT used */
                            break;
                        } else {
                            perror("read");
                            done = 1;
                            break;
                        }
                    } else if (count == 0) {
                        /* End of file. The remote has closed the connection. */
                        done = 1;
                        break;
                    }

                    /* Echo data back or process it */
                    ssize_t written = write(client_fd, buf, count);
                    if (written == -1) {
                        perror("write");
                        done = 1;
                        break;
                    }
                }

                if (done) {
                    printf("Closed connection on fd %d\n", client_fd);
                    close(client_fd);
                } else {
                    /* Re-arm EPOLLONESHOT descriptor */
                    struct epoll_event mod_ev;
                    memset(&mod_ev, 0, sizeof(mod_ev));
                    mod_ev.events = EPOLLIN | EPOLLET | EPOLLONESHOT;
                    mod_ev.data.fd = client_fd;
                    if (epoll_ctl(efd, EPOLL_CTL_MOD, client_fd, &mod_ev) == -1) {
                        perror("epoll_ctl MOD");
                        close(client_fd);
                    }
                }
            }
        }
    }

    free(events);
    close(sfd);
    close(efd);
    return 0;
}
