```c
#include <unistd.h>
#include <errno.h>
#include <sys/epoll.h>
#include <sys/socket.h>

typedef struct {
    int fd;
    const char *buffer;
    size_t length;
    size_t offset;
} ConnectionState;

int write_to_socket(int efd, ConnectionState *state) {
    while (state->offset < state->length) {
        size_t remaining = state->length - state->offset;
        ssize_t nwritten = write(state->fd, state->buffer + state->offset, remaining);

        if (nwritten <= 0) {
            if (nwritten < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    /* 
                     * Kernel send buffer is full. We must register for EPOLLOUT
                     * to be notified when space becomes available again.
                     */
                    struct epoll_event ev;
                    ev.events = EPOLLOUT | EPOLLET | EPOLLONESHOT;
                    ev.data.ptr = state;
                    if (epoll_ctl(efd, EPOLL_CTL_MOD, state->fd, &ev) == -1) {
                        return -1;
                    }
                    return 0; // Partial write handled, pending space
                } else if (errno == EINTR) {
                    continue; // Interrupted system call, retry write
                } else {
                    return -1; // Fatal socket error
                }
            }
        } else {
            state->offset += nwritten;
        }
    }
    return 1; // Completed writing entire buffer
}
