    printf("Event loop running. Press Ctrl+C to terminate gracefully.\n");
    int running = 1;

    while (running) {
        struct epoll_event events[10];
        int n = epoll_wait(efd, events, 10, -1);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror(
                "epoll_wait"
