            break;
        }

        for (int i = 0; i < n; i++) {
            if (events[i].data.fd == sfd) {
                struct signalfd_siginfo si;
                ssize_t bytes = read(sfd, &si, sizeof(si));
                if (bytes != sizeof(si)) {
