#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/epoll.h>

int non_blocking_connect(const char *ip_str, int port, int timeout_ms) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        return -1;
    }

    int flags = fcntl(sockfd, F_GETFL, 0);
    if (flags == -1 || fcntl(sockfd, F_SETFL, flags | O_NONBLOCK) == -1) {
        close(sockfd);
        return -1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_str, &addr.sin_addr) <= 0) {
        close(sockfd);
        return -1;
    }

    int res = connect(sockfd, (struct sockaddr *)&addr, sizeof(addr));
    if (res < 0) {
        if (errno != EINPROGRESS) {
            close(sockfd);
            return -1;
        }
    } else {
        return sockfd; // Connected immediately
    }

    int efd = epoll_create1(EPOLL_CLOEXEC);
    if (efd == -1) {
        close(sockfd);
        return -1;
    }

    struct epoll_event ev;
    ev.events = EPOLLOUT | EPOLLET;
    ev.data.fd = sockfd;
    if (epoll_ctl(efd, EPOLL_CTL_ADD, sockfd, &ev) == -1) {
        close(efd);
        close(sockfd);
        return -1;
    }

    struct epoll_event events[1];
    int n = epoll_wait(efd, events, 1, timeout_ms);
    close(efd);

    if (n < 0) {
        close(sockfd);
        return -1;
    } else if (n == 0) {
        errno = ETIMEDOUT;
        close(sockfd);
        return -1;
    }

    int err = 0;
    socklen_t len = sizeof(err);
    if (getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &err, &len) < 0 || err != 0) {
        if (err != 0) {
            errno = err;
        }
        close(sockfd);
        return -1;
    }

    return sockfd;
}
```

