#include <stdio.h>
#include <unistd.h>
#include <sys/epoll.h>
#include <errno.h>
#include <fcntl.h>

int safe_epoll_add(int epoll_fd, int target_fd, uint32_t events) {
    if (epoll_fd < 0 || target_fd < 0) {
        errno = EINVAL;
        return -1;
    }

    int flags = fcntl(target_fd, F_GETFL, 0);
    if (flags == -1) {
        return -1;
    }
    if (!(flags & O_NONBLOCK)) {
        if (fcntl(target_fd, F_SETFL, flags | O_NONBLOCK) == -1) {
            return -1;
        }
    }

    struct epoll_event ev;
    ev.events = events;
    ev.data.fd = target_fd;

    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, target_fd, &ev) == -1) {
        if (errno == EEXIST) {
            if (epoll_ctl(epoll_fd, EPOLL_CTL_MOD, target_fd, &ev) == -1) {
                return -1;
            }
        } else {
            return -1;
        }
    }
    return 0;
}

int main(void) {
    int efd = epoll_create1(EPOLL_CLOEXEC);
    if (efd == -1) return 1;

    int fds[2];
    if (pipe(fds) == -1) {
        close(efd);
        return 1;
    }

    if (safe_epoll_add(efd, fds[0], EPOLLIN | EPOLLET) == -1) {
        perror("safe_epoll_add failed");
    } else {
        printf("Successfully registered fd safely with non-blocking guarantees.\n");
    }

    close(fds[0]);
    close(fds[1]);
    close(efd);
    return 0;
}
