    if (pipe(pipe1) == -1 || pipe(pipe2) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    set_nonblocking(pipe1[0]);
    set_nonblocking(pipe2[0]);

    int epoll_fd = epoll_create1(EPOLL_CLOEXEC);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        exit(EXIT_FAILURE);
    }

    struct epoll_event ev;
    ev.events = EPOLLIN | EPOLLET;
    ev.data.fd = pipe1[0];
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, pipe1[0], &ev);

    ev.data.fd = pipe2[0];
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, pipe2[0], &ev);

    write(pipe1[1], "Hello", 5);
    write(pipe2[1], "World", 5);

    struct epoll_event events[MAX_EVENTS];
    int active_pipes = 2;

    while (active_pipes > 0) {
        int n = epoll_wait(epoll_fd, events, MAX_EVENTS, 1000);
        if (n < 0) {
            if (errno == EINTR) continue;
            break;
        }

        for (int i = 0; i < n; i++) {
            int fd = events[i].data.fd;
            while (1) {
                char buf[16];
                ssize_t count = read(fd, buf, sizeof(buf) - 1);
                if (count == -1) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        break;
                    }
                    perror("read");
                    active_pipes--;
                    break;
                } else if (count == 0) {
                    active_pipes--;
                    break;
                }
                buf[count] = '\0';
                printf("Read from fd %d: %s\n", fd, buf);
            }
        }
    }

    close(pipe1[0]); close(pipe1[1]);
    close(pipe2[0]); close(pipe2[1]);
    close(epoll_fd);
    return 0;
}
