#include <pthread.h>
#include <errno.h>

#define NUM_THREADS 4

typedef struct {
    int epoll_fd;
    int thread_id;
} worker_arg_t;

void *worker_thread(void *arg) {
    worker_arg_t *warg = (worker_arg_t *)arg;
    struct epoll_event events[32];

    printf("Worker thread %d started, waiting on epoll_fd %d\n", warg->thread_id, warg->epoll_fd);

    while (1) {
        int n = epoll_wait(warg->epoll_fd, events, 32, -1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < n; i++) {
            printf("Worker thread %d woke up for fd %d\n", warg->thread_id, events[i].data.fd);
        }
    }
    return NULL;
}

int main(void) {
    int listen_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (listen_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    int epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event ev;
    ev.events = EPOLLIN | EPOLLEXCLUSIVE;
    ev.data.fd = listen_fd;

    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, listen_fd, &ev) == -1) {
        perror("epoll_ctl EPOLLEXCLUSIVE");
        close(listen_fd);
        close(epoll_fd);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[NUM_THREADS];
    worker_arg_t args[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        args[i].epoll_fd = epoll_fd;
        args[i].thread_id = i;
        pthread_create(&threads[i], NULL, worker_thread, &args[i]);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    close(listen_fd);
    close(epoll_fd);
    return 0;
}
