#include <stdio.h>
#include <unistd.h>
#include <sys/epoll.h>
#include <errno.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t lock;
    int epoll_fd;
    int socket_fd;
    int is_closed;
} connection_ctx_t;

int safe_close_and_deregister(connection_ctx_t *ctx) {
    if (!ctx) return -1;

    pthread_mutex_lock(&ctx->lock);

    if (ctx->is_closed) {
        pthread_mutex_unlock(&ctx->lock);
        return 0;
    }

    ctx->is_closed = 1;
    int efd = ctx->epoll_fd;
    int sfd = ctx->socket_fd;

    pthread_mutex_unlock(&ctx->lock);

    if (epoll_ctl(efd, EPOLL_CTL_DEL, sfd, NULL) == -1) {
        if (errno != ENOENT && errno != EBADF) {
            perror("epoll_ctl EPOLL_CTL_DEL");
        }
