#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define MAX_BUFFER 1024

typedef struct {
    char buffer[MAX_BUFFER];
    size_t len;
} client_stream_t;

int process_incoming_data(int fd, client_stream_t *stream) {
    while (1) {
        if (stream->len >= MAX_BUFFER - 1) {
            fprintf(stderr, "Buffer overflow vulnerability prevented\n");
            return -1;
        }

        ssize_t n = read(fd, stream->buffer + stream->len, MAX_BUFFER - 1 - stream->len);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                break;
            }
            perror("read");
            return -1;
        } else if (n == 0) {
            return 0;
        }

        stream->len += n;
        stream->buffer[stream->len] = '\0';

        char *line_end;
        while ((line_end = strchr(stream->buffer, '\n')) != NULL) {
            *line_end = '\0';
            printf("Complete message parsed: %s\n", stream->buffer);

            size_t remaining_offset = (line_end + 1) - stream->buffer;
            size_t leftover_len = stream->len - remaining_offset;
            memmove(stream->buffer, line_end + 1, leftover_len);
            stream->len = leftover_len;
            stream->buffer[stream->len] = '\0';
        }
    }
    return 1;
}

int main(void) {
    int pipe_fds[2];
    if (pipe(pipe_fds) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    client_stream_t stream;
    stream.len = 0;
    memset(stream.buffer, 0, MAX_BUFFER);

    const char *msg1 = "Hello ";
    const char *msg2 = "World!\nSecond ";
    const char *msg3 = "Message\n";

    write(pipe_fds[1], msg1, strlen(msg1));
    process_incoming_data(pipe_fds[0], &stream);

    write(pipe_fds[1], msg2, strlen(msg2));
    process_incoming_data(pipe_fds[0], &stream);

    write(pipe_fds[1], msg3, strlen(msg3));
    process_incoming_data(pipe_fds[0], &stream);

    close(pipe_fds[0]);
    close(pipe_fds[1]);
    return 0;
}
