    conn->read_offset = 0;
    conn->write_offset = 0;
    conn->write_len = 0;
    return conn;
}

void destroy_connection(connection_t *conn) {
    if (conn) {
        close(conn->fd);
        free(conn);
    }
}

int handle_read(connection_t *conn) {
    while (1) {
        ssize_t n = read(conn->fd, conn->read_buf + conn->read_offset, sizeof(conn->read_buf) - conn->read_offset);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return 0;
            }
            return -1;
        } else if (n == 0) {
            return 1;
        }
        conn->read_offset += n;
        conn->write_len = conn->read_offset;
        conn->read_offset = 0;
    }
}

int handle_write(connection_t *conn) {
    while (conn->write_offset < conn->write_len) {
        ssize_t n = write(conn->fd, conn->write_buf + conn->write_offset, conn->write_len - conn->write_offset);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return 0;
            }
            return -1;
        }
        conn->write_offset += n;
    }
    conn->write_offset = 0;
    conn->write_len = 0;
    return 0;
}

