```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/epoll.h>
#include <netinet/in.h>

#define PORT 9090
#define MAX_EVENTS 16

typedef enum {
    STATE_READING,
    STATE_WRITING,
    STATE_CLOSING
} ConnectionState;

typedef struct {
    int fd;
    ConnectionState state;
    char buffer[256];
    size_t bytes_read;
    size_t bytes_written;
} Connection;

int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags == -1) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

int main(void) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    set_nonblocking(server_fd);

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, SOMAXCONN) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    int epoll_fd = epoll_create1(EPOLL_CLOEXEC);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event ev;
    ev.events = EPOLLIN | EPOLLET;
    ev.data.fd = server_fd;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, server_fd, &ev);

    printf("State machine server listening on port %d...\n", PORT);
    struct epoll_event events[MAX_EVENTS];

    while (1) {
        int nfds = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);
        if (nfds < 0) {
            if (errno == EINTR) continue;
            break;
        }

        for (int i = 0; i < nfds; ++i) {
            if (events[i].data.fd == server_fd) {
                struct sockaddr_in client_addr;
                socklen_t client_len = sizeof(client_addr);
                int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
                if (client_fd >= 0) {
                    set_nonblocking(client_fd);
                    Connection *conn = malloc(sizeof(Connection));
                    conn->fd = client_fd;
                    conn->state = STATE_READING;
                    conn->bytes_read = 0;
                    conn->bytes_written = 0;
                    memset(conn->buffer, 0, sizeof(conn->buffer));

                    ev.events = EPOLLIN | EPOLLET;
                    ev.data.ptr = conn;
                    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, client_fd, &ev);
                }
            } else {
                Connection *conn = (Connection *)events[i].data.ptr;
                if (conn->state == STATE_READING) {
                    ssize_t n = read(conn->fd, conn->buffer + conn->bytes_read, sizeof(conn->buffer) - 1 - conn->bytes_read);
                    if (n < 0) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            conn->state = STATE_CLOSING;
                        }
                    } else if (n == 0) {
                        conn->state = STATE_CLOSING;
                    } else {
                        conn->bytes_read += n;
                        conn->state = STATE_WRITING;
                        ev.events = EPOLLOUT | EPOLLET;
                        ev.data.ptr = conn;
                        epoll_ctl(epoll_fd, EPOLL_CTL_MOD, conn->fd, &ev);
                    }
                } else if (conn->state == STATE_WRITING) {
                    ssize_t n = write(conn->fd, conn->buffer + conn->bytes_written, conn->bytes_read - conn->bytes_written);
                    if (n < 0) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            conn->state = STATE_CLOSING;
                        }
                    } else {
                        conn->bytes_written += n;
                        if (conn->bytes_written >= conn->bytes_read) {
                            conn->state = STATE_CLOSING;
                        }
                    }
                }

                if (conn->state == STATE_CLOSING) {
                    epoll_ctl(epoll_fd, EPOLL_CTL_DEL, conn->fd, NULL);
                    close(conn->fd);
                    free(conn);
                }
            }
        }
    }

    close(server_fd);
    close(epoll_fd);
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $O(1)$ operations per state transition event per socket descriptor.
- **Space Complexity**: $O(K)$ where $K$ is the number of active connection tracking state structures allocated dynamically on the heap.

Here is a fully functional binary buddy memory allocator implementation. It handles memory splitting, coalescing of adjacent buddy blocks, and powers-of-two block sizes.

```cpp
#include <iostream>
#include <cstdint>
#include <cstddef>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cassert>

class BuddyAllocator {
private:
    static constexpr int MIN_ORDER = 4; // Min block size = 2^4 = 16 bytes
    int max_order_;
    size_t total_size_;
    char* memory_pool_;

    struct BlockHeader {
        bool is_free;
        int order;
        BlockHeader* next;
        BlockHeader* prev;
    };

    std::vector<BlockHeader*> free_lists_;

    size_t order_to_size(int order) const {
        return static_cast<size_t>(1) << order;
    }

    void remove_from_free_list(BlockHeader* block, int order) {
        if (block->prev) {
            block->prev->next = block->next;
        } else {
            free_lists_[order] = block->next;
        }
        if (block->next) {
            block->next->prev = block->prev;
        }
        block->next = nullptr;
        block->prev = nullptr;
    }

    void add_to_free_list(BlockHeader* block, int order) {
        block->is_free = true;
        block->next = free_lists_[order];
        block->prev = nullptr;
        if (free_lists_[order]) {
            free_lists_[order]->prev = block;
        }
        free_lists_[order] = block;
    }

public:
    BuddyAllocator(int max_order)
        : max_order_(max_order) {
        total_size_ = order_to_size(max_order_);

        #if defined(_MSC_VER) || defined(__MINGW32__)
        memory_pool_ = static_cast<char*>(_aligned_malloc(total_size_, 64));
        #else
        int res = posix_memalign(reinterpret_cast<void**>(&memory_pool_), 64, total_size_);
        if (res != 0) memory_pool_ = nullptr;
        #endif

        if (!memory_pool_) {
            throw std::bad_alloc();
        }

        free_lists_.resize(max_order_ + 1, nullptr);

        // Initialize root block
        BlockHeader* root = reinterpret_cast<BlockHeader*>(memory_pool_);
        root->is_free = true;
        root->order = max_order_;
        root->next = nullptr;
        root->prev = nullptr;
        free_lists_[max_order_] = root;
    }

    ~BuddyAllocator() {
        if (memory_pool_) {
            #if defined(_MSC_VER) || defined(__MINGW32__)
            _aligned_free(memory_pool_);
            #else
            free(memory_pool_);
            #endif
        }
    }

    void* allocate(size_t size) {
        size_t total_needed = size + sizeof(BlockHeader);
        int target_order = MIN_ORDER;
        while (order_to_size(target_order) < total_needed && target_order <= max_order_) {
            target_order++;
        }

        if (target_order > max_order_) {
            return nullptr; // Requested size exceeds max block size
        }

        // Find smallest available block of order >= target_order
        int current_order = target_order;
        while (current_order <= max_order_ && free_lists_[current_order] == nullptr) {
            current_order++;
        }

        if (current_order > max_order_) {
            return nullptr; // Out of memory
        }

        // Extract block from free list
        BlockHeader* block = free_lists_[current_order];
        remove_from_free_list(block, current_order);

        // Split blocks down to target_order
        while (current_order > target_order) {
            current_order--;
            size_t half_size = order_to_size(current_order);

            BlockHeader* buddy = reinterpret_cast<BlockHeader*>(reinterpret_cast<char*>(block) + half_size);
            buddy->order = current_order;
            add_to_free_list(buddy, current_order);

            block->order = current_order;
        }

        block->is_free = false;
        return static_cast<void*>(reinterpret_cast<char*>(block) + sizeof(BlockHeader));
    }

    void deallocate(void* ptr) {
        if (!ptr) return;

        BlockHeader* block = reinterpret_cast<BlockHeader*>(static_cast<char*>(ptr) - sizeof(BlockHeader));
        if (block->is_free) {
            throw std::runtime_error(
                "Double-free or corruption detected in buddy allocator.");
        }

        int current_order = block->order;

        // Coalesce with buddies
        while (current_order < max_order_) {
            size_t block_size = order_to_size(current_order);
            uintptr_t relative_offset = reinterpret_cast<char*>(block) - memory_pool_;
            uintptr_t buddy_offset = relative_offset ^ block_size;

            BlockHeader* buddy = reinterpret_cast<BlockHeader*>(memory_pool_ + buddy_offset);

            // Check if buddy is free and of the same order
            if (buddy->is_free && buddy->order == current_order) {
                remove_from_free_list(buddy, current_order);
                if (buddy < block) {
                    block = buddy;
                }
                current_order++;
                block->order = current_order;
            } else {
                break;
            }
        }

        add_to_free_list(block, current_order);
    }
};

int main() {
    try {
        BuddyAllocator buddy(16); // 2^16 = 65536 bytes
        void* p1 = buddy.allocate(100);
        void* p2 = buddy.allocate(250);

        std::cout << "Allocated p1: " << p1 << "\n";
        std::cout << "Allocated p2: " << p2 << "\n";

        buddy.deallocate(p1);
        buddy.deallocate(p2);
        std::cout << "Successfully deallocated and coalesced buddy blocks.\n";
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(\log N)$ where $N$ is the max block order, bounded by splitting operations.
  - `deallocate()`: $\mathcal{O}(\log N)$ for iterative coalescing with adjacent buddies.
- **Space Complexity:** $\mathcal{O}(2^M)$ where $M$ is `max_order`, with embedded metadata headers inside every buddy block.

Here is a complete thread-safe pool allocator with chunk-based growth and explicit concurrency controls.

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <cstdint>
#include <cstddef>
#include <new>
#include <cstdlib>
#include <cassert>

class ThreadSafePoolAllocator {
private:
    struct Node {
        Node* next;
    };

    struct Chunk {
        void* memory;
        Chunk* next;
    };

    size_t block_size_;
    size_t blocks_per_chunk_;
    Node* free_list_;
    Chunk* chunk_list_;
    std::mutex mtx_;

    void allocate_new_chunk() {
        size_t actual_block_size = block_size_ < sizeof(Node) ? sizeof(Node) : block_size_;
        size_t chunk_bytes = actual_block_size * blocks_per_chunk_ + sizeof(Chunk);

        void* raw_mem = std::malloc(chunk_bytes);
        if (!raw_mem) {
            throw std::bad_alloc();
        }

        Chunk* new_chunk = reinterpret_cast<Chunk*>(raw_mem);
        new_chunk->memory = static_cast<void*>(reinterpret_cast<char*>(raw_mem) + sizeof(Chunk));
        new_chunk->next = chunk_list_;
        chunk_list_ = new_chunk;

        char* block_ptr = static_cast<char*>(new_chunk->memory);
        for (size_t i = 0; i < blocks_per_chunk_; ++i) {
            Node* node = reinterpret_cast<Node*>(block_ptr + (i * actual_block_size));
            node->next = free_list_;
            free_list_ = node;
        }
    }

public:
    ThreadSafePoolAllocator(size_t block_size, size_t blocks_per_chunk)
        : block_size_(block_size), blocks_per_chunk_(blocks_per_chunk), free_list_(nullptr), chunk_list_(nullptr) {
        allocate_new_chunk();
    }

    ~ThreadSafePoolAllocator() {
        std::lock_guard<std::mutex> lock(mtx_);
        Chunk* current = chunk_list_;
        while (current != nullptr) {
            Chunk* next = current->next;
            std::free(current);
            current = next;
        }
    }

    void* allocate() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (free_list_ == nullptr) {
            allocate_new_chunk();
        }

        Node* node = free_list_;
        free_list_ = free_list_->next;
        return static_cast<void*>(node);
    }

    void deallocate(void* ptr) {
        if (!ptr) return;

        std::lock_guard<std::mutex> lock(mtx_);
        Node* node = reinterpret_cast<Node*>(ptr);
        node->next = free_list_;
        free_list_ = node;
    }
};

int main() {
    ThreadSafePoolAllocator pool(64, 16);
    void* p1 = pool.allocate();
    std::cout << "Allocated block: " << p1 << "\n";
    pool.deallocate(p1);
    std::cout << "Deallocated block successfully.\n";
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(1)$ amortized (acquiring mutex lock, popping head, or triggering chunk allocation).
  - `deallocate()`: $\mathcal{O}(1)$ (acquiring mutex lock and pushing to head).
- **Space Complexity:** $\mathcal{O}(C \times B)$ where $C$ is the number of dynamically allocated chunks and $B$ is the chunk size.

