    SimpleSlabBackend(size_t block_size, size_t num_blocks)
        : block_size_(block_size < sizeof(Node) ? sizeof(Node) : block_size),
          num_blocks_(num_blocks) {
        arena_ = static_cast<char*>(std::malloc(block_size_ * num_blocks_));
        if (!arena_) throw std::bad_alloc();

        free_list_ = reinterpret_cast<Node*>(arena_);
        Node* curr = free_list_;
        for (size_t i = 0; i < num_blocks_ - 1; ++i) {
            curr->next = reinterpret_cast<Node*>(arena_ + (i + 1) * block_size_);
            curr = curr->next;
        }
        curr->next = nullptr;
    }

    ~SimpleSlabBackend() {
        std::free(arena_);
    }

    void* allocate() {
        if (!free_list_) throw std::bad_alloc();
        Node* node = free_list_;
        free_list_ = free_list_->next;
        return node;
    }

    void deallocate(void* ptr) {
        Node* node = reinterpret_cast<Node*>(ptr);
        node->next = free_list_;
        free_list_ = node;
    }
};

template <typename T>
class SlabAllocatorAdapter {
private:
    std::shared_ptr<SimpleSlabBackend> backend_;

public:
    using value_type = T;

    template <typename U>
    struct rebind {
        using other = SlabAllocatorAdapter<U>;
    };

    explicit SlabAllocatorAdapter(std::shared_ptr<SimpleSlabBackend> backend)
        : backend_(backend) {}

    template <typename U>
    SlabAllocatorAdapter(const SlabAllocatorAdapter<U>& other) noexcept
        : backend_(other.backend()) {}

    T* allocate(size_t n) {
        if (n != 1) {
            // Fallback to standard allocation for multi-element requests
            return static_cast<T*>(::operator new(n * sizeof(T)));
        }
        return static_cast<T*>(backend_->allocate());
    }

    void deallocate(T* p, size_t n) noexcept {
        if (n != 1 || !p) {
            ::operator delete(p);
            return;
        }
        backend_->deallocate(static_cast<void*>(p));
    }

    std::shared_ptr<SimpleSlabBackend> backend() const noexcept {
        return backend_;
    }
};

template <typename T, typename U>
bool operator==(const SlabAllocatorAdapter<T>& a, const SlabAllocatorAdapter<U>& b) noexcept {
    return a.backend() == b.backend();
}

template <typename T, typename U>
bool operator!=(const SlabAllocatorAdapter<T>& a, const SlabAllocatorAdapter<U>& b) noexcept {
    return !(a == b);
}

