Here is a complete, production-ready implementation of a memory arena allocator in C++ with 64-byte cache-line alignment.

```cpp
#cstdlib>
#cstdint>
#cstring>
#iostream>
#cassert>

class ArenaAllocator {
private:
    uint8_t* buffer;
    size_t capacity;
    size_t offset;

    static constexpr size_t CACHE_LINE_SIZE = 64;

    static size_t align_forward(size_t ptr, size_t alignment) {
        size_t modulo = ptr & (alignment - 1);
        if (modulo != 0) {
            ptr += (alignment - modulo);
        }
        return ptr;
    }

public:
    explicit ArenaAllocator(size_t total_size) 
        : capacity(total_size), offset(0) {
        // Allocate buffer with alignment padding
        int result = posix_memalign(reinterpret_cast<void**>(&buffer), CACHE_LINE_SIZE, capacity);
        if (result != 0 || buffer == nullptr) {
            throw std::bad_alloc();
        }
        std::memset(buffer, 0, capacity);
    }

    ~ArenaAllocator() {
        if (buffer != nullptr) {
            free(buffer);
            buffer = nullptr;
        }
    }

    // Delete copy constructors to prevent double frees
    ArenaAllocator(const ArenaAllocator&) = delete;
    ArenaAllocator& operator=(const ArenaAllocator&) = delete;

    // Allow move semantics
    ArenaAllocator(ArenaAllocator&& other) noexcept 
        : buffer(other.buffer), capacity(other.capacity), offset(other.offset) {
        other.buffer = nullptr;
        other.capacity = 0;
        other.offset = 0;
    }

    ArenaAllocator& operator=(ArenaAllocator&& other) noexcept {
        if (this != &other) {
            if (buffer) {
                free(buffer);
            }
            buffer = other.buffer;
            capacity = other.capacity;
            offset = other.offset;
            other.buffer = nullptr;
            other.capacity = 0;
            other.offset = 0;
        }
        return this;
    }

    template <typename T, typename... Args>
    T* allocate(Args&&... args) {
        size_t size = sizeof(T);
        size_t align = alignof(T);

        if (align < CACHE_LINE_SIZE) {
            align = CACHE_LINE_SIZE;
        }

        uint8_t* current_address = buffer + offset;
        size_t current_ptr_val = reinterpret_cast<size_t>(current_address);
        size_t aligned_ptr_val = align_forward(current_ptr_val, align);
        size_t padding = aligned_ptr_val - current_ptr_val;

        if (offset + padding + size > capacity) {
            throw std::bad_alloc();
        }

        offset += padding + size;
        T* obj_ptr = reinterpret_cast<T*>(aligned_ptr_val);

        // Construct object in-place via placement new
        return new (obj_ptr) T(std::forward<Args>(args)...);
    }

    void reset() noexcept {
        offset = 0;
    }

    size_t get_used_memory() const noexcept {
        return offset;
    }

    size_t get_capacity() const noexcept {
        return capacity;
    }
};

int main() {
    try {
        ArenaAllocator arena(1024 * 1024); // 1 MB Arena
        int* x = arena.allocate<int>(42);
        double* y = arena.allocate<double>(3.14159);

        std::cout << "Allocated int: " << *x << " at address: " << x << std::endl;
        std::cout << "Allocated double: " << *y << " at address: " << y << std::endl;
        std::cout << "Used memory: " << arena.get_used_memory() << " bytes\n";

        arena.reset();
        std::cout << "After reset, used memory: " << arena.get_used_memory() << " bytes\n";
    } catch (const std::exception& e) {
        std::cerr << "Allocation failed: " << e.what() << std::endl;
    }
    return 0;
}
