  - `reset()`: $\mathcal{O}(1)$ as it simply resets the internal offset counter to zero without individual deallocations.
- **Space Complexity**: $\mathcal{O}(N)$ where $N$ is the fixed `total_size` allocated at initialization. Zero auxiliary heap metadata overhead per allocation.

Here is a complete, production-ready Slab Allocator written in C with zero metadata overhead via an intrusive free-list.

```c
#stdio.h>
#stdlib.h>
#stdint.h>
#string.h>
#assert.h>

typedef struct SlabNode {
    struct SlabNode* next;
} SlabNode;

typedef struct {
    size_t object_size;
    size_t objects_per_slab;
    void* memory_block;
    SlabNode* free_list;
} SlabAllocator;

SlabAllocator* slab_create(size_t obj_size, size_t num_objects) {
    if (obj_size < sizeof(SlabNode)) {
        obj_size = sizeof(SlabNode);
    }

    // Ensure 64-byte alignment for the objects
    size_t alignment = 64;
    size_t total_size = obj_size * num_objects + alignment;

    SlabAllocator* allocator = (SlabAllocator*)malloc(sizeof(SlabAllocator));
    if (!allocator) return NULL;

    void* raw_mem = NULL;
    if (posix_memalign(&raw_mem, alignment, total_size) != 0) {
        free(allocator);
        return NULL;
    }

    allocator->object_size = obj_size;
    allocator->objects_per_slab = num_objects;
    allocator->memory_block = raw_mem;
    allocator->free_list = (SlabNode*)raw_mem;

    // Initialize the intrusive free list
    SlabNode* current = allocator->free_list;
    for (size_t i = 0; i < num_objects - 1; ++i) {
        SlabNode* next_node = (SlabNode*)((uint8_t*)current + obj_size);
        current->next = next_node;
        current = next_node;
    }
    current->next = NULL;

    return allocator;
}

void* slab_alloc(SlabAllocator* allocator) {
    if (!allocator || !allocator->free_list) {
        return NULL; // Out of memory
    }

    SlabNode* node = allocator->free_list;
    allocator->free_list = node->next;
    return (void*)node;
}

void slab_free(SlabAllocator* allocator, void* ptr) {
    if (!allocator || !ptr) return;

    // Boundary validation check
    uint8_t* start = (uint8_t*)allocator->memory_block;
    uint8_t* end = start + (allocator->object_size * allocator->objects_per_slab);
    uint8_t* target = (uint8_t*)ptr;

    assert(target >= start && target < end);

    SlabNode* node = (SlabNode*)ptr;
    node->next = allocator->free_list;
    allocator->free_list = node;
}

void slab_destroy(SlabAllocator* allocator) {
    if (!allocator) return;
    free(allocator->memory_block);
    free(allocator);
}

int main() {
    SlabAllocator* allocator = slab_create(sizeof(int), 10);
    if (!allocator) {
        fprintf(stderr, "Failed to create slab allocator\n");
        return 1;
    }

    int* p1 = (int*)slab_alloc(allocator);
    int* p2 = (int*)slab_alloc(allocator);

    *p1 = 100;
    *p2 = 200;

    printf("p1: %d, p2: %d\n", *p1, *p2);

    slab_free(allocator, p1);
    int* p3 = (int*)slab_alloc(allocator);
    printf("p3 (reused p1 slot): %d\n", *p3);

    slab_destroy(allocator);
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `slab_alloc()`: $\mathcal{O}(1)$ as it pops the head of the intrusive free-list.
  - `slab_free()`: $\mathcal{O}(1)$ as it pushes the returned pointer back onto the head of the free-list.
- **Space Complexity**: $\mathcal{O}(M)$ where $M$ is the pre-allocated chunk size. Metadata storage overhead is $0$ extra bytes per allocation because pointers reuse the memory of unallocated payload blocks.

Here is a complete, production-ready Binary Buddy Memory Allocator in C++ handling splitting, merging, and binary block alignments.

```cpp
#iostream>
#vector>
#cmath>
#cstdint>
#cassert>

class BuddyAllocator {
private:
    size_t total_size;
    size_t min_block_size;
    int max_order;
    std::vector<std::vector<void*>> free_blocks;
    uint8_t* memory_pool;

    int size_to_order(size_t size) const {
        size_t s = min_block_size;
        int order = 0;
        while (s < size && s < total_size) {
            s <<= 1;
            order++;
        }
        return order;
    }

    size_t order_to_size(int order) const {
        return min_block_size << order;
    }

    size_t get_offset(void* ptr) const {
        return static_cast<size_t>(static_cast<uint8_t*>(ptr) - memory_pool);
    }

public:
    BuddyAllocator(size_t total_memory, size_t min_block)
        : total_size(total_memory), min_block_size(min_block) {
        assert((total_size & (total_size - 1)) == 0 && "Total size must be power of two");
        assert((min_block_size & (min_block_size - 1)) == 0 && "Min block must be power of two");

        max_order = 0;
        size_t temp = total_size / min_block_size;
        while (temp > 1) {
            temp >>= 1;
            max_order++;
        }

        memory_pool = static_cast<uint8_t*>(aligned_alloc(total_size, total_size));
        assert(memory_pool != nullptr);

        free_blocks.resize(max_order + 1);
        free_blocks[max_order].push_back(memory_pool);
    }

    ~BuddyAllocator() {
        free(memory_pool);
    }

    void* allocate(size_t size) {
        int target_order = size_to_order(size);
        if (target_order > max_order) return nullptr;

        int current_order = target_order;
        while (current_order <= max_order && free_blocks[current_order].empty()) {
            current_order++;
        }

        if (current_order > max_order) return nullptr; // Out of memory

        void* block = free_blocks[current_order].back();
        free_blocks[current_order].pop_back();

        while (current_order > target_order) {
            current_order--;
            size_t half_size = order_to_size(current_order);
            void* buddy = static_cast<void*>(static_cast<uint8_t*>(block) + half_size);
            free_blocks[current_order].push_back(buddy);
        }

        return block;
    }

    void deallocate(void* ptr, size_t size) {
        if (!ptr) return;
        int target_order = size_to_order(size);
        size_t block_size = order_to_size(target_order);

        size_t offset = get_offset(ptr);

        while (target_order < max_order) {
            size_t buddy_offset = offset ^ block_size;
            void* buddy_ptr = memory_pool + buddy_offset;

            auto& list = free_blocks[target_order];
            auto it = std::find(list.begin(), list.end(), buddy_ptr);

            if (it == list.end()) {
                break; // Buddy is not free, stop coalescing
            }

            // Remove buddy from free list and merge
            list.erase(it);
            if (buddy_offset < offset) {
                ptr = buddy_ptr;
                offset = buddy_offset;
            }
            target_order++;
            block_size <<= 1;
        }

        free_blocks[target_order].push_back(ptr);
    }
};

int main() {
    BuddyAllocator buddy(1024, 32);
    void* p1 = buddy.allocate(64);
    void* p2 = buddy.allocate(64);

    std::cout << "Allocated p1: " << p1 << " and p2: " << p2 << std::endl;

    buddy.deallocate(p1, 64);
    buddy.deallocate(p2, 64);
    std::cout << "Successfully deallocated and coalesced blocks back.\n";
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `allocate()`: $\mathcal{O}(\log N)$ where $N$ is the number of total minimum blocks due to recursive splitting.
  - `deallocate()`: $\mathcal{O}(\log N)$ due to iterative coalescing scans against buddy slots.
- **Space Complexity**: $\mathcal{O}(N)$ for the underlying binary tree block space, plus minimal overhead vectors for storing free lists per order.

