class ThreadSafeMemoryPool {
private:
    struct Node {
        Node* next;
    };

    size_t block_size;
    size_t pool_size;
    uint8_t* memory_block;
    Node* free_list;
    std::mutex mutex;

public:
    ThreadSafeMemoryPool(size_t chunk_size, size_t num_chunks)
        : block_size(chunk_size < sizeof(Node) ? sizeof(Node) : chunk_size), 
          pool_size(num_chunks) {

        size_t total_bytes = block_size * pool_size;
        memory_block = static_cast<uint8_t*>(aligned_alloc(64, total_bytes));
        assert(memory_block != nullptr);

        free_list = reinterpret_cast<Node*>(memory_block);
        Node* current = free_list;

        for (size_t i = 0; i < pool_size - 1; ++i) {
            Node* next_node = reinterpret_cast<Node*>(reinterpret_cast<uint8_t*>(current) + block_size);
            current->next = next_node;
            current = next_node;
        }
        current->next = nullptr;
    }

    ~ThreadSafeMemoryPool() {
        free(memory_block);
    }

    ThreadSafeMemoryPool(const ThreadSafeMemoryPool&) = delete;
    ThreadSafeMemoryPool& operator=(const ThreadSafeMemoryPool&) = delete;

    void* allocate() {
        std::lock_guard<std::mutex> lock(mutex);
        if (free_list == nullptr) {
            return nullptr;
        }

        Node* node = free_list;
        free_list = free_list->next;
        return static_cast<void*>(node);
    }

    void deallocate(void* ptr) {
        if (ptr == nullptr) return;

        std::lock_guard<std::mutex> lock(mutex);
        Node* node = reinterpret_cast<Node*>(ptr);
        node->next = free_list;
        free_list = node;
    }
};

