Here is a complete, production-ready Free List Allocator in C++ implementing first-fit search policies and dynamic coalescing.

```cpp
#iostream>
#cstdint>
#cstring>
#cassert>

class FreeListAllocator {
private:
    struct Header {
        size_t size;
        bool is_free;
        Header* next;
        Header* prev;
    };

    uint8_t* memory_pool;
    size_t total_capacity;
    Header* head;

public:
    FreeListAllocator(size_t capacity) : total_capacity(capacity) {
        memory_pool = static_cast<uint8_t*>(aligned_alloc(64, total_capacity));
        assert(memory_pool != nullptr);

        head = reinterpret_cast<Header*>(memory_pool);
        head->size = total_capacity - sizeof(Header);
        head->is_free = true;
        head->next = nullptr;
        head->prev = nullptr;
    }

    ~FreeListAllocator() {
        free(memory_pool);
    }

    void* allocate(size_t size) {
        Header* current = head;
        while (current != nullptr) {
            if (current->is_free && current->size >= size) {
                // Split block if remaining space is sufficient for a new header and payload
                if (current->size >= size + sizeof(Header) + 8) {
                    Header* next_block = reinterpret_cast<Header*>(
                        reinterpret_cast<uint8_t*>(current) + sizeof(Header) + size
                    );
                    next_block->size = current->size - size - sizeof(Header);
                    next_block->is_free = true;
                    next_block->next = current->next;
                    next_block->prev = current;

                    if (current->next) {
                        current->next->prev = next_block;
                    }
                    current->next = next_block;
                    current->size = size;
                }
                current->is_free = false;
                return reinterpret_cast<void*>(reinterpret_cast<uint8_t*>(current) + sizeof(Header));
            }
            current = current->next;
        }
        return nullptr; // Out of memory
    }

    void deallocate(void* ptr) {
        if (!ptr) return;

        Header* header = reinterpret_cast<Header*>(reinterpret_cast<uint8_t*>(ptr) - sizeof(Header));
        header->is_free = true;

        // Coalesce with next block if free
        if (header->next && header->next->is_free) {
            header->size += sizeof(Header) + header->next->size;
            header->next = header->next->next;
            if (header->next) {
                header->next->prev = header;
            }
        }

        // Coalesce with previous block if free
        if (header->prev && header->prev->is_free) {
            header->prev->size += sizeof(Header) + header->size;
            header->prev->next = header->next;
            if (header->next) {
                header->next->prev = header->prev;
            }
        }
    }
};

