Here is the complete implementation of a high-performance Fixed-Size Slab Allocator in C++.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cassert>

template <typename T, size_t ObjectsPerSlab = 64>
class SlabAllocator {
private:
    union Slot {
        Slot* next;
        alignas(T) char storage[sizeof(T)];
    };

    struct Slab {
        Slot slots[ObjectsPerSlab];
        Slab* next;
    };

    Slab* head_slab_;
    Slot* free_list_;

    void allocate_slab() {
        Slab* new_slab = new Slab();
        new_slab->next = head_slab_;
        head_slab_ = new_slab;

        for (size_t i = 0; i < ObjectsPerSlab; ++i) {
            new_slab->slots[i].next = free_list_;
            free_list_ = &new_slab->slots[i];
        }
    }

public:
    SlabAllocator() : head_slab_(nullptr), free_list_(nullptr) {
        static_assert(sizeof(T) >= sizeof(Slot*), "Object size must be at least the size of a pointer for free list.");
        allocate_slab();
    }

    ~SlabAllocator() {
        Slab* current = head_slab_;
        while (current != nullptr) {
            Slab* next = current->next;
            delete current;
            current = next;
        }
    }

    SlabAllocator(const SlabAllocator&) = delete;
    SlabAllocator& operator=(const SlabAllocator&) = delete;

    template <typename... Args>
    T* allocate(Args&&... args) {
        if (free_list_ == nullptr) {
            allocate_slab();
        }

        Slot* slot = free_list_;
        free_list_ = free_list_->next;

        T* memory = reinterpret_cast<T*>(slot->storage);
        return ::new (static_cast<void*>(memory)) T(std::forward<Args>(args)...);
    }

    void deallocate(T* ptr) {
        if (ptr == nullptr) return;

        ptr->~T();
        Slot* slot = reinterpret_cast<Slot*>(ptr);
        slot->next = free_list_;
        free_list_ = slot;
    }
};

struct Node {
    int id;
    double value;
    Node(int i, double v) : id(i), value(v) {}
};

int main() {
    SlabAllocator<Node, 4> allocator;
    Node* n1 = allocator.allocate(1, 3.14);
    Node* n2 = allocator.allocate(2, 6.28);

    std::cout << "Node 1: " << n1->id << ", " << n1->value << std::endl;
    std::cout << "Node 2: " << n2->id << ", " << n2->value << std::endl;

    allocator.deallocate(n1);
    Node* n3 = allocator.allocate(3, 9.42);
    std::cout << "Node 3: " << n3->id << ", " << n3->value << std::endl;

    allocator.deallocate(n2);
    allocator.deallocate(n3);
    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(1)$ amortized. ( $\mathcal{O}(N)$ worst-case only when a new slab must be allocated via the underlying OS/heap).
  - `deallocate()`: $\mathcal{O}(1)$ strict. Insertion into the head of the intrusive free list is a constant-time pointer swap.
- **Space Complexity:** $\mathcal{O}(N)$ where $N$ is the number of active and previously allocated objects retained in memory slabs. Memory overhead is minimized by overlaying the intrusive free list directly inside unallocated object memory via a `union`.

