#include <algorithm>
#include <cassert>

class MemoryArena {
private:
    struct Block {
        std::unique_ptr<char[]> memory;
        size_t capacity;
        size_t offset;

        Block(size_t cap) : memory(std::make_unique<char[]>(cap)), capacity(cap), offset(0) {}
    };

    size_t default_block_size_;
    std::vector<std::unique_ptr<Block>> blocks_;
    size_t current_block_index_;

    void add_block(size_t min_capacity) {
        size_t cap = std::max(default_block_size_, min_capacity);
        blocks_.push_back(std::make_unique<Block>(cap));
        current_block_index_ = blocks_.size() - 1;
    }

public:
    struct Checkpoint {
        size_t block_index;
        size_t block_offset;
    };

    explicit MemoryArena(size_t default_block_size = 4096) 
        : default_block_size_(default_block_size), current_block_index_(0) {
        blocks_.push_back(std::make_unique<Block>(default_block_size_));
    }

    ~MemoryArena() = default;

    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;

    void* allocate(size_t size, size_t alignment = alignof(std::max_align_t)) {
        assert(size > 0);

        Block* current = blocks_[current_block_index_].get();

        uintptr_t current_address = reinterpret_cast<uintptr_t>(current->memory.get() + current->offset);
        size_t adjustment = (alignment - (current_address % alignment)) % alignment;

        size_t total_needed = size + adjustment;

        if (current->offset + total_needed > current->capacity) {
            add_block(total_needed);
            current = blocks_[current_block_index_].get();
            current_address = reinterpret_cast<uintptr_t>(current->memory.get());
            adjustment = (alignment - (current_address % alignment)) % alignment;
            total_needed = size + adjustment;
            assert(current->offset + total_needed <= current->capacity && "Allocation exceeds maximum block capacity");
        }

        current->offset += adjustment;
        void* ptr = static_cast<void*>(current->memory.get() + current->offset);
        current->offset += size;
        return ptr;

    }

    Checkpoint get_checkpoint() const {
        return Checkpoint{current_block_index_, blocks_[current_block_index_]->offset};
    }

    void rollback(const Checkpoint& cp) {
        assert(cp.block_index < blocks_.size());
        assert(cp.block_offset <= blocks_[cp.block_index]->capacity);

        current_block_index_ = cp.block_index;
        blocks_[current_block_index_]->offset = cp.block_offset;

        for (size_t i = current_block_index_ + 1; i < blocks_.size(); ++i) {
            blocks_[i]->offset = 0;
        }
    }

    void reset() {
        current_block_index_ = 0;
        for (auto& block : blocks_) {
            block->offset = 0;
        }
    }
};

int main() {
    MemoryArena arena(1024);

    int* a = new (arena.allocate(sizeof(int), alignof(int))) int(42);
    double* b = new (arena.allocate(sizeof(double), alignof(double))) double(3.14159);

    std::cout << "a: " << *a << ", b: " << *b << std::endl;

    MemoryArena::Checkpoint cp = arena.get_checkpoint();

    int* c = new (arena.allocate(sizeof(int))) int(100);
    std::cout << "c (before rollback): " << *c << std::endl;

    arena.rollback(cp);

    int* d = new (arena.allocate(sizeof(int))) int(200);
    std::cout << "d (after rollback, overwriting c's region): " << *d << std::endl;

    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(1)$ amortized and bounds-checked. Incrementing a bump pointer with alignment calculations takes exact constant time, requiring block allocation only on capacity overflow.
  - `rollback()` / `reset()`: $\mathcal{O}(1)$ or $\mathcal{O}(K)$ where $K$ is the total number of allocated blocks being reset. Zero individual destructor or free calls are executed.
- **Space Complexity:** $\mathcal{O}(M)$ where $M$ is the cumulative capacity of all allocated memory blocks. Memory overhead is strictly minimal with zero per-object header footprint.

Here is the complete implementation of a cache-line aligned Pool Allocator in C++.

```cpp
#include <iostream>
#include <cstdint>
#include <cassert>
#include <new>

template <typename T, size_t PoolSize = 1024, size_t Alignment = 64>
class CacheAlignedPoolAllocator {
private:
    struct Node {
        Node* next;
        alignas(T) char storage[sizeof(T)];
    };

    struct Chunk {
        alignas(Alignment) char memory[sizeof(Node) * PoolSize];
        Chunk* next;
    };

    Chunk* head_chunk_;
    Node* free_list_;

    void allocate_chunk() {
        Chunk* new_chunk = new Chunk();
        new_chunk->next = head_chunk_;
        head_chunk_ = new_chunk;

        for (size_t i = 0; i < PoolSize; ++i) {
            Node* node = reinterpret_cast<Node*>(&new_chunk->memory[i * sizeof(Node)]);
            node->next = free_list_;
            free_list_ = node;
        }
    }

public:
    CacheAlignedPoolAllocator() : head_chunk_(nullptr), free_list_(nullptr) {
        static_assert(Alignment >= alignof(void*), "Alignment must accommodate a pointer");
        allocate_chunk();
    }

    ~CacheAlignedPoolAllocator() {
        Chunk* current = head_chunk_;
        while (current != nullptr) {
            Chunk* next = current->next;
            delete current;
            current = next;
        }
    }

    template <typename... Args>
    T* allocate(Args&&... args) {
        if (free_list_ == nullptr) {
            allocate_chunk();
        }

        Node* node = free_list_;
        free_list_ = free_list_->next;

        T* obj_ptr = reinterpret_cast<T*>(node->storage);
        assert(reinterpret_cast<uintptr_t>(obj_ptr) % Alignment == 0 && "Allocation fails cache-line alignment guarantee");
        return ::new (static_cast<void*>(obj_ptr)) T(std::forward<Args>(args)...);
    }

    void deallocate(T* ptr) {
        if (ptr == nullptr) return;
        ptr->~T();

        Node* node = reinterpret_cast<Node*>(reinterpret_cast<char*>(ptr) - offsetof(Node, storage));
        node->next = free_list_;
        free_list_ = node;
    }
};

struct alignas(64) WorkerTask {
    uint64_t task_id;
    uint32_t priority;
    WorkerTask(uint64_t id, uint32_t p) : task_id(id), priority(p) {}
};

int main() {
    CacheAlignedPoolAllocator<WorkerTask, 16, 64> pool;
    WorkerTask* t1 = pool.allocate(101, 1);
    WorkerTask* t2 = pool.allocate(102, 2);

    std::cout << "Task 1 ID: " << t1->task_id << " Address: " << t1 << std::endl;
    std::cout << "Task 2 ID: " << t2->task_id << " Address: " << t2 << std::endl;

    pool.deallocate(t1);
    pool.deallocate(t2);
    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(1)$ strict amortized. Free list pointer pops execute in constant time.
  - `deallocate()`: $\mathcal{O}(1)$ strict. Intrusive pointer links are restored instantly.
- **Space Complexity:** $\mathcal{O}(P)$ where $P$ is the total capacity allocated across chunks. Alignment padding introduces minimal predetermined footprint overhead.

Here is the complete implementation of a segregated free list memory allocator in C++.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cassert>

class SegregatedAllocator {
private:
    struct BlockHeader {
        size_t size;
        bool is_free;
        BlockHeader* next;
    };

    std::vector<char> memory_pool_;
    BlockHeader* free_list_head_;

public:
    explicit SegregatedAllocator(size_t pool_size) 
        : memory_pool_(pool_size), free_list_head_(nullptr) {
        assert(pool_size > sizeof(BlockHeader));

        free_list_head_ = reinterpret_cast<BlockHeader*>(memory_pool_.data());
        free_list_head_->size = pool_size - sizeof(BlockHeader);
        free_list_head_->is_free = true;
        free_list_head_->next = nullptr;
    }

    void* allocate(size_t size) {
        BlockHeader* current = free_list_head_;
        while (current != nullptr) {
            if (current->is_free && current->size >= size) {
                if (current->size >= size + sizeof(BlockHeader) + 8) {
                    BlockHeader* new_block = reinterpret_cast<BlockHeader*>(
                        reinterpret_cast<char*>(current) + sizeof(BlockHeader) + size
                    );
                    new_block->size = current->size - size - sizeof(BlockHeader);
                    new_block->is_free = true;
                    new_block->next = current->next;

                    current->size = size;
                    current->next = new_block;
                }
                current->is_free = false;
                return reinterpret_cast<void*>(reinterpret_cast<char*>(current) + sizeof(BlockHeader));
            }
            current = current->next;
        }
        return nullptr;
    }

    void deallocate(void* ptr) {
        if (ptr == nullptr) return;
        BlockHeader* header = reinterpret_cast<BlockHeader*>(
            reinterpret_cast<char*>(ptr) - sizeof(BlockHeader)
        );
        header->is_free = true;
    }
};

int main() {
    SegregatedAllocator allocator(4096);
    void* p1 = allocator.allocate(128);
    void* p2 = allocator.allocate(256);

    std::cout << "Allocated pointer 1: " << p1 << std::endl;
    std::cout << "Allocated pointer 2: " << p2 << std::endl;

    allocator.deallocate(p1);
    allocator.deallocate(p2);
    std::cout << "Successfully allocated and deallocated variable blocks." << std::endl;
    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:**
  - `allocate()`: $\mathcal{O}(N)$ where $N$ is the number of memory blocks in the segregated free list search path.
  - `deallocate()`: $\mathcal{O}(1)$ pointer flag toggle.
- **Space Complexity:** $\mathcal{O}(M)$ where $M$ is the pre-allocated memory pool size, with per-block header metadata overhead.

Here is the complete C++20 implementation of a cache-aligned fixed-size slab allocator with debug poisoning and explicit memory tracking.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <new>
#include <cstring>
#include <cassert>

class SlabAllocator {
private:
    struct Node {
        Node* next;
    };

    size_t block_size;
    size_t blocks_per_slab;
    size_t alignment;
    std::vector<void*> slabs;
    Node* free_list;

    void allocate_slab() {
        size_t actual_block_size = (block_size < sizeof(Node)) ? sizeof(Node) : block_size;
        // Ensure alignment is respected
        size_t total_slab_bytes = actual_block_size * blocks_per_slab + alignment;

        void* raw_memory = ::operator new(total_slab_bytes, std::align_val_t{alignment});
        slabs.push_back(raw_memory);

        uintptr_t address = reinterpret_cast<uintptr_t>(raw_memory);
        size_t offset = alignment - (address % alignment);
        if (offset == alignment) {
            offset = 0;
        }
        char* aligned_start = reinterpret_cast<char*>(address + offset);

        for (size_t i = 0; i < blocks_per_slab; ++i) {
            char* block_addr = aligned_start + (i * actual_block_size);
            Node* node = reinterpret_cast<Node*>(block_addr);
            node->next = free_list;
            free_list = node;
        }
    }

public:
    SlabAllocator(size_t block_size, size_t blocks_per_slab, size_t alignment = 64)
        : block_size(block_size), blocks_per_slab(blocks_per_slab), alignment(alignment), free_list(nullptr) {
        assert(block_size > 0);
        assert(blocks_per_slab > 0);
        assert((alignment & (alignment - 1)) == 0 && "Alignment must be a power of two");
        allocate_slab();
    }

    ~SlabAllocator() {
        for (void* slab : slabs) {
            ::operator delete(slab, std::align_val_t{alignment});
        }
    }

    SlabAllocator(const SlabAllocator&) = delete;
    SlabAllocator& operator=(const SlabAllocator&) = delete;

    void* allocate() {
        if (free_list == nullptr) {
            allocate_slab();
        }
        Node* node = free_list;
        free_list = free_list->next;

        // Poison the memory block with 0xCC (debug pattern) before returning if needed
        std::memset(node, 0xCC, (block_size < sizeof(Node)) ? sizeof(Node) : block_size);
        return static_cast<void*>(node);
    }

    void deallocate(void* ptr) {
        if (ptr == nullptr) return;

        Node* node = static_cast<Node*>(ptr);
        // Poison freed memory with 0xDD
        std::memset(node, 0xDD, (block_size < sizeof(Node)) ? sizeof(Node) : block_size);

        node->next = free_list;
        free_list = node;
    }
};

int main() {
    SlabAllocator allocator(128, 1024, 64);
    void* p1 = allocator.allocate();
    void* p2 = allocator.allocate();

    std::cout << "Allocated 1: " << p1 << std::endl;
    std::cout << "Allocated 2: " << p2 << std::endl;

    allocator.deallocate(p1);
    allocator.deallocate(p2);

    std::cout << "Slab allocator test passed successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `allocate()`: $\mathcal{O}(1)$ amortized ($\mathcal{O}(N)$ only when a new slab must be dynamically allocated).
  - `deallocate()`: $\mathcal{O}(1)$ constant time as it pushes to the front of the singly linked free list.
- **Space Complexity**: $\mathcal{O}(M)$ where $M$ is the total memory requested across all allocated slabs, with zero external fragmentation.

Here is the production-ready implementation of a monotonic Arena allocator supporting checkpointing and rollbacks in C++20.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <new>
#include <memory>
#include <algorithm>
#include <cassert>

class Arena {
private:
    struct Block {
        size_t capacity;
        size_t used;
        char* data;
        Block* next;

        Block(size_t cap, Block* nxt) : capacity(cap), used(0), next(nxt) {
            data = new char[capacity];
        }

        ~Block() {
            delete[] data;
        }
    };

    size_t default_block_size;
    size_t alignment;
    Block* current_block;

    void allocate_block(size_t min_capacity) {
        size_t cap = std::max(default_block_size, min_capacity);
        current_block = new Block(cap, current_block);
    }

public:
    explicit Arena(size_t block_size = 4096, size_t alignment = alignof(std::max_align_t))
        : default_block_size(block_size), alignment(alignment), current_block(nullptr) {
        assert(block_size > 0);
        assert((alignment & (alignment - 1)) == 0);
        allocate_block(default_block_size);
    }

    ~Arena() {
        while (current_block != nullptr) {
            Block* next = current_block->next;
            delete current_block;
            current_block = next;
        }
    }

    Arena(const Arena&) = delete;
    Arena& operator=(const Arena&) = delete;

    void* allocate(size_t size) {
        if (size == 0) return nullptr;

        // Compute alignment adjustment
        uintptr_t current_address = reinterpret_cast<uintptr_t>(current_block->data + current_block->used);
        size_t adjustment = alignment - (current_address % alignment);
        if (adjustment == alignment) adjustment = 0;

        size_t total_needed = size + adjustment;

        if (current_block->used + total_needed > current_block->capacity) {
            allocate_block(std::max(default_block_size, size + alignment));
            return allocate(size);
        }

        current_block->used += adjustment;
        char* ptr = current_block->data + current_block->used;
        current_block->used += size;

        return static_cast<void*>(ptr);
    }

    struct Checkpoint {
        Block* block;
        size_t used;
    };

    Checkpoint get_checkpoint() const {
        return Checkpoint{current_block, current_block->used};
    }

    void rollback(const Checkpoint& cp) {
        while (current_block != cp.block) {
            Block* next = current_block->next;
            delete current_block;
            current_block = next;
        }
        if (current_block) {
            assert(cp.used <= current_block->capacity);
            current_block->used = cp.used;
        }
    }

    void reset() {
        if (!current_block) return;
        Block* head = current_block;
        while (head->next != nullptr) {
            Block* temp = head;
            head = head->next;
            delete temp;
        }
        current_block = head;
        current_block->used = 0;
    }
};

int main() {
    Arena arena(1024);
    void* p1 = arena.allocate(100);
    auto cp = arena.get_checkpoint();
    void* p2 = arena.allocate(200);

    std::cout << "Allocated 1: " << p1 << ", Allocates 2: " << p2 << std::endl;
    arena.rollback(cp);
    std::cout << "Rolled back arena state successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**:
  - `allocate()`: $\mathcal{O}(1)$ pointer bump arithmetic in the common case. $\mathcal{O}(K)$ during block exhaustion where $K$ is the number of blocks freed/allocated during block chain expansion.
  - `rollback()`: $\mathcal{O}(B)$ where $B$ is the number of blocks reaped during unwinding.
- **Space Complexity**: $\mathcal{O}(N)$ where $N$ is the cumulative footprint of all active memory blocks managed by the arena.

Here is a simplified thread-caching memory pool demonstrating thread-local cache integration and central heap locks in C++20.

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <cstdint>
#include <cstddef>
#include <cassert>

class CentralHeap {
private:
    struct Node {
        Node* next;
    };
    std::mutex mtx;
    Node* free_list = nullptr;
    size_t block_size;
    std::vector<void*> chunks;

    void grow() {
        size_t count = 64;
        char* memory = new char[block_size * count];
        chunks.push_back(memory);
        for (size_t i = 0; i < count; ++i) {
            Node* node = reinterpret_cast<Node*>(memory + (i * block_size));
            node->next = free_list;
            free_list = node;
        }
    }

public:
    explicit CentralHeap(size_t block_size) : block_size(block_size) {}

    ~CentralHeap() {
        for (void* chunk : chunks) {
            delete[] static_cast<char*>(chunk);
        }
    }

    void* fetch() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!free_list) {
            grow();
        }
        Node* node = free_list;
        free_list = free_list->next;
        return node;
    }

    void release(void* ptr) {
        std::lock_guard<std::mutex> lock(mtx);
        Node* node = static_cast<Node*>(ptr);
        node->next = free_list;
        free_list = node;
    }
};

class ThreadCache {
private:
    struct Node {
        Node* next;
    };
    CentralHeap& central_heap;
    Node* cache_list = nullptr;
    size_t cache_count = 0;
    const size_t max_cache_count = 32;

public:
    explicit ThreadCache(CentralHeap& heap) : central_heap(heap) {}

    ~ThreadCache() {
        while (cache_list) {
            Node* temp = cache_list;
            cache_list = cache_list->next;
            central_heap.release(temp);
        }
    }

    void* allocate() {
        if (!cache_list) {
            for (size_t i = 0; i < max_cache_count / 2; ++i) {
                void* ptr = central_heap.fetch();
                Node* node = static_cast<Node*>(ptr);
                node->next = cache_list;
                cache_list = node;
                cache_count++;
            }
        }
        Node* node = cache_list;
        cache_list = cache_list->next;
        cache_count--;
        return node;
    }

    void deallocate(void* ptr) {
        Node* node = static_cast<Node*>(ptr);
        node->next = cache_list;
        cache_list = node;
        cache_count++;

        if (cache_count >= max_cache_count) {
            for (size_t i = 0; i < max_cache_count / 2; ++i) {
                Node* temp = cache_list;
                cache_list = cache_list->next;
                cache_count--;
                central_heap.release(temp);
            }
        }
    }
};

int main() {
    CentralHeap heap(64);
    ThreadCache tcache(heap);

    void* p1 = tcache.allocate();
    void* p2 = tcache.allocate();

    tcache.deallocate(p1);
    tcache.deallocate(p2);

    std::cout << "Thread-caching memory pool execution finished successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**:
  - `allocate()`: $\mathcal{O}(1)$ thread-local fast-path execution without mutex contention.
  - `deallocate()`: $\mathcal{O}(1)$ push to thread-local list with amortized background central heap flushing.
- **Space Complexity**: $\mathcal{O}(H + T)$ where $H$ is central heap chunk storage and $T$ is thread-local cache buffering bounds.

Here is a complete C++20 Pool Allocator using a bitset/bitmap to manage allocation statuses without dynamic heap allocation inside critical paths.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <cassert>

template <size_t BlockSize, size_t BlockCount>
class BitmapPoolAllocator {
private:
    alignas(64) char pool[BlockSize * BlockCount];
    uint64_t bitmap[(BlockCount + 63) / 64] = {0};

public:
    BitmapPoolAllocator() = default;
    ~BitmapPoolAllocator() = default;

    BitmapPoolAllocator(const BitmapPoolAllocator&) = delete;
    BitmapPoolAllocator& operator=(const BitmapPoolAllocator&) = delete;

    void* allocate() {
        for (size_t i = 0; i < (BlockCount + 63) / 64; ++i) {
            if (bitmap[i] != ~uint64_t(0)) {
                for (size_t j = 0; j < 64; ++j) {
                    size_t index = i * 64 + j;
                    if (index >= BlockCount) return nullptr;

                    if ((bitmap[i] & (uint64_t(1) << j)) == 0) {
                        bitmap[i] |= (uint64_t(1) << j);
                        return static_cast<void*>(pool + (index * BlockSize));
                    }
                }
            }
        }
        return nullptr;
    }

    void deallocate(void* ptr) {
        if (!ptr) return;
        char* byte_ptr = static_cast<char*>(ptr);
        ptrdiff_t offset = byte_ptr - pool;

        assert(offset >= 0 && static_cast<size_t>(offset) < sizeof(pool));
        assert(offset % BlockSize == 0);

        size_t index = offset / BlockSize;
        size_t word_idx = index / 64;
        size_t bit_idx = index % 64;

        assert((bitmap[word_idx] & (uint64_t(1) << bit_idx)) != 0 && "Double free or corrupt block detected");
        bitmap[word_idx] &= ~(uint64_t(1) << bit_idx);
    }
};

int main() {
    BitmapPoolAllocator<64, 128> allocator;
    void* ptr1 = allocator.allocate();
    void* ptr2 = allocator.allocate();

    std::cout << "Bitmap pool allocated block 1: " << ptr1 << std::endl;
    std::cout << "Bitmap pool allocated block 2: " << ptr2 << std::endl;

    allocator.deallocate(ptr1);
    allocator.deallocate(ptr2);

    std::cout << "Bitmap pool allocator tests passed successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**:
  - `allocate()`: $\mathcal{O}(N / 64)$ where $N$ is `BlockCount`, accelerated via word-level bitwise checks.
  - `deallocate()`: $\mathcal{O}(1)$ direct index mapping.
- **Space Complexity**: $\mathcal{O}(B \times C)$ where $B$ is `BlockSize` and $C$ is `BlockCount`, plus $\mathcal{O}(C / 64)$ space for the bitmap tracking array.

Here is the production-ready C++17 Memory Arena implementation.

```cpp
#include <iostream>
#include <cstdint>
#include <cstddef>
#include <new>
#include <utility>
#include <cassert>

class MemoryArena {
private:
    std::byte* m_buffer;
    size_t m_capacity;
    size_t m_offset;

    static constexpr size_t DEFAULT_ALIGNMENT = alignof(std::max_align_t);

    // Helper to compute aligned forward displacement
    static uintptr_t align_forward_adjustment(const void* address, size_t alignment) {
        uintptr_t addr_val = reinterpret_cast<uintptr_t>(address);
        uintptr_t remainder = addr_val % alignment;
        if (remainder == 0) {
            return 0;
        }
        return alignment - remainder;
    }

public:
    explicit MemoryArena(size_t capacity)
        : m_capacity(capacity), m_offset(0) {
        if (capacity == 0) {
            throw std::invalid_argument("Arena capacity must be greater than zero.");
        }
        // Allocate raw uninitialized memory buffer
        m_buffer = static_cast<std::byte*>(::operator new(capacity, std::align_val_t{DEFAULT_ALIGNMENT}));
    }

    ~MemoryArena() {
        ::operator delete(m_buffer, std::align_val_t{DEFAULT_ALIGNMENT});
    }

    // Non-copyable, non-movable to prevent lifetime management bugs
    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;
    MemoryArena(MemoryArena&&) = delete;
    MemoryArena& operator=(MemoryArena&&) = delete;

    template <typename T, typename... Args>
    T* allocate(Args&&... args) {
        void* raw = allocate_bytes(sizeof(T), alignof(T));
        if (!raw) {
            return nullptr;
        }
        return ::new (raw) T(std::forward<Args>(args)...);
    }

    void* allocate_bytes(size_t size, size_t alignment = DEFAULT_ALIGNMENT) {
        if (size == 0) {
            return nullptr;
        }

        std::byte* current_address = m_buffer + m_offset;
        uintptr_t adjustment = align_forward_adjustment(current_address, alignment);
        size_t total_needed = size + adjustment;

        if (m_offset + total_needed > m_capacity) {
            return nullptr; // Out of memory in arena
        }

        m_offset += adjustment;
        void* allocated_ptr = static_cast<void*>(m_buffer + m_offset);
        m_offset += size;

        return allocated_ptr;
    }

    void reset() noexcept {
        m_offset = 0;
    }

    [[nodiscard]] size_t capacity() const noexcept { return m_capacity; }
    [[nodiscard]] size_t allocated_bytes() const noexcept { return m_offset; }
    [[nodiscard]] size_t available_bytes() const noexcept { return m_capacity - m_offset; }
};

int main() {
    try {
        MemoryArena arena(1024 * 1024); // 1 MB Arena

        int* numbers = arena.allocate<int>(42);
        std::cout << "Allocated int: " << *numbers << " at offset: " << arena.allocated_bytes() << "\n";

        arena.reset();
        std::cout << "Arena reset. Allocated bytes: " << arena.allocated_bytes() << "\n";
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }
    return 0;
}
