### Complexity Analysis
- **Time Complexity**:
  - Allocation (`allocate_bytes`): $O(1)$ constant time arithmetic updates for pointer offsets and alignments.
  - Reset (`reset`): $O(1)$ constant time offset resetting.
- **Space Complexity**: $O(K)$ where $K$ is the fixed pre-allocated buffer size capacity, with zero external fragmentation and negligible metadata overhead.

Here is the complete implementation of a Power-of-Two Buddy Memory Allocator in C99.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <assert.h>

#define MAX_ORDER 16

typedef struct {
    size_t min_block_size;
    size_t max_order;
    uint8_t* memory_pool;
    // Bitmaps or tree flags tracking node status: 0 for free, 1 for allocated/split
    uint8_t* node_is_split;
} BuddyAllocator;

static size_t compute_total_nodes(size_t max_order) {
    return (1U << (max_order + 1)) - 1;
}

BuddyAllocator* buddy_create(size_t min_block_size, size_t max_order) {
    if (max_order >= MAX_ORDER || min_block_size == 0) {
        return NULL;
    }

    BuddyAllocator* allocator = (BuddyAllocator*)malloc(sizeof(BuddyAllocator));
    if (!allocator) return NULL;

    allocator->min_block_size = min_block_size;
    allocator->max_order = max_order;

    size_t total_memory = min_block_size * (1U << max_order);
    allocator->memory_pool = (uint8_t*)malloc(total_memory);
    if (!allocator->memory_pool) {
        free(allocator);
        return NULL;
    }

    size_t num_nodes = compute_total_nodes(max_order);
    allocator->node_is_split = (uint8_t*)calloc(num_nodes, sizeof(uint8_t));
    if (!allocator->node_is_split) {
        free(allocator->memory_pool);
        free(allocator);
        return NULL;
    }

    return allocator;
}

void buddy_destroy(BuddyAllocator* allocator) {
    if (allocator) {
        free(allocator->memory_pool);
        free(allocator->node_is_split);
        free(allocator);
    }
}

intptr_t buddy_alloc(BuddyAllocator* allocator, size_t size) {
    if (!allocator || size == 0) return -1;

    // Find the appropriate order needed
    size_t target_order = 0;
    size_t block_size = allocator->min_block_size;

    while (block_size < size) {
        block_size <<= 1;
        target_order++;
        if (target_order > allocator->max_order) {
            return -1; // Requested size exceeds maximum capacity
        }
    }

    size_t current_order = allocator->max_order;
    size_t index = 0;

    // Traverse binary tree to find a free block
    while (current_order > target_order) {
        size_t left_child = 2 * index + 1;
        size_t right_child = 2 * index + 2;

        if (allocator->node_is_split[index]) {
            // If split, we must search child nodes. Prefer left child if available.
            index = left_child;
        } else {
            // Found an entire free block of higher order; split it!
            allocator->node_is_split[index] = 1;
            index = left_child;
        }
        current_order--;
    }

    // Check if target node is already allocated
    if (allocator->node_is_split[index]) {
        return -1; // Out of memory or block busy
    }

    allocator->node_is_split[index] = 1;

    // Compute memory offset from node index
    size_t scale = 1U << (allocator->max_order - current_order);
    size_t offset = (index - ((1U << current_order) - 1)) * (allocator->min_block_size * scale);

    return (intptr_t)(allocator->memory_pool + offset);
}

bool buddy_free(BuddyAllocator* allocator, void* ptr) {
    if (!allocator || !ptr) return false;

    uint8_t* byte_ptr = (uint8_t*)ptr;
    if (byte_ptr < allocator->memory_pool || 
        byte_ptr >= allocator->memory_pool + (allocator->min_block_size * (1U << allocator->max_order))) {
        return false;
    }

    // Reverse-engineer the tree index from the pointer address
    size_t current_order = 0;
    size_t index = 0;
    size_t offset = byte_ptr - allocator->memory_pool;
    size_t block_size = allocator->min_block_size * (1U << allocator->max_order);

    // Find leaf node corresponding to the address
    while (current_order < allocator->max_order) {
        block_size >>= 1;
        size_t left_child = 2 * index + 1;
        size_t right_child = 2 * index + 2;

        if (offset >= block_size) {
            offset -= block_size;
            index = right_child;
        } else {
            index = left_child;
        }
        current_order++;
    }

    if (!allocator->node_is_split[index] && index > 0 && allocator->node_is_split[(index - 1) / 2] == 0) {
        return false; // Double free or invalid pointer
    }

    // Free node and bubble up to coalesce buddies
    allocator->node_is_split[index] = 0;

    while (index > 0) {
        size_t parent = (index - 1) / 2;
        size_t buddy = (index % 2 == 1) ? index + 1 : index - 1;

        if (!allocator->node_is_split[parent] && !allocator->node_is_split[buddy]) {
            // Both current and buddy are free; collapse parent
            allocator->node_is_split[parent] = 0;
            index = parent;
        } else {
            break;
        }
    }

    return true;
}
```

### Complexity Analysis
- **Time Complexity**:
  - Allocation (`buddy_alloc`): $O(K)$ where $K$ is `max_order`, traversing the binary tree depth to split nodes.
  - Deallocation (`buddy_free`): $O(K)$ to locate the leaf and iteratively bubble up the tree for buddy coalescing.
- **Space Complexity**: $O(2^{K+1})$ bits/bytes for tracking split states alongside the primary memory pool buffer of size $2^K \times \text{min\_block\_size}$.

Here is the lock-free thread-safe pool allocator implemented in modern C++17.

```cpp
#include <iostream>
#include <atomic>
#include <cstdint>
#include <cstddef>
#include <new>
#include <cassert>

template <size_t BlockSize, size_t BlockCount>
class LockFreePoolAllocator {
private:
    struct Node {
        std::atomic<Node*> next;
    };

    // Ensure block size is sufficient to hold the atomic node pointer
    static_assert(BlockSize >= sizeof(Node), "BlockSize must be at least large enough to contain Node pointer.");

    alignas(64) std::byte m_pool[BlockSize * BlockCount];
    alignas(64) std::atomic<Node*> m_head;

public:
    LockFreePoolAllocator() {
        // Initialize blocks and link them into the Treiber stack
        Node* last = nullptr;
        for (size_t i = BlockCount; i > 0; --i) {
            std::byte* address = m_pool + (i - 1) * BlockSize;
            Node* node = reinterpret_cast<Node*>(address);
            node->next.store(last, std::memory_order_relaxed);
            last = node;
        }
        m_head.store(last, std::memory_order_release);
    }

    ~LockFreePoolAllocator() = default;

    LockFreePoolAllocator(const LockFreePoolAllocator&) = delete;
    LockFreePoolAllocator& operator=(const LockFreePoolAllocator&) = delete;

    void* allocate() noexcept {
        Node* old_head = m_head.load(std::memory_order_acquire);

        // Treiber stack pop operation using Compare-And-Swap (CAS) loop
        while (old_head != nullptr) {
            Node* new_head = old_head->next.load(std::memory_order_relaxed);
            if (m_head.compare_exchange_weak(old_head, new_head,
                                             std::memory_order_release,
                                             std::memory_order_acquire)) {
                return static_cast<void*>(old_head);
            }
        }
        return nullptr; // Out of memory pool blocks
    }

    void deallocate(void* ptr) noexcept {
        if (!ptr) return;

        Node* node = reinterpret_cast<Node*>(ptr);
        Node* old_head = m_head.load(std::memory_order_relaxed);

        // Treiber stack push operation using Compare-And-Swap (CAS) loop
        do {
            node->next.store(old_head, std::memory_order_relaxed);
        } while (!m_head.compare_exchange_weak(old_head, node,
                                             std::memory_order_release,
                                             std::memory_order_relaxed));
    }

    [[nodiscard]] constexpr size_t block_size() const noexcept { return BlockSize; }
    [[nodiscard]] constexpr size_t block_count() const noexcept { return BlockCount; }
};

int main() {
    LockFreePoolAllocator<64, 10> pool;

    void* p1 = pool.allocate();
    void* p2 = pool.allocate();

    std::cout << "Allocated p1: " << p1 << "\n";
    std::cout << "Allocated p2: " << p2 << "\n";

    pool.deallocate(p1);
    pool.deallocate(p2);

    std::cout << "Blocks successfully recycled lock-free.\n";
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**:
  - Allocation (`allocate`): $O(1)$ expected time (bounded by contention loops in high-concurrency CAS retry paths).
  - Deallocation (`deallocate`): $O(1)$ expected time via atomic stack pushes.
- **Space Complexity**: $O(B \times C)$ where $B$ is `BlockSize` and $C$ is `BlockCount`, with embedded intrusive pointers eliminating external overhead.

Here is the complete C99 implementation of a secure Zone/Pool Allocator equipped with canary boundary guards and double-free detection.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <assert.h>

#define CANARY_VALUE 0xDEADBEEFCAFE0000ULL

typedef struct BlockHeader {
    uint64_t canary_start;
    size_t size;
    bool is_free;
    struct BlockHeader* next;
    uint64_t canary_end;
} BlockHeader;

typedef struct {
    uint8_t* pool;
    size_t total_size;
    BlockHeader* head;
} GuardedZone;

GuardedZone* guarded_zone_create(size_t size) {
    GuardedZone* zone = (GuardedZone*)malloc(sizeof(GuardedZone));
    if (!zone) return NULL;

    zone->pool = (uint8_t*)malloc(size);
    if (!zone->pool) {
        free(zone);
        return NULL;
    }

    zone->total_size = size;

    // Initialize the first block header covering the entire zone
    zone->head = (BlockHeader*)zone->pool;
    zone->head->canary_start = CANARY_VALUE;
    zone->head->size = size - sizeof(BlockHeader);
    zone->head->is_free = true;
    zone->head->next = NULL;
    zone->head->canary_end = CANARY_VALUE;

    return zone;
}

void guarded_zone_destroy(GuardedZone* zone) {
    if (zone) {
        free(zone->pool);
        free(zone);
    }
}

void* guarded_alloc(GuardedZone* zone, size_t size) {
    if (!zone || size == 0) return NULL;

    // Align size to 8 bytes
    size = (size + 7) & ~7;

    BlockHeader* current = zone->head;
    while (current != NULL) {
        // Verify canaries before trusting metadata
        if (current->canary_start != CANARY_VALUE || current->canary_end != CANARY_VALUE) {
            fprintf(stderr, "CRITICAL: Memory corruption detected! Canary overwritten.\n");
            abort();
        }

        if (current->is_free && current->size >= size) {
            // Exact fit or split block
            if (current->size >= size + sizeof(BlockHeader) + 8) {
                BlockHeader* next_block = (BlockHeader*)((uint8_t*)(current + 1) + size);
                next_block->canary_start = CANARY_VALUE;
                next_block->size = current->size - size - sizeof(BlockHeader);
                next_block->is_free = true;
                next_block->next = current->next;
                next_block->canary_end = CANARY_VALUE;

                current->size = size;
                current->next = next_block;
            }

            current->is_free = false;
            return (void*)(current + 1);
        }
        current = current->next;
    }

    return NULL; // Out of memory
}

bool guarded_free(GuardedZone* zone, void* ptr) {
    if (!zone || !ptr) return false;

    BlockHeader* header = ((BlockHeader*)ptr) - 1;

    // Validate canaries
    if (header->canary_start != CANARY_VALUE || header->canary_end != CANARY_VALUE) {
        fprintf(stderr, "CRITICAL: Buffer overflow or corruption detected upon deallocation!\n");
        abort();
    }

    if (header->is_free) {
        fprintf(stderr, "CRITICAL: Double-free vulnerability detected!\n");
        abort();
    }

    header->is_free = true;

    // Coalesce adjacent free blocks
    BlockHeader* current = zone->head;
    while (current != NULL && current->next != NULL) {
        if (current->canary_start != CANARY_VALUE || current->canary_end != CANARY_VALUE) {
            abort();
        }
        if (current->is_free && current->next->is_free) {
            current->size += sizeof(BlockHeader) + current->next->size;
            current->next = current->next->next;
        } else {
            current = current->next;
        }
    }

    return true;
}
```

### Complexity Analysis
- **Time Complexity**:
  - Allocation (`guarded_alloc`): $O(N)$ linear scan over memory blocks, checking canaries and locating a free slot.
  - Deallocation (`guarded_free`): $O(N)$ linear time to validate canaries and coalesce adjacent free blocks.
- **Space Complexity**: $O(M + K \times S)$ where $M$ is the total zone size, $K$ is the number of allocation splits, and $S$ is the metadata header size holding boundary canaries.

Here is the complete implementation of a cache-aligned slab allocator in C featuring intrusive free-list management, canary protection, and strict safety invariants.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>

#define CACHE_LINE_SIZE 64
#define MAGIC_FREE 0xDEADBEEF
#define MAGIC_ALLOC 0xCAFEBABEU
#define CANARY_VAL 0x5AA55AA5U

typedef struct SlabHeader {
    uint32_t magic;
    uint32_t slot_index;
    uint32_t canary;
} SlabHeader;

typedef struct FreeNode {
    struct FreeNode* next;
} FreeNode;

typedef struct {
    size_t block_size;
    size_t slot_count;
    size_t actual_slot_size;
    uint8_t* memory_pool;
    FreeNode* free_list;
    size_t active_allocations;
} SlabAllocator;

static inline size_t align_up(size_t val, size_t alignment) {
    return (val + alignment - 1) & ~(alignment - 1);
}

SlabAllocator* slab_create(size_t slot_size, size_t slot_count) {
    if (slot_size == 0 || slot_count == 0) return NULL;

    size_t header_size = align_up(sizeof(SlabHeader), CACHE_LINE_SIZE);
    size_t payload_size = align_up(slot_size, CACHE_LINE_SIZE);
    size_t actual_slot_size = header_size + payload_size + sizeof(uint32_t);

    size_t total_pool_size = actual_slot_size * slot_count;

    SlabAllocator* allocator = (SlabAllocator*)malloc(sizeof(SlabAllocator));
    if (!allocator) return NULL;

    #if defined(_MSC_VER)
    allocator->memory_pool = (uint8_t*)_aligned_malloc(total_pool_size, CACHE_LINE_SIZE);
    # else
    int res = posix_memalign((void**)&allocator->memory_pool, CACHE_LINE_SIZE, total_pool_size);
    if (res != 0) {
        free(allocator);
        return NULL;
    }
    #endif

    if (!allocator->memory_pool) {
        free(allocator);
        return NULL;
    }

    allocator->block_size = slot_size;
    allocator->slot_count = slot_count;
    allocator->actual_slot_size = actual_slot_size;
    allocator->free_list = NULL;
    allocator->active_allocations = 0;

    for (size_t i = 0; i < slot_count; ++i) {
        uint8_t* slot_ptr = allocator->memory_pool + (i * actual_slot_size);
        SlabHeader* header = (SlabHeader*)slot_ptr;
        header->magic = MAGIC_FREE;
        header->slot_index = (uint32_t)i;
        header->canary = CANARY_VAL;

        uint8_t* payload_ptr = slot_ptr + header_size;
        FreeNode* node = (FreeNode*)payload_ptr;
        node->next = allocator->free_list;
        allocator->free_list = node;

        uint32_t* footer = (uint32_t*)(slot_ptr + header_size + payload_size);
        *footer = CANARY_VAL;
    }

    return allocator;
}

void* slab_alloc(SlabAllocator* allocator) {
    if (!allocator || !allocator->free_list) return NULL;

    FreeNode* node = allocator->free_list;
    allocator->free_list = node->next;

    size_t header_size = align_up(sizeof(SlabHeader), CACHE_LINE_SIZE);
    uint8_t* slot_ptr = (uint8_t*)node - header_size;
    SlabHeader* header = (SlabHeader*)slot_ptr;

    if (header->magic != MAGIC_FREE || header->canary != CANARY_VAL) {
        fprintf(stderr, "CRITICAL: Slab corruption detected during allocation!\n");
        abort();
    }

    header->magic = MAGIC_ALLOC;
    allocator->active_allocations++;

    return (void*)node;
}

void slab_free(SlabAllocator* allocator, void* ptr) {
    if (!allocator || !ptr) return;

    size_t header_size = align_up(sizeof(SlabHeader), CACHE_LINE_SIZE);
    uint8_t* slot_ptr = (uint8_t*)ptr - header_size;
    SlabHeader* header = (SlabHeader*)slot_ptr;

    if (header->magic == MAGIC_FREE) {
        fprintf(stderr, "CRITICAL: Double free detected on slab pointer %p!\n", ptr);
        abort();
    }

    if (header->magic != MAGIC_ALLOC) {
        fprintf(stderr, "CRITICAL: Invalid pointer passed to slab_free: %p!\n", ptr);
        abort();
    }

    if (header->canary != CANARY_VAL) {
        fprintf(stderr, "CRITICAL: Header canary corruption detected!\n");
        abort();
    }

    size_t payload_size = align_up(allocator->block_size, CACHE_LINE_SIZE);
    uint32_t* footer = (uint32_t*)(slot_ptr + header_size + payload_size);
    if (*footer != CANARY_VAL) {
        fprintf(stderr, "CRITICAL: Buffer overflow/underflow detected via footer canary!\n");
        abort();
    }

    header->magic = MAGIC_FREE;
    FreeNode* node = (FreeNode*)ptr;
    node->next = allocator->free_list;
    allocator->free_list = node;
    allocator->active_allocations--;
}

void slab_destroy(SlabAllocator* allocator) {
    if (!allocator) return;
    if (allocator->active_allocations > 0) {
        fprintf(stderr, "WARNING: Destroying slab allocator with %zu active leaks!\n", allocator->active_allocations);
    }
    #if defined(_MSC_VER)
    _aligned_free(allocator->memory_pool);
    #else
    free(allocator->memory_pool);
    #endif
    free(allocator);
}

int main(void) {
    SlabAllocator* allocator = slab_create(128, 4);
    if (!allocator) {
        fprintf(stderr, "Failed to create slab allocator\n");
        return 1;
    }

    void* p1 = slab_alloc(allocator);
    void* p2 = slab_alloc(allocator);

    memset(p1, 0xAA, 128);
    memset(p2, 0xBB, 128);

    printf("Allocated p1 at: %p\n", p1);
    printf("Allocated p2 at: %p\n", p2);

    slab_free(allocator, p1);
    void* p3 = slab_alloc(allocator);
    printf("Reallocated p3 at: %p (should match p1 due to LIFO free-list)\n", p3);

    slab_free(allocator, p2);
    slab_free(allocator, p3);

    slab_destroy(allocator);
    printf("Slab allocator executed successfully without memory corruption.\n");
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `slab_create`: $\mathcal{O}(N)$ where $N$ is `slot_count`, since every slot must be initialized and linked.
  - `slab_alloc`: $\mathcal{O}(1)$ constant time pointer popping from the intrusive head.
  - `slab_free`: $\mathcal{O}(1)$ constant time pointer pushing back onto the intrusive head.
  - `slab_destroy`: $\mathcal{O}(1)$ single call to deallocate the contiguous pool block.
- **Space Complexity**: $\mathcal{O}(N \times S)$ auxiliary memory footprint, where $N$ is the slot count and $S$ is the aligned slot size including metadata headers, footers, and padding constraints.

Here is the complete C++20 implementation of a monotonic memory arena allocator with explicit alignment guarantees and invariant checking.

```cpp
#include <iostream>
#include <cstdint>
#include <cstdlib>
#include <new>
#include <vector>
#include <string_view>
#include <cassert>

class MemoryArena {
private:
    size_t m_capacity;
    size_t m_offset;
    std::byte* m_buffer;
    bool m_owns_buffer;

    static constexpr size_t align_forward(size_t ptr, size_t alignment) noexcept {
        size_t modulo = ptr & (alignment - 1);
        if (modulo != 0) {
            ptr += (alignment - modulo);
        }
        return ptr;
    }

public:
    explicit MemoryArena(size_t capacity_bytes) 
        : m_capacity(capacity_bytes), m_offset(0), m_owns_buffer(true) {
        if (m_capacity == 0) {
            throw std::invalid_argument("Arena capacity must be greater than zero.");
        }
        m_buffer = static_cast<std::byte*>(std::malloc(m_capacity));
        if (!m_buffer) {
            throw std::bad_alloc();
        }
    }

    ~MemoryArena() noexcept {
        if (m_owns_buffer && m_buffer) {
            std::free(m_buffer);
        }
    }

    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;
    MemoryArena(MemoryArena&&) noexcept = delete;
    MemoryArena& operator=(MemoryArena&&) noexcept = delete;

    template <typename T, typename... Args>
    T* allocate(Args&&... args) {
        constexpr size_t size = sizeof(T);
        constexpr size_t alignment = alignof(T);

        void* raw_mem = allocate_bytes(size, alignment);
        if (!raw_mem) {
            return nullptr;
        }
        return ::new (raw_mem) T(std::forward<Args>(args)...);
    }

    void* allocate_bytes(size_t size, size_t alignment) noexcept {
        if (size == 0) return nullptr;

        uintptr_t current_address = reinterpret_cast<uintptr_t>(m_buffer + m_offset);
        uintptr_t aligned_address = align_forward(current_address, alignment);
        size_t padding = aligned_address - current_address;

        size_t total_requested = size + padding;
        if (m_offset + total_requested > m_capacity) {
            return nullptr;
        }

        m_offset += total_requested;
        return reinterpret_cast<void*>(aligned_address);
    }

    void reset() noexcept {
        m_offset = 0;
    }

    [[nodiscard]] size_t capacity() const noexcept { return m_capacity; }
    [[nodiscard]] size_t allocated_bytes() const noexcept { return m_offset; }
    [[nodiscard]] size_t available_bytes() const noexcept { return m_capacity - m_offset; }
};

struct Vector3 {
    float x, y, z;
    Vector3(float px, float py, float pz) : x(px), y(py), z(pz) {
        std::cout << "Vector3 constructed at: " << this << "\n";
    }
    ~Vector3() {
        std::cout << "Vector3 destroyed at: " << this << "\n";
    }
};

