Here is a complete three-stage concurrent pipeline implementation in Go with proper cleanup guarantees and race-free error handling.

```go
package main

(
	"context"
	"fmt"
	"sync"
	"time"
)

func Producer(ctx context.Context, count int) (<-chan int, <-chan error) {
	out := make(chan int, 10)
	errs := make(chan error, 1)

	go func() {
		defer close(out)
		defer close(errs)

		for i := 1; i <= count; i++ {
			select {
			case <-ctx.Done():
				errs <- ctx.Err()
				return
			case out <- i:
				time.Sleep(10 * time.Millisecond)
			}
		}
	}()
	return out, errs
}

func Transformer(ctx context.Context, in <-chan int) (<-chan int, <-chan error) {
	out := make(chan int, 10)
	errs := make(chan error, 1)

	go func() {
		defer close(out)
		defer close(errs)

		for {
			select {
			case <-ctx.Done():
				errs <- ctx.Err()
				return
			case val, ok := <-in:
				if !ok {
					return
				}
				select {
				case <-ctx.Done():
					errs <- ctx.Err()
					return
				case out <- val * 2:
				}
			}
		}
	}()
	return out, errs
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
	defer cancel()

	nums, pErrs := Producer(ctx, 5)
	results, tErrs := Transformer(ctx, nums)

	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case res, ok := <-results:
				if !ok {
					return
				}
				fmt.Printf("Pipeline Result: %d\n", res)
			}
		}
	}()

	wg.Wait()

	select {
	case err := <-pErrs:
		if err != nil {
			fmt.Printf("Producer error: %v\n", err)
		}
	default:
	}

	select {
	case err := <-tErrs:
		if err != nil {
			fmt.Printf("Transformer error: %v\n", err)
		}
	default:
	}
}
