func NewTokenBucket(capacity int, refillRate time.Duration) *TokenBucket {
	tb := &TokenBucket{
		capacity: capacity,
		tokens:   make(chan struct{}, capacity),
		ticker:   time.NewTicker(refillRate),
		quit:     make(chan struct{}),
	}

	for i := 0; i < capacity; i++ {
		tb.tokens <- struct{}{}
	}

	tb.wg.Add(1)
	go func() {
		defer tb.wg.Done()
		for {
			select {
			case <-tb.ticker.C:
				select {
				case tb.tokens <- struct{}{}:
				default:
				}
			case <-tb.quit:
				return
			}
		}
	}()

	return tb
}

func (tb *TokenBucket) Acquire(ctx context.Context) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-tb.tokens:
		return nil
	}
}

func (tb *TokenBucket) Close() {
	tb.ticker.Stop()
	close(tb.quit)
	tb.wg.Wait()
	close(tb.tokens)
}

func main() {
	bucket := NewTokenBucket(5, 50*time.Millisecond)
	defer bucket.Close()

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
			defer cancel()

			err := bucket.Acquire(ctx)
			if err != nil {
				fmt.Printf("Client %d failed to acquire token: %v
", id, err)
				return
			}
			fmt.Printf("Client %d acquired token successfully
", id)
		}(i)
	}
	wg.Wait()
}
