		},
	}
}

func (bp *BufferPool) Get() ([]byte, error) {
	val := bp.pool.Get()
	buf, ok := val.([]byte)
	if !ok {
		return nil, errors.New("type assertion failed in sync.Pool")
	}
	return buf[:0], nil
}

func (bp *BufferPool) Put(buf []byte) {
	if cap(buf) == 0 {
		return
	}
	bp.pool.Put(buf[:0])
}

func main() {
	bp := NewBufferPool(1024)

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			buf, err := bp.Get()
			if err != nil {
				return
			}

			buf = append(buf, fmt.Sprintf("goroutine-%d", id)...)
			var out bytes.Buffer
			out.Write(buf)
			fmt.Println(out.String())

			bp.Put(buf)
		}(i)
	}
	wg.Wait()
}
