Here is the complete, production-grade generic worker pool implementation in Go.

```go
package main

(
	"context"
	"errors"
	"fmt"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Task represents an executable unit of work returning a generic result and error.
type Task[T any] struct {
	ID     string
	Exec   func(ctx context.Context) (T, error)
	Result chan<- TaskResult[T]
}

// TaskResult carries the execution outcome.
type TaskResult[T any] struct {
	ID  string
	Res T
	Err error
}

// WorkerPool manages workers, graceful cancellation, and metrics.
type WorkerPool[T any] struct {
	inputChan   chan Task[T]
	ctx         context.Context
	cancel      context.CancelFunc
	wg          sync.WaitGroup
	workerCount int
	activeTasks int64
	resultPool  sync.Pool
}

// NewWorkerPool initializes a new worker pool.
func NewWorkerPool[T any](workerCount int, queueSize int) *WorkerPool[T] {
	ctx, cancel := context.WithCancel(context.Background())
	return &WorkerPool[T]{
		inputChan:   make(chan Task[T], queueSize),
		ctx:         ctx,
		cancel:      cancel,
		workerCount: workerCount,
		resultPool: sync.Pool{
			New: func() interface{} {
				return &TaskResult[T]{}
			},
		},
	}
}

// Start spawns the worker goroutines.
func (wp *WorkerPool[T]) Start() {
	for i := 0; i < wp.workerCount; i++ {
		wp.wg.Add(1)
		go wp.workerLoop(i)
	}
}

func (wp *WorkerPool[T]) workerLoop(id int) {
	defer wp.wg.Done()
	for {
		select {
		case <-wp.ctx.Done():
			return
		case task, ok := <-wp.inputChan:
			if !ok {
				return
			}
			atomic.AddInt64(&wp.activeTasks, 1)
			wp.executeTask(task)
			atomic.AddInt64(&wp.activeTasks, -1)
		}
	}
}

func (wp *WorkerPool[T]) executeTask(task Task[T]) {
	defer func() {
		if r := recover(); r != nil {
			if task.Result != nil {
				res := wp.resultPool.Get().(*TaskResult[T])
				res.ID = task.ID
				res.Res = *new(T)
				res.Err = fmt.Errorf("panic recovered in worker: %v", r)
				task.Result <- *res
				wp.resultPool.Put(res)
			}
		}
	}()

	res := wp.resultPool.Get().(*TaskResult[T])
	res.ID = task.ID
	res.Res, res.Err = task.Exec(wp.ctx)

	if task.Result != nil {
		task.Result <- *res
	}
	wp.resultPool.Put(res)
}

// Submit sends a task into the queue.
func (wp *WorkerPool[T]) Submit(ctx context.Context, task Task[T]) error {
	select {
	case <-wp.ctx.Done():
		return errors.New("worker pool is stopped")
	case <-ctx.Done():
		return ctx.Err()
	case wp.inputChan <- task:
		return nil
	}
}

// Shutdown gracefully stops the worker pool.
func (wp *WorkerPool[T]) Shutdown() {
	wp.cancel()
	close(wp.inputChan)
	wp.wg.Wait()
}

func main() {
	pool := NewWorkerPool[int](4, 100)
	pool.Start()

	resultChan := make(chan TaskResult[int], 10)
	for i := 0; i < 10; i++ {
		val := i
		task := Task[int]{
			ID: fmt.Sprintf("task-%d", val),
			Exec: func(ctx context.Context) (int, error) {
				if val == 5 {
					panic("simulated worker failure")
				}
				return val * val, nil
			},
			Result: resultChan,
		}
		err := pool.Submit(context.Background(), task)
		if err != nil {
			fmt.Printf("Failed to submit task: %v\n", err)
		}
	}

	time.Sleep(time.Second)
	pool.Shutdown()
}
```

### Complexity Analysis
- **Time Complexity:** Task submission takes $O(1)$ amortized time. Execution time per task is bounded by the user-defined `Exec` function complexity. Worker selection and select statements execute in $O(1)$ time relative to channel buffer size.
- **Space Complexity:** $O(N + M)$ where $N$ is the input channel buffer capacity and $M$ is the number of active workers, augmented by `sync.Pool` reducing allocation churn to $O(1)$ for result objects.

