```go
package main

(
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// TokenBucket implements a concurrent rate limiter using a ticker and channel buffer.
type TokenBucket struct {
	capacity int
	tokens   chan struct{}
	closeChan chan struct{}
	wg       sync.WaitGroup
}

// NewTokenBucket creates a bucket holding 'capacity' tokens, refilling at 'rate' per second.
func NewTokenBucket(capacity int, rate float64) *TokenBucket {
	b := &TokenBucket{
		capacity:  capacity,
		tokens:    make(chan struct{}, capacity),
		closeChan: make(chan struct{}),
	}

	// Pre-fill the bucket
	for i := 0; i < capacity; i++ {
		b.tokens <- struct{}{}
	}

	interval := time.Duration(float64(time.Second) / rate)
	b.wg.Add(1)
	go b.refillLoop(interval)

	return b
}

func (b *TokenBucket) refillLoop(interval time.Duration) {
	defer b.wg.Done()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-b.closeChan:
			return
		case <-ticker.C:
			select {
			case b.tokens <- struct{}{}:
			default:
				// Bucket is full, drop token
			}
		}
	}
}

// Acquire attempts to acquire a token, respecting context cancellation.
func (b *TokenBucket) Acquire(ctx context.Context) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-b.closeChan:
		return errors.New("rate limiter closed")
	case <-b.tokens:
		return nil
	}
}

// Stop terminates the background refilling routine.
func (b *TokenBucket) Stop() {
	close(b.closeChan)
	b.wg.Wait()
}

func main() {
	limiter := NewTokenBucket(5, 10.0) // 5 burst capacity, 10 tokens per second
	defer limiter.Stop()

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			ctx, cancel := context.WithTimeout(context.Background(), time.Second)
			defer cancel()

			if err := limiter.Acquire(ctx); err != nil {
				fmt.Printf("Routine %d rate limited or timed out: %v\n", id, err)
				return
			}
			fmt.Printf("Routine %d executed successfully\n", id)
		}(i)
	}
	wg.Wait()
}
```

