- **Time Complexity:** $O(1)$ for token acquisition and channel push operations.
- **Space Complexity:** $O(C)$ where $C$ is the bucket capacity allocated inside the buffered channel.

Here is the production-grade concurrent MapReduce engine in Go.

```go
package main

(
	"context"
	"fmt"
	"sync"
)

type KeyValuePair[K comparable, V any] struct {
	Key   K
	Value V
}

// MapReduce runs a concurrent Map-Reduce computation.
func MapReduce[K comparable, V any, R any](
	ctx context.Context,
	inputs []V,
	mapper func(ctx context.Context, val V) ([]KeyValuePair[K, R], error),
	reducer func(ctx context.Context, key K, values []R) (R, error),
) (map[K]R, error) {

	inputChan := make(chan V, len(inputs))
	for _, in := range inputs {
		inputChan <- in
	}
	close(inputChan)

	intermediateChan := make(chan KeyValuePair[K, R], len(inputs)*2)
	var mapWg sync.WaitGroup

	// Mapper stage
	workers := 4
	for i := 0; i < workers; i++ {
		mapWg.Add(1)
		go func() {
			defer mapWg.Done()
			for val := range inputChan {
				select {
				case <-ctx.Done():
					return
				default:
					results, err := mapper(ctx, val)
					if err == nil {
						for _, kv := range results {
							intermediateChan <- kv
						}
					}
				}
			}
		}()
	}

	go func() {
		mapWg.Wait()
		close(intermediateChan)
	}()

	// Shuffle & Group stage
	grouped := make(map[K][]R)
	for kv := range intermediateChan {
		grouped[kv.Key] = append(grouped[kv.Key], kv.Value)
	}

	// Reducer stage
	results := make(map[K]R)
	var reduceWg sync.WaitGroup
	var mu sync.Mutex

	for k, vals := range grouped {
		reduceWg.Add(1)
		go func(key K, values []R) {
			defer reduceWg.Done()
			res, err := reducer(ctx, key, values)
			if err == nil {
				mu.Lock()
				results[key] = res
				mu.Unlock()
			}
		}(k, vals)
	}

	reduceWg.Wait()
	return results, nil
}

func main() {
	ctx := context.Background()
	inputs := []string{"apple banana apple", "banana orange apple", "orange orange"}

	mapper := func(ctx context.Context, line string) ([]KeyValuePair[string, int], error) {
		out := []KeyValuePair[string, int]{}
		words := []string{}
		// simple whitespace tokenizer
		word := ""
		for _, ch := range line {
			if ch == ' ' {
				if word != "" {
					words = append(words, word)
					word = ""
				}
			} else {
				word += string(ch)
			}
		}
		if word != "" {
			words = append(words, word)
		}

		for _, w := range words {
			out = append(out, KeyValuePair[string, int]{Key: w, Value: 1})
		}
		return out, nil
	}

	reducer := func(ctx context.Context, key string, values []int) (int, error) {
		sum := 0
		for _, v := range values {
			sum += v
		}
		return sum, nil
	}

	res, err := MapReduce(ctx, inputs, mapper, reducer)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	for k, v := range res {
		fmt.Printf("%s: %d\n", k, v)
	}
}
```

### Complexity Analysis
- **Time Complexity:** $O(N + M + K)$ where $N$ is the number of inputs, $M$ is the number of intermediate mapped records, and $K$ is the number of unique keys reduced.
- **Space Complexity:** $O(M + K)$ for storing intermediate shuffle buffers and final grouped reducer maps.

