}

func (p *WorkerPool) Submit(job Job) error {
	select {
	case <-p.ctx.Done():
		return ErrPoolClosed
	case p.jobQueue <- job:
		return nil
	default:
		return errors.New("job queue is full")
	}
}

func (p *WorkerPool) Stop() {
	p.cancel()
	close(p.jobQueue)
	p.wg.Wait()
}

