```go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// TokenBucket implements a rate limiter.
type TokenBucket struct {
	mu         sync.Mutex
	capacity   float64
	tokens     float64
	fillRate   float64 // tokens per second
	lastFill   time.Time
	ctx        context.Context
	cancel     context.CancelFunc
	wg         sync.WaitGroup
}

// NewTokenBucket creates and starts a token bucket rate limiter.
func NewTokenBucket(capacity float64, fillRate float64) *TokenBucket {
	ctx, cancel := context.WithCancel(context.Background())
	b := &TokenBucket{
		capacity: capacity,
		tokens:   capacity,
		fillRate: fillRate,
		lastFill: time.Now(),
		ctx:      ctx,
		cancel:   cancel,
	}

	b.wg.Add(1)
	go b.backgroundRefill()
	return b
}

func (b *TokenBucket) backgroundRefill() {
	defer b.wg.Done()
	ticker := time.NewTicker(50 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-b.ctx.Done():
			return
		case t := <-ticker.C:
			b.mu.Lock()
			now := t
			delta := now.Sub(b.lastFill).Seconds()
			b.lastFill = now
			b.tokens = min(b.capacity, b.tokens+delta*b.fillRate)
			b.mu.Unlock()
		}
	}
}

// Allow checks if a token can be consumed.
func (b *TokenBucket) Allow() bool {
	b.mu.Lock()
	defer b.mu.Unlock()

	now := time.Now()
	delta := now.Sub(b.lastFill).Seconds()
	b.lastFill = now
	b.tokens = min(b.capacity, b.tokens+delta*b.fillRate)

	if b.tokens >= 1.0 {
		b.tokens--
		return true
	}
	return false
}

// Stop terminates background filling and waits for cleanup.
func (b *TokenBucket) Stop() {
	b.cancel()
	b.wg.Wait()
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

func main() {
	limiter := NewTokenBucket(5, 2)
	defer limiter.Stop()

	for i := 0; i < 10; i++ {
		if limiter.Allow() {
			fmt.Printf("Request %d: Allowed\n", i)
		} else {
			fmt.Printf("Request %d: Rate limited\n", i)
		}
		time.Sleep(100 * time.Millisecond)
	}
}
```

