- **Space Complexity:** $O(1)$ constant auxiliary memory footprint.

Here is the implementation of a generic worker pool executing tasks with context propagation and structured error results.

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

type Task[T any, R any] struct {
	ID  string
	Arg T
}

type Result[R any] struct {
	ID  string
	Res R
	Err error
}

func WorkerPool[T any, R any](
	ctx context.Context,
	workers int,
	tasks <-chan Task[T,
	R],
	exec func(context.Context, T) (R, error),
) <-chan Result[R] {
	results := make(chan Result[R])
	var wg sync.WaitGroup

	worker := func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case task, ok := <-tasks:
				if !ok {
					return
				}
				res, err := exec(ctx, task.Arg)
				select {
				case results <- Result[R]{ID: task.ID, Res: res, Err: err}:
				case <-ctx.Done():
					return
				}
			}
		}
	}

	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go worker()
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
	defer cancel()

	tasks := make(chan Task[int, int], 5)
	for i := 1; i <= 5; i++ {
		tasks <- Task[int, int]{ID: fmt.Sprintf("task-%d", i), Arg: i}
	}
	close(tasks)

	execFn := func(ctx context.Context, v int) (int, error) {
		if v == 3 {
			return 0, errors.New("failed on 3")
		}
		return v * 2, nil
	}

	results := WorkerPool(ctx, 3, tasks, execFn)
	for res := range results {
		if res.Err != nil {
			fmt.Printf("Task %s failed: %v\n", res.ID, res.Err)
		} else {
			fmt.Printf("Task %s succeeded: %d\n", res.ID, res.Res)
		}
	}
}
```

