	Err      error
}

func ScatterGather(ctx context.Context, workersCount int) ([]string, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	results := make(chan Result, workersCount)
	var wg sync.WaitGroup

	for i := 0; i < workersCount; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()

			simulatedLatency := time.Duration(id*10) * time.Millisecond
			select {
			case <-ctx.Done():
				return
			case <-time.After(simulatedLatency):
				if id == 3 {
					results <- Result{WorkerID: id, Err: errors.New("critical worker failure")}
					cancel()
					return
				}
				results <- Result{WorkerID: id, Data: fmt.Sprintf("resp-%d", id), Err: nil}
			}
		}(i)
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	var gathered []string
	for res := range results {
		if res.Err != nil {
			return nil, res.Err
		}
		gathered = append(gathered, res.Data)
	}

	return gathered, nil
}

