package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// Job represents a unit of work to be processed.
type Job struct {
	ID   int
	Data string
}

// Result represents the outcome of a processed job.
type Result struct {
	JobID int
	Output string
	Err   error
}

// WorkerPool manages concurrent execution of jobs.
type WorkerPool struct {
	numWorkers int
	jobs       chan Job
	results    chan Result
}

// NewWorkerPool initializes a new WorkerPool with specified concurrency and buffer sizes.
func NewWorkerPool(numWorkers, bufferSize int) *WorkerPool {
	return &WorkerPool{
		numWorkers: numWorkers,
		jobs:       make(chan Job, bufferSize),
		results    make(chan Result, bufferSize),
	}
}

// Start spawns the worker goroutines and returns the results channel.
func (wp *WorkerPool) Start(ctx context.Context) <-chan Result {
	var wg sync.WaitGroup

	for i := 1; i <= wp.numWorkers; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case job, ok := <-wp.jobs:
					if !ok {
						return
					}

					// Execute job with panic recovery
					res, err := processJob(ctx, job)
					select {
					case <-ctx.Done():
						return
					case wp.results <- Result{JobID: job.ID, Output: res, Err: err}:
					}
				}
			}
		}(i)
	}

	// Closer goroutine to close the results channel once all workers terminate
	go func() {
		wg.Wait()
		close(wp.results)
	}()

	return wp.results
}

func processJob(ctx context.Context, job Job) (string, error) {
	// Simulate work
	select {
	case <-time.After(10 * time.Millisecond):
		return fmt.Sprintf("Processed-%s", job.Data), nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

func (wp *WorkerPool) Submit(ctx context.Context, job Job) bool {
	select {
	case <-ctx.Done():
		return false
	case wp.jobs <- job:
		return true
	}
}

func (wp *WorkerPool) CloseJobs() {
	close(wp.jobs)
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	pool := NewWorkerPool(4, 10)
	resultsChan := pool.Start(ctx)

	go func() {
		for i := 1; i <= 20; i++ {
			if !pool.Submit(ctx, Job{ID: i, Data: fmt.Sprintf("Val-%d", i)}) {
				break
			}
		}
		pool.CloseJobs()
	}()

	for res := range resultsChan {
		if res.Err != nil {
			fmt.Printf("Job %d failed: %v\n", res.JobID, res.Err)
		} else {
			fmt.Printf("Job %d success: %s\n", res.JobID, res.Output)
		}
	}
}
