	}()
	_ = task.Fn()
}

func (p *WorkerPool) Submit(task Task) error {
	if p.closed.Load() {
		return errors.New("worker pool is closed")
	}
	p.taskQueue <- task
	return nil
}

func (p *WorkerPool) Shutdown() {
	p.closed.Store(true)
	close(p.taskQueue)
	p.wg.Wait()
}

