		TaskID:   task.ID,
		Output:   fmt.Sprintf("Processed data: %s", task.Data),
		Err:      nil,
	}
}

// Submit adds a task to the queue, returning an error if context is cancelled.
func (wp *WorkerPool) Submit(ctx context.Context, task Task) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case wp.taskQueue <- task:
		return nil
	}
}

// CloseAndWait closes the task queue and blocks until all workers terminate.
func (wp *WorkerPool) CloseAndWait() {
	close(wp.taskQueue)
	wp.wg.Wait()
	close(wp.resultChan)
}

// Results returns the read-only results channel.
func (wp *WorkerPool) Results() <-chan Result {
	return wp.resultChan
}

