class ContiguousMatrixBuffer:
    def __init__(self, rows: int, cols: int, initial_val: int = 0):
        if rows <= 0 or cols <= 0:
            raise ValueError("Matrix dimensions must be positive integers")
        self._rows = rows
        self._cols = cols
        self._buffer = bytearray([initial_val & 0xFF] * (rows * cols))

    @property
    def shape(self) -> tuple[int, int]:
        return (self._rows, self._cols)

    def __len__(self) -> int:
        return len(self._buffer)

    def __getitem__(self, idx: tuple[int, int]) -> int:
        r, c = idx
        if not (0 <= r < self._rows and 0 <= c < self._cols):
            raise IndexError(f"Index ({r}, {c}) out of bounds for shape {self.shape}")
        return self._buffer[r * self._cols + c]

    def __setitem__(self, idx: tuple[int, int], value: int) -> None:
        r, c = idx
        if not (0 <= r < self._rows and 0 <= c < self._cols):
            raise IndexError(f"Index ({r}, {c}) out of bounds for shape {self.shape}")
        if not (0 <= value <= 255):
            raise ValueError("Value must fit in a single byte (0-255)")
        self._buffer[r * self._cols + c] = value

    def __buffer__(self, flags: int) -> memoryview:
        # Expose the underlying bytearray via standard memoryview buffer export
        mv = memoryview(self._buffer)
        return mv

