import ctypes
import sys

# Load standard C library
if sys.platform == 'win32':
    libc = ctypes.CDLL('msvcrt.dll')
else:
    libc = ctypes.CDLL(None)

# Configure signatures for safety
libc.malloc.argtypes = [ctypes.c_size_t]
libc.malloc.restype = ctypes.c_void_p

libc.free.argtypes = [ctypes.c_void_p]
libc.free.restype = None

libc.memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
libc.memcpy.restype = ctypes.c_void_p


class OffHeapBuffer:
    """
    A context manager and container for raw off-heap memory allocations
    managed via standard C malloc/free, complete with buffer protocol exposure.

    Time Complexity:
        - Allocation / Deallocation: O(1) allocator dependent.
        - Read/Write via buffer: O(N) for bulk copy, O(1) for direct indexing.
    Space Complexity: O(N) where N is the buffer size in bytes.
    """
    def __init__(self, size: int):
        if size <= 0:
            raise ValueError("Allocation size must be greater than zero.")
        self._size = size
        self._ptr = libc.malloc(size)
        if not self._ptr:
            raise MemoryError(f"Failed to allocate {size} bytes of off-heap memory.")
        self._released = False

    @property
    def size(self) -> int:
        return self._size

    @property
    def address(self) -> int:
        return self._ptr

    def release(self) -> None:
        if not self._released:
            libc.free(self._ptr)
            self._ptr = None
            self._released = True

    def __enter__(self) -> 'OffHeapBuffer':
        if self._released:
            raise ValueError("Cannot enter context of a released OffHeapBuffer.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.release()

    def __del__(self):
        try:
            self.release()
        except Exception:
            pass

    def __buffer__(self, flags: int) -> memoryview:
        if self._released:
            raise ValueError("Cannot export buffer from a released memory region.")
        # Create a ctypes array type pointing to the memory address
        array_type = ctypes.c_char * self._size
        self._array_ref = array_type.from_address(self._ptr)
        return memoryview(self._array_ref)

if __name__ == '__main__':
    # Demonstration of context manager and zero-copy write via memoryview
    with OffHeapBuffer(1024) as buf:
        mv = memoryview(buf)
        mv[:5] = b'Hello'
        print("Successfully wrote to off-heap memory:", bytes(mv[:5]))
