types = dis

def analyze_bytecode_jumps(func):
    """
    Analyzes a Python function's bytecode to identify jump instructions,
    their targets, and builds a directed adjacency representation of jumps.

    Time Complexity: O(I) where I is the number of bytecode instructions.
    Space Complexity: O(I) for storing instruction maps and jump edges.
    """
    if not callable(func):
        raise TypeError("Provided object must be a callable function.")

    try:
        code_obj = func.__code__
    except AttributeError as e:
        raise ValueError("Object does not have a valid __code__ attribute.") from e

    instructions = list(dis.get_instructions(code_obj))
    offset_to_index = {instr.offset: idx for idx, instr in enumerate(instructions)}

    jumps = []
    jump_targets = set()

    for idx, instr in enumerate(instructions):
        if 'JUMP' in instr.opname:
            target_offset = instr.argval
            if isinstance(target_offset, int):
                jump_targets.add(target_offset)
                jumps.append({
                    'source_offset': instr.offset,
                    'source_opname': instr.opname,
                    'target_offset': target_offset,
                    'conditional': 'IF' in instr.opname or 'CBNZ' in instr.opname or 'POP' in instr.opname
                })

    return {
        'total_instructions': len(instructions),
        'jump_edges': jumps,
        'unique_jump_targets': sorted(list(jump_targets))
    }

if __name__ == '__main__':
    def sample_func(x):
        if x > 10:
            return x * 2
        else:
            return x + 5

    analysis = analyze_bytecode_jumps(sample_func)
    print("Bytecode Jump Analysis Result:")
    for k, v in analysis.items():
        print(f"{k}: {v}")
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(I)$ where $I$ is the instruction count of the code object, as we perform a single linear scan over `dis.get_instructions()`.
- **Space Complexity**: $\mathcal{O}(I)$ to store the instruction index maps, jump edges, and unique targets.

Here is a clean-room implementation of a custom event loop handling file descriptor selectors and scheduled callbacks.

```python
import selectors
import time
import heapq
from typing import Callable, Any, Tuple

class CustomEventLoop:
    """
    A production-grade, minimal single-threaded asynchronous event loop
    supporting socket/FD multiplexing and time-based callback scheduling.

    Time Complexity:
        - Event dispatch iteration: O(N + K log M) where N is ready FDs, K is expired timers.
        - Scheduling call_later: O(log M) where M is scheduled timers.
    Space Complexity: O(F + M) where F is registered FDs and M is pending timers.
    """
    def __init__(self):
        self._selector = selectors.DefaultSelector()
        self._timer_handle = 0
        self._scheduled: list[Tuple[float, int, Callable, tuple]] = []
        self._running = False

    def call_soon(self, callback: Callable[..., Any], *args: Any) -> None:
        self.call_later(0.0, callback, *args)

    def call_later(self, delay: float, callback: Callable[..., Any], *args: Any) -> None:
        if delay < 0:
            raise ValueError("Delay cannot be negative.")
        if not callable(callback):
            raise TypeError("Callback must be a callable object.")

        run_at = time.monotonic() + delay
        self._timer_handle += 1
        heapq.heappush(self._scheduled, (run_at, self._timer_handle, callback, args))

    def add_reader(self, fileobj: Any, callback: Callable[..., Any], *args: Any) -> None:
        try:
            key = self._selector.get_key(fileobj)
            events = key.events | selectors.EVENT_READ
            data = (callback, key.data[1]) if key.data else (callback, None)
            self._selector.modify(fileobj, events, data)
        except KeyError:
            self._selector.register(fileobj, selectors.EVENT_READ, (callback, None))

    def remove_reader(self, fileobj: Any) -> None:
        try:
            key = self._selector.get_key(fileobj)
            events = key.events & ~selectors.EVENT_READ
            if events:
                self._selector.modify(fileobj, events, key.data)
            else:
                self._selector.unregister(fileobj)
        except KeyError:
            pass

    def run_once(self, timeout: float | None = None) -> None:
        # Process timers first
        now = time.monotonic()
        next_timeout = timeout

        if self._scheduled:
            run_at, _, callback, args = self._scheduled[0]
            if run_at <= now:
                heapq.heappop(self._scheduled)
                try:
                    callback(*args)
                except Exception as e:
                    print(f"Exception in scheduled callback {callback}: {e}", file=sys.stderr)
                return
            else:
                delta = run_at - now
                next_timeout = delta if next_timeout is None else min(next_timeout, delta)

        # Poll selector
        events = self._selector.select(timeout=next_timeout)
        for key, mask in events:
            callback, _ = key.data
            try:
                callback()
            except Exception as e:
                print(f"Exception in reader callback {callback}: {e}", file=sys.stderr)

    def run(self) -> None:
        self._running = True
        try:
            while self._running:
                self.run_once(timeout=1.0)
        finally:
            self._selector.close()

    def stop(self) -> None:
        self._running = False

if __name__ == '__main__':
    import sys
    loop = CustomEventLoop()

    def test_task():
        print("Timer executed successfully!")
        loop.stop()

    loop.call_later(0.1, test_task)
    loop.run()
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(\log M)$ per timer insertion via binary heap. $\mathcal{O}(N + K \log M)$ per event loop iteration where $N$ is ready file descriptors and $K$ is expired timer tasks processed.
- **Space Complexity**: $\mathcal{O}(F + M)$ where $F$ is the number of active registered file descriptors and $M$ is the number of pending delayed callbacks.

Here is a custom cooperative event loop using Python's `selectors` and `heapq` modules.

```python
import selectors
import heapq
import time
import collections

class CustomEventLoop:
    def __init__(self) -> None:
        self._selector = selectors.DefaultSelector()
        self._ready = collections.deque()
        self._scheduled = []
        self._handle_counter = 0
        self._running = False

    def call_soon(self, callback, *args):
        self._ready.append((callback, args))

    def call_later(self, delay: float, callback, *args):
        if delay < 0:
            raise ValueError("Delay must be non-negative.")
        when = time.monotonic() + delay
        self._handle_counter += 1
        heapq.heappush(self._scheduled, (when, self._handle_counter, callback, args))

    def run_until_complete(self, coro):
        self._running = True
        task = self._ensure_future(coro)
        while self._running:
            self._run_once()
            if task.done():
                self._running = False
        return task.result()

    def _ensure_future(self, coro):
        # Simplified future/task wrapper representation
        class SimpleTask:
            def __init__(self, c):
                self.coro = c
                self._done = False
                self._result = None
            def step(self, loop):
                try:
                    res = self.coro.send(None)
                except StopIteration as e:
                    self._done = True
                    self._result = e.value
                except Exception as ex:
                    self._done = True
                    self._result = ex
            def done(self):
                return self._done
            def result(self):
                if isinstance(self._result, Exception):
                    raise self._result
                return self._result

        t = SimpleTask(coro)
        self.call_soon(t.step, self)
        return t

    def _run_once(self):
        now = time.monotonic()
        if self._scheduled:
            while self._scheduled and self._scheduled[0][0] <= now:
                _, _, callback, args = heapq.heappop(self._scheduled)
                self._ready.append((callback, args))

        timeout = None
        if self._scheduled and not self._ready:
            timeout = max(0, self._scheduled[0][0] - now)

        events = self._selector.select(timeout)
        for key, mask in events:
            callback, args = key.data
            self._ready.append((callback, args + (mask,)))

        n_ready = len(self._ready)
        for _ in range(n_ready):
            callback, args = self._ready.popleft()
            try:
                callback(*args)
            except Exception as e:
                print(f"Exception in event loop callback: {e}")

    def stop(self):
        self._running = False

    def close(self):
        self._selector.close()

if __name__ == "__main__":
    async def sample_coro():
        return "Event Loop Complete"

    loop = CustomEventLoop()
    try:
        res = loop.run_until_complete(sample_coro())
        print(res)
    finally:
        loop.close()
```

### Complexity Analysis
- **Time Complexity**: $O(\log K + E)$ per loop iteration, where $K$ is the number of scheduled timers in the priority queue and $E$ is the number of triggered file descriptors.
- **Space Complexity**: $O(F + T)$ where $F$ is the number of registered file descriptors in the selector and $T$ is the number of active scheduled callbacks.

Here is the complete implementation utilizing Python's bytecode disassembly structures to audit functions for unauthorized global accesses.

```python
import dis
import types
from typing import Tuple, List, Set

def audit_global_lookups(func: types.FunctionType, whitelist: Set[str]) -> Tuple[bool, List[str]]:
    """
    Audits a function's bytecode for LOAD_GLOBAL instructions referencing
    names outside the provided whitelist.

    Args:
        func: The function object to inspect.
        whitelist: A set of allowed global names (strings).

    Returns:
        A tuple of (is_safe, list_of_violations).
    """
    if not isinstance(func, types.FunctionType):
        raise TypeError("Provided object is not a standard Python function.")

    code_obj = func.__code__
    violations: List[str] = []

    # Iterate through bytecode instructions using dis.get_instructions
    for instr in dis.get_instructions(code_obj):
        if instr.opname == 'LOAD_GLOBAL':
            name = instr.argval
            if name not in whitelist:
                if name not in violations:
                    violations.append(name)

    # Recursively check nested code objects (e.g., closures, lambdas, inner functions)
    for const in code_obj.co_consts:
        if isinstance(const, types.CodeType):
            # Create a dummy function to run audit recursively
            dummy_func = types.FunctionType(const, func.__globals__)
            _, sub_violations = audit_global_lookups(dummy_func, whitelist)
            for v in sub_violations:
                if v not in violations:
                    violations.append(v)

    return len(violations) == 0, violations

if __name__ == "__main__":
    def unsafe_func():
        return eval("1 + 1") + len([1, 2, 3])

    allowed = {'len', 'print'}
    safe, offenders = audit_global_lookups(unsafe_func, allowed)
    print(f"Is Safe: {safe}, Violations: {offenders}")
```

### Complexity Analysis
- **Time Complexity:** $O(I)$ where $I$ is the total number of bytecode instructions across the function and all nested code objects.
- **Space Complexity:** $O(V + D)$ where $V$ is the number of unique violations stored and $D$ is the maximum nesting depth of code objects.

Here is the complete C++ implementation of a B+ Tree leaf node split routine for a slotted-page database storage engine.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <memory>

constexpr size_t PAGE_SIZE = 4096;

struct RecordID {
    uint32_t page_id;
    uint16_t slot_id;
};

struct LeafNode {
    static constexpr size_t MAX_KEYS = 3;
    int keys[MAX_KEYS + 1];
    RecordID values[MAX_KEYS + 1];
    uint16_t num_keys;
    uint32_t next_page_id;
    uint32_t prev_page_id;
    bool is_leaf;

    LeafNode() : num_keys(0), next_page_id(0), prev_page_id(0), is_leaf(true) {
        std::memset(keys, 0, sizeof(keys));
        std::memset(values, 0, sizeof(values));
    }
};

struct SplitResult {
    int promoted_key;
    std::unique_ptr<LeafNode> new_node;
};

class BPlusTreeEngine {
public:
    static SplitResult split_leaf_node(LeafNode* left_node, int new_key, const RecordID& new_val, uint32_t new_page_id) {
        if (!left_node) {
            throw std::invalid_argument("Left node cannot be null");
        }

        // Temporary buffer to hold all keys and values including the new insertion
        const size_t total_elements = left_node->num_keys + 1;
        std::vector<int> temp_keys(total_elements);
        std::vector<RecordID> temp_values(total_elements);

        size_t insert_idx = 0;
        while (insert_idx < left_node->num_keys && left_node->keys[insert_idx] < new_key) {
            temp_keys[insert_idx] = left_node->keys[insert_idx];
            temp_values[insert_idx] = left_node->values[insert_idx];
            insert_idx++;
        }

        temp_keys[insert_idx] = new_key;
        temp_values[insert_idx] = new_val;

        for (size_t i = insert_idx; i < left_node->num_keys; ++i) {
            temp_keys[i + 1] = left_node->keys[i];
            temp_values[i + 1] = left_node->values[i];
        }

        // Clear left node contents
        std::memset(left_node->keys, 0, sizeof(left_node->keys));
        std::memset(left_node->values, sizeof(left_node->values));
        left_node->num_keys = 0;

        // Calculate split point (split evenly or left-heavy)
        size_t split_idx = (total_elements + 1) / 2;

        // Populate left node
        for (size_t i = 0; i < split_idx; ++i) {
            left_node->keys[i] = temp_keys[i];
            left_node->values[i] = temp_values[i];
            left_node->num_keys++;
        }

        // Create new right sibling node
        auto right_node = std::make_unique<LeafNode>();
        size_t right_count = 0;
        for (size_t i = split_idx; i < total_elements; ++i) {
            right_node->keys[right_count] = temp_keys[i];
            right_node->values[right_count] = temp_values[i];
            right_count++;
        }
        right_node->num_keys = right_count;

        // Maintain doubly linked list pointers for leaf nodes
        right_node->next_page_id = left_node->next_page_id;
        right_node->prev_page_id = new_page_id; // Will be set by buffer pool manager
        left_node->next_page_id = new_page_id;

        SplitResult result;
        result.promoted_key = right_node->keys[0];
        result.new_node = std::move(right_node);
        return result;
    }
};

int main() {
    LeafNode node;
    node.keys[0] = 10;
    node.values[0] = {1, 0};
    node.keys[1] = 20;
    node.values[1] = {1, 1};
    node.keys[2] = 30;
    node.values[2] = {1, 2};
    node.num_keys = 3;

    auto result = BPlusTreeEngine::split_leaf_node(&node, 25, {1, 3}, 99);
    std::cout << "Promoted Key: " << result.promoted_key << std::endl;
    std::cout << "Left Node Keys: " << node.num_keys << " | Right Node Keys: " << result.new_node->num_keys << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the maximum number of keys in a node (bounded by node capacity, typically small like 64-512 elements per node due to cache-line and page sizing).
- **Space Complexity**: $\mathcal{O}(N)$ auxiliary space for temporary vectors used during sorting and partitioning before committing back to the fixed node buffers.

Here is a complete C++ implementation of a Clock buffer pool replacement policy enforcing frame pinning, dirty tracking, and cyclic victim selection.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <stdexcept>

class ClockBufferPool {
private:
    struct Frame {
        uint32_t page_id;
        bool ref_bit;
        bool dirty_bit;
        int pin_count;
        bool is_valid;

        Frame() : page_id(0), ref_bit(false), dirty_bit(false), pin_count(0), is_valid(false) {}
    };

    size_t pool_size;
    size_t hand;
    std::vector<Frame> frames;

public:
    explicit ClockBufferPool(size_t size) : pool_size(size), hand(0) {
        if (size == 0) {
            throw std::invalid_argument("Buffer pool size must be greater than zero");
        }
        frames.resize(pool_size);
    }

    int find_victim_frame() {
        size_t checked = 0;
        while (checked < 2 * pool_size) {
            Frame& frame = frames[hand];

            if (!frame.is_valid) {
                int victim = hand;
                hand = (hand + 1) % pool_size;
                return victim;
            }

            if (frame.pin_count == 0) {
                if (!frame.ref_bit) {
                    int victim = hand;
                    hand = (hand + 1) % pool_size;
                    return victim;
                } else {
                    frame.ref_bit = false;
                }
            }

            hand = (hand + 1) % pool_size;
            checked++;
        }
        throw std::runtime_error("No unpinned frames available in buffer pool (all pinned!)");
    }

    void pin_page(uint32_t page_id, int frame_id) {
        if (frame_id < 0 || static_cast<size_t>(frame_id) >= pool_size) {
            throw std::out_of_range("Invalid frame ID");
        }
        Frame& frame = frames[frame_id];
        frame.page_id = page_id;
        frame.ref_bit = true;
        frame.pin_count++;
        frame.is_valid = true;
    }

    void unpin_page(int frame_id, bool is_dirty) {
        if (frame_id < 0 || static_cast<size_t>(frame_id) >= pool_size) {
            throw std::out_of_range("Invalid frame ID");
        }
        Frame& frame = frames[frame_id];
        if (frame.pin_count <= 0) {
            throw std::runtime_error("Page pin count underflow");
        }
        frame.pin_count--;
        if (is_dirty) {
            frame.dirty_bit = true;
        }
    }

    size_t get_pool_size() const { return pool_size; }
};

int main() {
    ClockBufferPool bp(3);
    int f1 = bp.find_victim_frame();
    bp.pin_page(100, f1);

    int f2 = bp.find_victim_frame();
    bp.pin_page(101, f2);

    bp.unpin_page(f1, false);
    int f3 = bp.find_victim_frame();
    std::cout << "Evicted/Selected victim frame: " << f3 << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - Victim Eviction: $\mathcal{O}(N)$ in the worst-case where $N$ is the buffer pool capacity, when all frames have reference bits set and require a full clock sweep. Average case is $\mathcal{O}(1)$.
  - Pin/Unpin: $\mathcal{O}(1)$ direct array index lookup.
- **Space Complexity**: $\mathcal{O}(N)$ auxiliary memory proportional to the fixed buffer pool size to track frame metadata headers.

Here is a complete C++ implementation of a slotted-page storage manager for variable-length database records inside fixed-size pages.

```cpp
#include <iostream>
#include <vector>
#include <cstring>
#include <cstdint>
#include <stdexcept>

constexpr size_t PAGE_SIZE = 4096;

struct Slot {
    uint16_t offset;
    uint16_t length;
    bool is_deleted;
};

class SlottedPage {
private:
    uint8_t data[PAGE_SIZE];

    uint16_t& get_num_slots_ref() {
        return *reinterpret_cast<uint16_t*>(data);
    }

    uint16_t& get_free_space_pointer_ref() {
        return *reinterpret_cast<uint16_t*>(data + 2);
    }

    Slot* get_slot_array() {
        return reinterpret_cast<Slot*>(data + 4);
    }

public:
    SlottedPage() {
        std::memset(data, 0, PAGE_SIZE);
        get_num_slots_ref() = 0;
        get_free_space_pointer_ref() = PAGE_SIZE;
    }

    int insert_record(const uint8_t* record_data, uint16_t record_len) {
        uint16_t num_slots = get_num_slots_ref();
        uint16_t free_space_ptr = get_free_space_pointer_ref();

        size_t needed_space = sizeof(Slot) + record_len;
        size_t current_free = free_space_ptr - (4 + (num_slots + 1) * sizeof(Slot));

        if (current_free < needed_space) {
            return -1; // Insufficient space
        }

        uint16_t new_data_offset = free_space_ptr - record_len;
        std::memcpy(data + new_data_offset, record_data, record_len);

        Slot* slots = get_slot_array();
        slots[num_slots].offset = new_data_offset;
        slots[num_slots].length = record_len;
        slots[num_slots].is_deleted = false;

        get_num_slots_ref()++;
        get_free_space_pointer_ref() = new_data_offset;

        return num_slots;
    }

    bool get_record(uint16_t slot_id, const uint8_t*& out_data, uint16_t& out_len) {
        uint16_t num_slots = get_num_slots_ref();
        if (slot_id >= num_slots) {
            return false;
        }
        Slot* slots = get_slot_array();
        if (slots[slot_id].is_deleted) {
            return false;
        }

        out_data = data + slots[slot_id].offset;
        out_len = slots[slot_id].length;
        return true;
    }

    size_t get_free_space_bytes() const {
        uint16_t num_slots = *reinterpret_cast<const uint16_t*>(data);
        uint16_t free_space_ptr = *reinterpret_cast<const uint16_t*>(data + 2);
        size_t slot_array_end = 4 + num_slots * sizeof(Slot);
        if (free_space_ptr < slot_array_end) return 0;
        return free_space_ptr - slot_array_end;
    }
};

int main() {
    SlottedPage page;
    const char* tuple1 = "Hello Database World";
    int slot_id = page.insert_record(reinterpret_cast<const uint8_t*>(tuple1), std::strlen(tuple1));

    std::cout << "Inserted tuple at slot: " << slot_id << std::endl;
    std::cout << "Remaining free space: " << page.get_free_space_bytes() << " bytes" << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(L)$ where $L$ is the record length, for memory copying into the slotted page payload area.
- **Space Complexity**: $\mathcal{O}(1)$ auxiliary space operating directly within a fixed 4KB memory-mapped page frame.

Here is a complete, production-ready C++ implementation of a B+ Tree node split mechanism.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <memory>
#include <stdexcept>

template<typename Key, typename Value, size_t Degree>
class BPlusTree {
public:
    static_assert(Degree >= 4, "B+ Tree Degree must be at least 4 for valid splitting invariants.");

    enum class NodeType { INTERNAL, LEAF };

    struct Node {
        NodeType type;
        bool is_leaf;
        size_t num_keys;
        std::vector<Key> keys;
        std::vector<Node*> children; // Used if INTERNAL
        std::vector<Value> values;   // Used if LEAF
        Node* next;
        Node* prev;

        Node(NodeType t) : type(t), is_leaf(t == NodeType::LEAF), num_keys(0), next(nullptr), prev(nullptr) {
            if (is_leaf) {
                keys.resize(Degree);
                values.resize(Degree);
                children.resize(0);
            } else {
                keys.resize(Degree);
                children.resize(Degree + 1);
                values.resize(0);
            }
        }

        ~Node() = default;
    };

    BPlusTree() : root(new Node(NodeType::LEAF)) {}

    ~BPlusTree() {
        clear(root);
    }

    void insert(const Key& key, const Value& value) {
        if (root->num_keys == Degree - 1) {
            Node* new_root = new Node(NodeType::INTERNAL);
            new_root->children[0] = root;
            split_child(new_root, 0, root);
            root = new_root;
        }
        insert_non_full(root, key, value);
    }

    void split_child(Node* parent, size_t index, Node* child) {
        if (!parent || !child) {
            throw std::invalid_argument("Parent and child pointers cannot be null during split.");
        }

        size_t mid = Degree / 2;
        Node* right_node = new Node(child->type);

        if (child->is_leaf) {
            right_node->num_keys = child->num_keys - mid;
            for (size_t i = 0; i < right_node->num_keys; ++i) {
                right_node->keys[i] = child->keys[mid + i];
                right_node->values[i] = child->values[mid + i];
            }
            child->num_keys = mid;

            // Maintain leaf doubly linked list
            right_node->next = child->next;
            if (right_node->next) {
                right_node->next->prev = right_node;
            }
            child->next = right_node;
            right_node->prev = child;

            // Shift parent children and keys
            for (size_t i = parent->num_keys + 1; i > index + 1; --i) {
                parent->children[i] = parent->children[i - 1];
            }
            parent->children[index + 1] = right_node;

            for (size_t i = parent->num_keys; i > index; --i) {
                parent->keys[i] = parent->keys[i - 1];
            }
            parent->keys[index] = right_node->keys[0]; // Copy up for leaf split
            parent->num_keys++;

        } else {
            right_node->num_keys = child->num_keys - mid - 1;
            Key promoted_key = child->keys[mid];

            for (size_t i = 0; i < right_node->num_keys; ++i) {
                right_node->keys[i] = child->keys[mid + 1 + i];
            }
            for (size_t i = 0; i <= right_node->num_keys; ++i) {
                right_node->children[i] = child->children[mid + 1 + i];
            }
            child->num_keys = mid;

            for (size_t i = parent->num_keys + 1; i > index + 1; --i) {
                parent->children[i] = parent->children[i - 1];
            }
            parent->children[index + 1] = right_node;

            for (size_t i = parent->num_keys; i > index; --i) {
                parent->keys[i] = parent->keys[i - 1];
            }
            parent->keys[index] = promoted_key;
            parent->num_keys++;
        }
    }

private:
    Node* root;

    void insert_non_full(Node* node, const Key& key, const Value& value) {
        int i = static_cast<int>(node->num_keys) - 1;
        if (node->is_leaf) {
            while (i >= 0 && key < node->keys[i]) {
                node->keys[i + 1] = node->keys[i];
                node->values[i + 1] = node->values[i];
                i--;
            }
            node->keys[i + 1] = key;
            node->values[i + 1] = value;
            node->num_keys++;
        } else {
            while (i >= 0 && key < node->keys[i]) {
                i--;
            }
            i++;
            if (node->children[i]->num_keys == Degree - 1) {
                split_child(node, i, node->children[i]);
                if (key > node->keys[i]) {
                    i++;
                }
            }
            insert_non_full(node->children[i], key, value);
        }
    }

    void clear(Node* node) {
        if (!node) return;
        if (!node->is_leaf) {
            for (size_t i = 0; i <= node->num_keys; ++i) {
                clear(node->children[i]);
            }
        }
        delete node;
    }
};

int main() {
    BPlusTree<int, std::string, 4> tree;
    tree.insert(10, "ten");
    tree.insert(20, "twenty");
    tree.insert(5, "five");
    tree.insert(6, "six");
    tree.insert(12, "twelve");
    std::cout << "B+ Tree split verification completed successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: Node split operations run in $O(B)$ time where $B$ is the node capacity (Degree), required to shift keys and pointers. Total insertion time is $O(\log_B N)$ due to tree height traversal.
- **Space Complexity**: $O(B)$ auxiliary space during a split for allocating the new sibling node and copying elements.

Here is a complete C++ implementation of an LRU Buffer Pool Manager.

```cpp
#include <iostream>
#include <unordered_map>
#include <list>
#include <vector>
#include <cstring>
#include <stdexcept>

using page_id_t = int;
const size_t PAGE_SIZE = 4096;

struct Page {
    page_id_t id = -1;
    int pin_count = 0;
    bool is_dirty = false;
    char data[PAGE_SIZE];

    void reset() {
        id = -1;
        pin_count = 0;
        is_dirty = false;
        std::memset(data, 0, PAGE_SIZE);
    }
};

class DiskSimulator {
public:
    void read_page(page_id_t page_id, char* page_data) {
        // Simulate reading from disk into page frame
        std::memset(page_data, static_cast<int>(page_id), PAGE_SIZE);
    }

    void write_page(page_id_t page_id, const char* page_data) {
        // Simulate writing dirty page to disk
        (void)page_id;
        (void)page_data;
    }
};

class LRUBufferPoolManager {
private:
    size_t pool_size;
    DiskSimulator& disk;
    std::vector<Page> frames;
    std::list<page_id_t> lru_list;
    std::unordered_map<page_id_t, std::list<page_id_t>::iterator> page_table;
    std::vector<page_id_t> free_list;

public:
    LRUBufferPoolManager(size_t pool_size, DiskSimulator& disk_sim)
        : pool_size(pool_size), disk(disk_sim) {
        frames.resize(pool_size);
        for (size_t i = 0; i < pool_size; ++i) {
            free_list.push_back(static_cast<page_id_t>(i));
        }
    }

    Page* fetch_page(page_id_t page_id) {
        if (page_table.find(page_id) != page_table.end()) {
            // Page is in buffer pool
            auto lru_iter = page_table[page_id];
            // Since we use frame indices or page IDs in LRU list, let's map page_id directly
            lru_list.erase(lru_iter);
            lru_list.push_front(page_id);

            // Find frame index
            for (size_t i = 0; i < pool_size; ++i) {
                if (frames[i].id == page_id) {
                    frames[i].pin_count++;
                    return &frames[i];
                }
            }
        }

        // Page not in buffer pool, need to evict or use free frame
        page_id_t victim_page_id = -1;
        size_t frame_index = 0;

        if (!free_list.empty()) {
            frame_index = static_cast<size_t>(free_list.back());
            free_list.pop_back();
        } else {
            // Evict from LRU list
            bool evicted = false;
            for (auto it = lru_list.rbegin(); it != lru_list.rend(); ++it) {
                page_id_t candidate_id = *it;
                // Find frame for candidate and check pin count
                for (size_t i = 0; i < pool_size; ++i) {
                    if (frames[i].id == candidate_id && frames[i].pin_count == 0) {
                        victim_page_id = candidate_id;
                        frame_index = i;
                        lru_list.erase(std::next(it).base());
                        evicted = true;
                        break;
                    }
                }
                if (evicted) break;
            }
            if (!evicted) {
                throw std::runtime_error("All buffer pool frames are pinned! Cannot evict.");
            }

            page_table.erase(victim_page_id);
            if (frames[frame_index].is_dirty) {
                disk.write_page(frames[frame_index].id, frames[frame_index].data);
            }
        }

        // Load new page into frame_index
        Page& target_frame = frames[frame_index];
        target_frame.reset();
        target_frame.id = page_id;
        target_frame.pin_count = 1;
        disk.read_page(page_id, target_frame.data);

        lru_list.push_front(page_id);
        page_table[page_id] = lru_list.begin();

        return &target_frame;
    }

    bool unpin_page(page_id_t page_id, bool is_dirty) {
        auto it = page_table.find(page_id);
        if (it == page_table.end()) return false;

        for (size_t i = 0; i < pool_size; ++i) {
            if (frames[i].id == page_id) {
                if (frames[i].pin_count <= 0) return false;
                frames[i].pin_count--;
                if (is_dirty) {
                    frames[i].is_dirty = true;
                }
                return true;
            }
        }
        return false;
    }
};

int main() {
    DiskSimulator disk;
    LRUBufferPoolManager bpm(3, disk);
    Page* p1 = bpm.fetch_page(101);
    bpm.unpin_page(101, true);
    Page* p2 = bpm.fetch_page(102);
    bpm.unpin_page(102, false);
    std::cout << "LRU Buffer Pool verification passed." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: Page fetch, unpin, and eviction operations execute in $O(1)$ amortized time utilizing hash map lookups combined with a doubly-linked LRU list.
- **Space Complexity**: $O(P)$ where $P$ is the number of buffer pool frames allocated.

Here is a complete C++ implementation of a slotted-page database storage layout parser and record inserter.

```cpp
#include <iostream>
#include <vector>
#include <cstring>
#include <cstdint>
#include <stdexcept>

class SlottedPage {
private:
    static constexpr size_t PAGE_SIZE = 4096;

    struct Slot {
        uint16_t offset;
        uint16_t length;
    };

    struct PageHeader {
        uint16_t slot_count;
        uint16_t free_space_pointer;
    };

    char data[PAGE_SIZE];

public:
    SlottedPage() {
        clear();
    }

    void clear() {
        std::memset(data, 0, PAGE_SIZE);
        PageHeader header{0, static_cast<uint16_t>(PAGE_SIZE)};
        std::memcpy(data, &header, sizeof(PageHeader));
    }

    int16_t insert_record(const char* record_data, uint16_t record_length) {
        PageHeader header;
        std::memcpy(&header, data, sizeof(PageHeader));

        size_t needed_space = sizeof(Slot) + record_length;
        size_t current_free_space = header.free_space_pointer - (sizeof(PageHeader) + header.slot_count * sizeof(Slot));

        if (current_free_space < needed_space) {
            return -1; // Page full or fragmentation requires compaction
        }

        uint16_t new_free_pointer = header.free_space_pointer - record_length;
        std::memcpy(data + new_free_pointer, record_data, record_length);

        Slot new_slot{new_free_pointer, record_length};
        size_t slot_array_offset = sizeof(PageHeader) + header.slot_count * sizeof(Slot);
        std::memcpy(data + slot_array_offset, &new_slot, sizeof(Slot));

        header.slot_count++;
        header.free_space_pointer = new_free_pointer;
        std::memcpy(data, &header, sizeof(PageHeader));

        return static_cast<int16_t>(header.slot_count - 1);
    }

    bool get_record(uint16_t slot_id, char* buffer, uint16_t& out_length) const {
        PageHeader header;
        std::memcpy(&header, data, sizeof(PageHeader));

        if (slot_id >= header.slot_count) {
            return false;
        }

        size_t slot_offset = sizeof(PageHeader) + slot_id * sizeof(Slot);
        Slot slot;
        std::memcpy(&slot, data + slot_offset, sizeof(Slot));

        if (slot.length == 0) {
            return false; // Deleted tombstone
        }

        out_length = slot.length;
        std::memcpy(buffer, data + slot.offset, slot.length);
        return true;
    }
};

int main() {
    SlottedPage page;
    const char* rec1 = "SELECT * FROM users;";
    int16_t id1 = page.insert_record(rec1, std::strlen(rec1) + 1);

    char buffer[256];
    uint16_t len = 0;
    if (page.get_record(id1, buffer, len)) {
        std::cout << "Retrieved Slotted Record: " << buffer << std::endl;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: Inserting a record and retrieving via slot index runs in $O(1)$ time.
- **Space Complexity**: $O(R)$ where $R$ is record size stored directly inside the fixed 4KB page buffer.

Here is the complete implementation of a B+ Tree Leaf Node in C++:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>

template <typename Key, typename Value, size_t Capacity>
class BPlusTreeLeafNode {
public:
    size_t num_keys;
    Key keys[Capacity];
    Value values[Capacity];
    BPlusTreeLeafNode* next;
    BPlusTreeLeafNode* prev;

    BPlusTreeLeafNode() : num_keys(0), next(nullptr), prev(nullptr) {}

    bool IsFull() const {
        return num_keys >= Capacity;
    }

    bool IsUnderfull(size_t min_capacity) const {
        return num_keys < min_capacity;
    }

    int Find(const Key& key) const {
        auto it = std::lower_bound(keys, keys + num_keys, key);
        int idx = std::distance(keys, it);
        if (idx < num_keys && keys[idx] == key) {
            return idx;
        }
        return -1;
    }

    bool Insert(const Key& key, const Value& value) {
        auto it = std::lower_bound(keys, keys + num_keys, key);
        size_t idx = std::distance(keys, it);

        if (idx < num_keys && keys[idx] == key) {
            values[idx] = value;
            return true;
        }

        if (IsFull()) {
            return false;
        }

        for (size_t i = num_keys; i > idx; --i) {
            keys[i] = keys[i - 1];
            values[i] = values[i - 1];
        }

        keys[idx] = key;
        values[idx] = value;
        ++num_keys;
        return true;
    }

    BPlusTreeLeafNode* Split(Key& promoted_key) {
        assert(IsFull());
        size_t split_idx = num_keys / 2;

        BPlusTreeLeafNode* new_node = new BPlusTreeLeafNode();
        size_t move_count = num_keys - split_idx;

        for (size_t i = 0; i < move_count; ++i) {
            new_node->keys[i] = keys[split_idx + i];
            new_node->values[i] = values[split_idx + i];
        }

        new_node->num_keys = move_count;
        num_keys = split_idx;

        new_node->next = next;
        new_node->prev = this;
        if (next != nullptr) {
            next->prev = new_node;
        }
        next = new_node;

        promoted_key = new_node->keys[0];
        return new_node;
    }
};

int main() {
    BPlusTreeLeafNode<int, std::string, 4> leaf;
    leaf.Insert(10, "A");
    leaf.Insert(20, "B");
    leaf.Insert(30, "C");
    leaf.Insert(40, "D");
    assert(leaf.IsFull() == true);

    int promoted = 0;
    BPlusTreeLeafNode<int, std::string, 4>* right_node = leaf.Split(promoted);

    assert(promoted == 30);
    assert(leaf.num_keys == 2);
    assert(right_node->num_keys == 2);
    assert(right_node->keys[0] == 30);

    delete right_node;
    std::cout << "B+ Tree Leaf Node operations verified successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** 
  - Search: $O(\log N)$ via binary search (`std::lower_bound`).
  - Insertion: $O(N)$ due to element shifting in arrays to maintain sorted order.
  - Split: $O(N)$ to copy half of the elements to the new sibling node.
- **Space Complexity:** $O(Capacity)$ per node block allocated statically or dynamically.

Here is the complete C++ LRU Buffer Pool implementation:

```cpp
#iostream
#include <iostream>
#include <unordered_map>
#include <list>
#include <cassert>

typedef int page_id_t;

struct Page {
    page_id_t page_id;
    int pin_count;
    bool is_dirty;
    char data[4096];

    Page() : page_id(-1), pin_count(0), is_dirty(false) {}
};

class LRUBufferPool {
private:
    size_t capacity;
    std::unordered_map<page_id_t, std::pair<Page, std::list<page_id_t>::iterator>> pool;
    std::list<page_id_t> lru_list;

public:
    explicit LRUBufferPool(size_t cap) : capacity(cap) {}

    Page* FetchPage(page_id_t page_id) {
        auto it = pool.find(page_id);
        if (it != pool.end()) {
            it->second.first.pin_count++;
            lru_list.erase(it->second.second);
            lru_list.push_front(page_id);
            it->second.second = lru_list.begin();
            return &(it->second.first);
        }

        if (pool.size() >= capacity) {
            bool evicted = false;
            for (auto rev_it = lru_list.rbegin(); rev_it != lru_list.rend(); ++rev_it) {
                page_id_t victim_id = *rev_it;
                if (pool[victim_id].first.pin_count == 0) {
                    pool.erase(victim_id);
                    lru_list.erase(std::next(rev_it).base());
                    evicted = true;
                    break;
                }
            }
            if (!evicted) {
                return nullptr;
            }
        }

        Page new_page;
        new_page.page_id = page_id;
        new_page.pin_count = 1;
        lru_list.push_front(page_id);
        pool[page_id] = {new_page, lru_list.begin()};
        return &(pool[page_id].first);
    }

    bool UnpinPage(page_id_t page_id, bool is_dirty) {
        auto it = pool.find(page_id);
        if (it == pool.end()) {
            return false;
        }
        if (is_dirty) {
            it->second.first.is_dirty = true;
        }
        if (it->second.first.pin_count > 0) {
            it->second.first.pin_count--;
        }
        return true;
    }

    size_t Size() const {
        return pool.size();
    }
};

int main() {
    LRUBufferPool bp(2);
    Page* p1 = bp.FetchPage(1);
    assert(p1 != nullptr);
    bp.UnpinPage(1, false);

    Page* p2 = bp.FetchPage(2);
    assert(p2 != nullptr);
    bp.UnpinPage(2, false);

    Page* p3 = bp.FetchPage(3);
    assert(p3 != nullptr);

    std::cout << "LRU Buffer Pool verified successfully." << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** 
  - FetchPage: $O(1)$ average time complexity for hash map lookups and linked list node reordering.
  - UnpinPage: $O(1)$ map lookup and state update.
- **Space Complexity:** $O(C)$ where $C$ is the maximum capacity of the buffer pool.

