enum LogRecordType { BEGIN = 1, UPDATE = 2, COMMIT = 3, ABORT = 4 };

struct LogRecord {
    uint64_t length;
    uint64_t lsn;
    uint32_t tx_id;
    uint32_t type;
    std::string payload;
};

class WALRecoveryManager {
public:
    static std::unordered_set<uint32_t> AnalyzeLog(const std::vector<LogRecord>& log_records) {
        std::unordered_set<uint32_t> active_transactions;

        for (const auto& record : log_records) {
            switch (record.type) {
                case LogRecordType::BEGIN:
                    active_transactions.insert(record.tx_id);
                    break;
                case LogRecordType::COMMIT:
                case LogRecordType::ABORT:
                    active_transactions.erase(record.tx_id);
                    break;
                case LogRecordType::UPDATE:
                    break;
                default:
                    break;
            }
        }
        return active_transactions;
    }
};

int main() {
    std::vector<LogRecord> logs = {
        {30, 1, 101, LogRecordType::BEGIN, ""},
        {40, 2, 101, LogRecordType::UPDATE, "x=1"},
        {30, 3, 102, LogRecordType::BEGIN, ""},
        {30, 4, 101, LogRecordType::COMMIT, ""}
    };

    std::unordered_set<uint32_t> active = WALRecoveryManager::AnalyzeLog(logs);

    assert(active.find(101) == active.end());
    assert(active.find(102) != active.end());

    std::cout << "WAL Recovery Analysis verified successfully." << std::endl;
    return 0;
}
