```cpp
#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>
#include <memory>

constexpr size_t PAGE_SIZE = 4096;

typedef uint64_t LSN;

template <typename KeyType, typename ValType, size_t M>
class BPlusTreeLeafNode {
public:
    KeyType keys[M];
    ValType values[M];
    size_t num_keys;
    bool is_leaf;
    BPlusTreeLeafNode* next;
    BPlusTreeLeafNode* prev;

    BPlusTreeLeafNode() : num_keys(0), is_leaf(true), next(nullptr), prev(nullptr) {
        std::memset(keys, 0, sizeof(keys));
        std::memset(values, 0, sizeof(values));
    }

    ~BPlusTreeLeafNode() = default;

    bool IsFull() const {
        return num_keys >= M;
    }

    int FindLowerBound(const KeyType& key) const {
        int left = 0;
        int right = static_cast<int>(num_keys) - 1;
        int ans = static_cast<int>(num_keys);
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (keys[mid] >= key) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return ans;
    }

    bool Insert(const KeyType& key, const ValType& val, BPlusTreeLeafNode*& new_sibling, KeyType& promoted_key) {
        if (num_keys >= M) {
            return false;
        }
        int idx = FindLowerBound(key);
        if (idx < static_cast<int>(num_keys) && keys[idx] == key) {
            values[idx] = val;
            return true;
        }
        for (int i = static_cast<int>(num_keys); i > idx; --i) {
            keys[i] = keys[i - 1];
            values[i] = values[i - 1];
        }
        keys[idx] = key;
        values[idx] = val;
        num_keys++;

        if (num_keys == M) {
            new_sibling = new BPlusTreeLeafNode();
            size_t split_idx = M / 2;
            size_t move_count = M - split_idx;

            for (size_t i = 0; i < move_count; ++i) {
                new_sibling->keys[i] = keys[split_idx + i];
                new_sibling->values[i] = values[split_idx + i];
            }
            new_sibling->num_keys = move_count;
            num_keys = split_idx;

            new_sibling->next = this->next;
            new_sibling->prev = this;
            if (this->next) {
                this->next->prev = new_sibling;
            }
            this->next = new_sibling;
            promoted_key = new_sibling->keys[0];
            return true;
        }
        return true;
    }
};

int main() {
    BPlusTreeLeafNode<int, int, 4>* leaf = new BPlusTreeLeafNode<int, int, 4>();
    BPlusTreeLeafNode<int, int, 4>* sibling = nullptr;
    int promoted = 0;

    leaf->Insert(10, 100, sibling, promoted);
    leaf->Insert(30, 300, sibling, promoted);
    leaf->Insert(20, 200, sibling, promoted);
    bool res = leaf->Insert(40, 400, sibling, promoted);

    std::cout << "Insertion result: " << (res ? "Success" : "Failed") << std::endl;
    std::cout << "Original node keys: ";
    for(size_t i=0; i<leaf->num_keys; ++i) std::cout << leaf->keys[i] << " ";
    std::cout << std::endl;

    if (sibling) {
        std::cout << "Sibling node keys: ";
        for(size_t i=0; i<sibling->num_keys; ++i) std::cout << sibling->keys[i] << " ";
        std::cout << std::endl;
        std::cout << "Promoted Key: " << promoted << std::endl;
        delete sibling;
    }
    delete leaf;
    return 0;
}
