### Complexity Analysis
- **Time Complexity**: Insertion takes $O(M)$ in the worst case due to shifting elements within the fixed-capacity node array, where $M$ is the maximum node capacity. Finding the insertion position using binary search takes $O(\log M)$.
- **Space Complexity**: $O(M)$ auxiliary space per node, fitting inside standard database page boundaries (e.g., 4KB).

```cpp
#include <iostream>
#include <unordered_map>
#include <list>
#include <vector>
#include <stdexcept>

typedef int page_id_t;
constexpr size_t PAGE_SIZE = 4096;

struct Page {
    page_id_t page_id;
    int pin_count;
    bool is_dirty;
    char data[PAGE_SIZE];

    Page() : page_id(-1), pin_count(0), is_dirty(false) {
        std::fill(data, data + PAGE_SIZE, 0);
    }

    void Reset() {
        page_id = -1;
        pin_count = 0;
        is_dirty = false;
        std::fill(data, data + PAGE_SIZE, 0);
    }
};

class LRUBufferPoolManager {
private:
    size_t pool_size;
    std::vector<Page> pages;
    std::list<page_id_t> lru_list;
    std::unordered_map<page_id_t, std::list<page_id_t>::iterator> page_table;

    bool Evict(page_id_t* evicted_page_id) {
        if (lru_list.empty()) {
            return false;
        }
        page_id_t victim_id = lru_list.back();
        lru_list.pop_back();
        page_table.erase(victim_id);
        *evicted_page_id = victim_id;
        return true;
    }

public:
    explicit LRUBufferPoolManager(size_t pool_size) : pool_size(pool_size) {
        pages.resize(pool_size);
    }

    Page* FetchPage(page_id_t page_id) {
        if (page_table.find(page_id) != page_table.end()) {
            auto it = page_table[page_id];
            lru_list.erase(it);
            lru_list.push_front(page_id);
            page_table[page_id] = lru_list.begin();

            size_t index = 0;
            for (size_t i = 0; i < pool_size; ++i) {
                if (pages[i].page_id == page_id) {
                    pages[i].pin_count++;
                    return &pages[i];
                }
            }
        }

        page_id_t victim_id;
        size_t candidate_index = pool_size;
        for (size_t i = 0; i < pool_size; ++i) {
            if (pages[i].page_id == -1) {
                candidate_index = i;
                break;
            }
        }

        if (candidate_index == pool_size) {
            if (!Evict(&victim_id)) {
                throw std::runtime_error("All pages are pinned; cannot evict.");
            }
            for (size_t i = 0; i < pool_size; ++i) {
                if (pages[i].page_id == victim_id) {
                    candidate_index = i;
                    break;
                }
            }
        }

        Page* page = &pages[candidate_index];
        page->Reset();
        page->page_id = page_id;
        page->pin_count = 1;
        page->is_dirty = false;

        lru_list.push_front(page_id);
        page_table[page_id] = lru_list.begin();
        return page;
    }

    bool UnpinPage(page_id_t page_id, bool is_dirty) {
        if (page_table.find(page_id) == page_table.end()) {
            return false;
        }
        for (size_t i = 0; i < pool_size; ++i) {
            if (pages[i].page_id == page_id) {
                if (pages[i].pin_count <= 0) {
                    return false;
                }
                if (is_dirty) {
                    pages[i].is_dirty = true;
                }
                pages[i].pin_count--;
                return true;
            }
        }
        return false;
    }
};

int main() {
    LRUBufferPoolManager bpm(2);
    Page* p1 = bpm.FetchPage(1);
    p1->data[0] = 'X';
    bpm.UnpinPage(1, true);

    Page* p2 = bpm.FetchPage(2);
    bpm.UnpinPage(2, false);

    Page* p3 = bpm.FetchPage(3);
    std::cout << "Fetched page 3 successfully after eviction." << std::endl;
    bpm.UnpinPage(3, false);
    return 0;
}
```
### Complexity Analysis
- **Time Complexity**: $O(1)$ amortized for page fetch, unpin, and eviction operations via hash map indexing and doubly-linked list adjustments.
- **Space Complexity**: $O(P)$ memory footprint where $P$ is the buffer pool capacity containing fixed-size page frames.

