template <typename KeyType, typename ValType, size_t M>
bool MergeLeafNodes(LeafNode<KeyType, ValType, M>* left, LeafNode<KeyType, ValType, M>* right) {
    if (!left || !right) {
        return false;
    }
    size_t min_capacity = (M - 1) / 2;
    if (left->num_keys + right->num_keys >= M) {
        return false;
    }

    for (size_t i = 0; i < right->num_keys; ++i) {
        left->keys[left->num_keys + i] = right->keys[i];
        left->values[left->num_keys + i] = right->values[i];
    }
    left->num_keys += right->num_keys;

    left->next = right->next;
    if (right->next) {
        right->next->prev = left;
    }

    delete right;
    return true;
}

