Here is the complete C++ implementation of a Clock Buffer Pool manager with frame pinning, dirty tracking, and cyclic hand sweep eviction.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <cassert>

class ClockBufferPool {
private:
    struct Frame {
        int frame_id;
        int page_id;
        bool ref_bit;
        bool is_dirty;
        int pin_count;

        Frame(int fid) : frame_id(fid), page_id(-1), ref_bit(false), is_dirty(false), pin_count(0) {}
    };

    size_t pool_size;
    size_t clock_hand;
    std::vector<Frame> frames;
    std::unordered_map<int, int> page_to_frame;

public:
    explicit ClockBufferPool(size_t size) : pool_size(size), clock_hand(0) {
        frames.reserve(pool_size);
        for (size_t i = 0; i < pool_size; ++i) {
            frames.emplace_back(static_cast<int>(i));
        }
    }

    int FetchPage(int page_id, bool is_dirty) {
        if (page_to_frame.find(page_id) != page_to_frame.end()) {
            int frame_id = page_to_frame[page_id];
            frames[frame_id].pin_count++;
            frames[frame_id].ref_bit = true;
            if (is_dirty) {
                frames[frame_id].is_dirty = true;
            }
            return frame_id;
        }

        int victim_frame_id = Evict();
        if (victim_frame_id == -1) {
            return -1;
        }

        Frame& victim = frames[victim_frame_id];
        if (victim.page_id != -1) {
            page_to_frame.erase(victim.page_id);
        }

        victim.page_id = page_id;
        victim.pin_count = 1;
        victim.ref_bit = true;
        victim.is_dirty = is_dirty;

        page_to_frame[page_id] = victim_frame_id;
        return victim_frame_id;
    }

    bool UnpinPage(int page_id, bool is_dirty) {
        if (page_to_frame.find(page_id) == page_to_frame.end()) {
            return false;
        }
        int frame_id = page_to_frame[page_id];
        Frame& frame = frames[frame_id];
        if (frame.pin_count <= 0) {
            return false;
        }
        if (is_dirty) {
            frame.is_dirty = true;
        }
        frame.pin_count--;
        return true;
    }

private:
    int Evict() {
        size_t scanned = 0;
        while (scanned < pool_size * 2) {
            Frame& frame = frames[clock_hand];
            if (frame.pin_count == 0) {
                if (!frame.ref_bit) {
                    int victim_id = static_cast<int>(clock_hand);
                    clock_hand = (clock_hand + 1) % pool_size;
                    return victim_id;
                }
                frame.ref_bit = false;
            }
            clock_hand = (clock_hand + 1) % pool_size;
            scanned++;
        }
        return -1; 
    }
};

int main() {
    ClockBufferPool bp(3);

    int f0 = bp.FetchPage(101, false);
    int f1 = bp.FetchPage(102, false);
    int f2 = bp.FetchPage(103, false);

    assert(f0 != -1 && f1 != -1 && f2 != -1);

    assert(bp.UnpinPage(101, false));
    assert(bp.UnpinPage(102, false));

    int f3 = bp.FetchPage(104, false);
    assert(f3 != -1);

    std::cout << "Clock Buffer Pool Eviction Test Passed Successfully!" << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** 
  - Fetch/Evict: $\mathcal{O}(P)$ in the worst case where $P$ is the pool capacity, due to the Clock hand sweeping across all pinned/unpinned frames.
  - Unpin: $\mathcal{O}(1)$ via hash map lookup.
- **Space Complexity:** $\mathcal{O}(P)$ space to maintain buffer slots and page-to-frame maps.

Here is the complete C++ implementation of a B+ Tree internal node underflow merger and key redistribution algorithm.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>

struct BPlusTreeInternalNode {
    std::vector<int> keys;
    std::vector<BPlusTreeInternalNode*> children;

    bool IsUnderfull(size_t min_keys) const {
        return keys.size() < min_keys;
    }

    bool BorrowFromLeft(BPlusTreeInternalNode* left_sibling, int parent_key_index, std::vector<int>& parent_keys) {
        if (left_sibling->keys.size() <= 1) {
            return false;
        }

        int borrowed_key = left_sibling->keys.back();
        left_sibling->keys.pop_back();

        BPlusTreeInternalNode* borrowed_child = left_sibling->children.back();
        left_sibling->children.pop_back();

        keys.insert(keys.begin(), parent_keys[parent_key_index]);
        parent_keys[parent_key_index] = borrowed_key;

        children.insert(children.begin(), borrowed_child);
        return true;
    }

    void MergeWithRight(BPlusTreeInternalNode* right_sibling, int parent_key) {
        keys.push_back(parent_key);
        keys.insert(keys.end(), right_sibling->keys.begin(), right_sibling->keys.end());
        children.insert(children.end(), right_sibling->children.begin(), right_sibling->children.end());
    }
};

int main() {
    BPlusTreeInternalNode parent;
    parent.keys = {10, 20, 30};

    auto* left = new BPlusTreeInternalNode();
    left->keys = {5};
    left->children = {nullptr, nullptr};

    auto* right = new BPlusTreeInternalNode();
    right->keys = {15};
    right->children = {nullptr, nullptr};

    parent.children = {nullptr, left, right, nullptr};

    bool borrowed = right->BorrowFromLeft(left, 0, parent.keys);
    assert(borrowed);
    assert(right->keys.size() == 2);
    assert(left->keys.empty());

    delete left;
    delete right;

    std::cout << "B+ Tree Internal Node Redistribution Test Passed Successfully!" << std::endl;
    return 0;
}
```

