- **Time Complexity:** 
  - Borrow: $\mathcal{O}(K)$ where $K$ is the number of keys, due to vector element insertion and shifting.
  - Merge: $\mathcal{O}(K)$ to concatenate keys and child pointers.
- **Space Complexity:** $\mathcal{O}(K)$ auxiliary memory per node data structure.

Here is the complete C++ implementation of a B+ Tree leaf node with split, merge, and redistribution logic.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>

template <typename KeyType, typename ValueType, size_t MaxCapacity = 4>
class BPlusTreeLeafNode {
public:
    struct Result {
        bool success;
        std::string message;
    };

    std::vector<KeyType> keys;
    std::vector<ValueType> values;
    BPlusTreeLeafNode* next;
    BPlusTreeLeafNode* prev;

    BPlusTreeLeafNode() : next(nullptr), prev(nullptr) {
        keys.reserve(MaxCapacity + 1);
        values.reserve(MaxCapacity + 1);
    }

    ~BPlusTreeLeafNode() = default;

    bool IsOverflow() const {
        return keys.size() > MaxCapacity;
    }

    bool IsUnderflow(size_t min_capacity) const {
        return keys.size() < min_capacity;
    }

    Result Insert(const KeyType& key, const ValueType& value) {
        auto it = std::lower_bound(keys.begin(), keys.end(), key);
        size_t idx = std::distance(keys.begin(), it);

        if (it != keys.end() && *it == key) {
            return {false, "Key already exists."};
        }

        keys.insert(it, key);
        values.insert(values.begin() + idx, value);
        return {true, "Success."};
    }

    std::pair<KeyType, BPlusTreeLeafNode*> Split() {
        assert(IsOverflow());
        auto* sibling = new BPlusTreeLeafNode();
        size_t split_idx = keys.size() / 2;

        sibling->keys.assign(keys.begin() + split_idx, keys.end());
        sibling->values.assign(values.begin() + split_idx, values.end());

        keys.erase(keys.begin() + split_idx, keys.end());
        values.erase(values.begin() + split_idx, values.end());

        sibling->next = this->next;
        sibling->prev = this;
        if (this->next) {
            this->next->prev = sibling;
        }
        this->next = sibling;

        KeyType promoted_key = sibling->keys.front();
        return {promoted_key, sibling};
    }

    void Merge(BPlusTreeLeafNode* right_sibling) {
        assert(right_sibling != nullptr);
        keys.insert(keys.end(), right_sibling->keys.begin(), right_sibling->keys.end());
        values.insert(values.end(), right_sibling->values.begin(), right_sibling->values.end());

        this->next = right_sibling->next;
        if (this->next) {
            this->next->prev = this;
        }
    }
};

int main() {
    BPlusTreeLeafNode<int, std::string, 3> leaf;
    leaf.Insert(10, "data10");
    leaf.Insert(20, "data20");
    leaf.Insert(30, "data30");

    std::cout << "Initial insertions completed.\n";

    auto res = leaf.Insert(40, "data40");
    if (leaf.IsOverflow()) {
        auto [promoted, sibling] = leaf.Split();
        std::cout << "Split occurred. Promoted key: " << promoted << "\n";
        std::cout << "Left size: " << leaf.keys.size() << ", Right size: " << sibling->keys.size() << "\n";
        delete sibling;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: 
  - `Insert`: $\mathcal{O}(N)$ due to binary search via `std::lower_bound` followed by vector element shifting.
  - `Split`: $\mathcal{O}(N)$ to copy elements to the new sibling node and erase from the current node.
  - `Merge`: $\mathcal{O}(N)$ to append keys and values from the right sibling.
- **Space Complexity**: $\mathcal{O}(N)$ auxiliary memory footprint per node proportional to capacity limits.

Here is the production-grade implementation of Tarjan's SCC algorithm in Python.

```python
import sys
from typing import Dict, List, Set

# Increase recursion depth for deep graphs if required
sys.setrecursionlimit(200000)


class TarjanSCC:
    def __init__(self, num_vertices: int):
        if num_vertices <= 0:
            raise ValueError("Number of vertices must be positive.")
        self.n = num_vertices
        self.adj: Dict[int, List[int]] = {i: [] for i in range(num_vertices)}

    def add_edge(self, u: int, v: int) -> None:
        if not (0 <= u < self.n and 0 <= v < self.n):
            raise IndexError("Vertex index out of range.")
        self.adj[u].append(v)

    def find_sccs(self) -> List[List[int]]:
        disc = [-1] * self.n
        low = [-1] * self.n
        stack_member = [False] * self.n
        st: List[int] = []
        time = [0]
        sccs: List[List[int]] = []

        def dfs(u: int) -> None:
            disc[u] = time[0]
            low[u] = time[0]
            time[0] += 1
            st.append(u)
            stack_member[u] = True

            for v in self.adj[u]:
                if disc[v] == -1:
                    dfs(v)
                    low[u] = min(low[u], low[v])
                elif stack_member[v]:
                    low[u] = min(low[u], disc[v])

            if low[u] == disc[u]:
                current_scc = []
                while True:
                    v = st.pop()
                    stack_member[v] = False
                    current_scc.append(v)
                    if v == u:
                        break
                sccs.append(current_scc)

        for i in range(self.n):
            if disc[i] == -1:
                dfs(i)

        return sccs


if __name__ == "__main__":
    try:
        g = TarjanSCC(5)
        g.add_edge(1, 0)
        g.add_edge(0, 2)
        g.add_edge(2, 1);
        g.add_edge(0, 3);
        g.add_edge(3, 4);

        result = g.find_sccs()
        print("Strongly Connected Components:", result)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(V + E)$ where $V$ is the number of vertices and $E$ is the number of edges, as every vertex and edge is visited exactly once.
- **Space Complexity**: $\mathcal{O}(V)$ to store discovery times, low-link values, stack membership flags, and the recursion stack.

Here is the production-grade Segment Tree implementation with Lazy Propagation in C++.

```cpp
#include <iostream>
#include <vector>
#include <stdexcept>

class SegmentTreeLazy {
private:
    int n;
    std::vector<long long> tree;
    std::vector<long long> lazy;

    void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            int mid = start + (end - start) / 2;

            tree[2 * node] += lazy[node] * (mid - start + 1);
            lazy[2 * node] += lazy[node];

            tree[2 * node + 1] += lazy[node] * (end - mid);
            lazy[2 * node + 1] += lazy[node];

            lazy[node] = 0;
        }
    }

    void update_range(int node, int start, int end, int l, int r, long long val) {
        if (l > end || r < start) return;
        if (l <= start && end <= r) {
            tree[node] += val * (end - start + 1);
            lazy[node] += val;
            return;
        }
        push(node, start, end);
        int mid = start + (end - start) / 2;
        update_range(2 * node, start, mid, l, r, val);
        update_range(2 * node + 1, mid + 1, end, l, r, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long long query_range(int node, int start, int end, int l, int r) {
        if (l > end || r < start) return 0;
        if (l <= start && end <= r) return tree[node];

        push(node, start, end);
        int mid = start + (end - start) / 2;
        return query_range(2 * node, start, mid, l, r) +
               query_range(2 * node + 1, mid + 1, end, l, r);
    }

public:
    explicit SegmentTreeLazy(const std::vector<long long>& data) {
        if (data.empty()) {
            throw std::invalid_argument("Input data cannot be empty.");
        }
        n = data.size();
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        build(1, 0, n - 1, data);
    }

    void build(int node, int start, int end, const std::vector<long long>& data) {
        if (start == end) {
            tree[node] = data[start];
            return;
        }
        int mid = start + (end - start) / 2;
        build(2 * node, start, mid, data);
        build(2 * node + 1, mid + 1, end, data);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void update(int l, int r, long long val) {
        if (l < 0 || r >= n || l > r) {
            throw std::out_of_range("Invalid range boundaries for update.");
        }
        update_range(1, 0, n - 1, l, r, val);
    }

    long long query(int l, int r) {
        if (l < 0 || r >= n || l > r) {
            throw std::out_of_range("Invalid range boundaries for query.");
        }
        return query_range(1, 0, n - 1, l, r);
    }
};

int main() {
    try {
        std::vector<long long> arr = {1, 2, 3, 4, 5};
        SegmentTreeLazy st(arr);

        std::cout << "Initial sum (1, 3): " << st.query(1, 3) << std::endl;
        st.update(1, 3, 2);
        std::cout << "Sum after adding 2 to range (1, 3): " << st.query(1, 3) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(\log N)$ for both range updates and range queries. Array construction takes $\mathcal{O}(N)$ time.
- **Space Complexity**: $\mathcal{O}(N)$ to store the segment tree and lazy propagation state arrays.

Here is the production-grade implementation of the Edmonds-Karp Algorithm in C++.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

class EdmondsKarp {
private:
    int n;
    std::vector<std::vector<long long>> capacity;
    std::vector<std::vector<int>> adj;

public:
    explicit EdmondsKarp(int nodes) : n(nodes), capacity(nodes, std::vector<long long>(nodes, 0)), adj(nodes) {}

    void add_edge(int from, int to, long long cap) {
        if (cap < 0) {
            throw std::invalid_argument("Capacity cannot be negative.");
        }
        if (from < 0 || from >= n || to < 0 || to >= n) {
            throw std::out_of_range("Vertex indices are out of bounds.");
        }
        if (capacity[from][to] == 0 && capacity[to][from] == 0) {
            adj[from].push_back(to);
            adj[to].push_back(from);
        }
        capacity[from][to] += cap;
    }

    long long max_flow(int s, int t) {
        if (s < 0 || s >= n || t < 0 || t >= n) {
            throw std::out_of_range("Source or sink indices are out of bounds.");
        }
        if (s == t) return 0;

        long long flow = 0;
        std::vector<int> parent(n);

        auto bfs = [&](int source, int sink, std::vector<int>& par) -> long long {
            std::fill(par.begin(), par.end(), -1);
            par[source] = -2;
            std::queue<std::pair<int, long long>> q;
            q.push({source, std::numeric_limits<long long>::max()});

            while (!q.empty()) {
                int u = q.front().first;
                long long flow_val = q.front().second;
                q.pop();

                for (int v : adj[u]) {
                    if (par[v] == -1 && capacity[u][v] > 0) {
                        par[v] = u;
                        long long new_flow = std::min(flow_val, capacity[u][v]);
                        if (v == sink) {
                            return new_flow;
                        }
                        q.push({v, new_flow});
                    }
                }
            }
            return 0;
        };

        long long new_flow;
        while ((new_flow = bfs(s, t, parent)) != 0) {
            flow += new_flow;
            int curr = t;
            while (curr != s) {
                int prev = parent[curr];
                capacity[prev][curr] -= new_flow;
                capacity[curr][prev] += new_flow;
                curr = prev;
            }
        }

        return flow;
    }
};

int main() {
    try {
        EdmondsKarp ek(6);
        ek.add_edge(0, 1, 16);
        ek.add_edge(0, 2, 13);
        ek.add_edge(1, 2, 10);
        ek.add_edge(1, 3, 12);
        ek.add_edge(2, 1, 4);
        ek.add_edge(2, 4, 14);
        ek.add_edge(3, 2, 9);
        ek.add_edge(3, 5, 20);
        ek.add_edge(4, 3, 7);
        ek.add_edge(4, 5, 4);

        std::cout << "Max Flow (Edmonds-Karp): " << ek.max_flow(0, 5) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(V E^2)$ where $V$ is the number of vertices and $E$ is the number of edges. The number of augmenting paths is bounded by $\mathcal{O}(V \cdot E)$.
- **Space Complexity**: $\mathcal{O}(V^2)$ to store the residual capacity matrix alongside adjacency lists.

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

class Dinic {
public:
    struct Edge {
        int to;
        long long capacity;
        long long flow;
        int rev;
    };

    int n;
    vector<vector<Edge>> adj;
    vector<int> level;
    vector<int> ptr;

    Dinic(int n) : n(n), adj(n), level(n), ptr(n) {}

    void add_edge(int from, int to, long long capacity) {
        if (from == to) return;
        adj[from].push_back({to, capacity, 0, (int)adj[to].size()});
        adj[to].push_back({from, 0, 0, (int)adj[from].size() - 1});
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (auto& edge : adj[v]) {
                if (edge.capacity - edge.flow > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[v] + 1;
                    q.push(edge.to);
                }
            }
        }
        return level[t] != -1;
    }

    long long dfs(int v, int t, long long pushed) {
        if (pushed == 0) return 0;
        if (v == t) return pushed;
        for (int& cid = ptr[v]; cid < adj[v].size(); ++cid) {
            auto& edge = adj[v][cid];
            int tr = edge.to;
            if (level[v] + 1 != level[tr] || edge.capacity - edge.flow == 0) continue;
            long long tr_pushed = dfs(tr, t, min(pushed, edge.capacity - edge.flow));
            if (tr_pushed == 0) continue;
            edge.flow += tr_pushed;
            adj[tr][edge.rev].flow -= tr_pushed;
            return tr_pushed;
        }
        return 0;
    }

    long long max_flow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, t, 1e18)) {
                flow += pushed;
            }
        }
        return flow;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n = 4, s = 0, t = 3;
    Dinic dinic(n);
    dinic.add_edge(0, 1, 10);
    dinic.add_edge(0, 2, 5);
    dinic.add_edge(1, 2, 15);
    dinic.add_edge(1, 3, 5);
    dinic.add_edge(2, 3, 10);
    cout << "Max Flow: " << dinic.max_flow(s, t) << "\n";
    return 0;
}

/*
Time Complexity:
- Level graph construction via BFS takes O(V + E) time per phase.
- Blocking flow computation via DFS takes O(V * E) time per phase.
- In general graphs, Dinic's algorithm performs at most O(V^2 * E) phases/augmentations.
- For unit networks (where all capacities are 1), the time complexity drops to O(min(V^{2/3}, E^{1/2}) * E).
- For networks with capacities bounded by C, it runs in O(E * V * log C).

Space Complexity:
- O(V + E) to store the adjacency list representation of the network, level arrays, and pointer arrays.
*/

#include <vector>
#include <iostream>
#include <algorithm>

using namespace std;

class LazySegmentTree {
private:
    int n;
    vector<long long> tree;
    vector<long long> lazy;

    void build(const vector<long long>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
            return;
        }
        int mid = start + (end - start) / 2;
        build(arr, 2 * node, start, mid);
        build(arr, 2 * node + 1, mid + 1, end);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            int mid = start + (end - start) / 2;
            tree[2 * node] += lazy[node] * (mid - start + 1);
            lazy[2 * node] += lazy[node];
            tree[2 * node + 1] += lazy[node] * (end - mid);
            lazy[2 * node + 1] += lazy[node];
            lazy[node] = 0;
        }
    }

    void update_range(int node, int start, int end, int l, int r, long long val) {
        if (l > end || r < start) return;
        if (l <= start && end <= r) {
            tree[node] += val * (end - start + 1);
            lazy[node] += val;
            return;
        }
        push(node, start, end);
        int mid = start + (end - start) / 2;
        update_range(2 * node, start, mid, l, r, val);
        update_range(2 * node + 1, mid + 1, end, l, r, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long long query_range(int node, int start, int end, int l, int r) {
        if (l > end || r < start) return 0;
        if (l <= start && end <= r) return tree[node];
        push(node, start, end);
        int mid = start + (end - start) / 2;
        return query_range(2 * node, start, mid, l, r) + query_range(2 * node + 1, mid + 1, end, l, r);
    }

public:
    LazySegmentTree(const vector<long long>& arr) {
        n = arr.size();
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        if (n > 0) build(arr, 1, 0, n - 1);
    }

    void update(int l, int r, long long val) {
        if (l < 0 || r >= n || l > r) return;
        update_range(1, 0, n - 1, l, r, val);
    }

    long long query(int l, int r) {
        if (l < 0 || r >= n || l > r) return 0;
        return query_range(1, 0, n - 1, l, r);
    }
};

int main() {
    vector<long long> arr = {1, 2, 3, 4, 5};
    LazySegmentTree st(arr);
    cout << "Query(1, 3): " << st.query(1, 3) << "\n";
    st.update(1, 3, 2);
    cout << "Query(1, 3) after update: " << st.query(1, 3) << "\n";
    return 0;
}

/*
Time Complexity:
- Construction: O(N) time, visiting each node once.
- Range Update: O(log N) time per query by lazily propagating changes.
- Range Query: O(log N) time per query.

Space Complexity:
- O(N) auxiliary space allocation for the tree array (4 * N size) and lazy array (4 * N size).
*/

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class BridgeFinder {
private:
    int n;
    vector<vector<pair<int, int>>> adj; // pair of {neighbor, edge_id}
    vector<int> disc;
    vector<int> low;
    vector<pair<int, int>> bridges;
    int timer;

    void dfs(int u, int p_edge_id) {
        disc[u] = low[u] = ++timer;
        for (auto& edge : adj[u]) {
            int v = edge.first;
            int edge_id = edge.second;
            if (edge_id == p_edge_id) continue;
            if (disc[v] != -1) {
                low[u] = min(low[u], disc[v]);
            } else {
                dfs(v, edge_id);
                low[u] = min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    bridges.push_back({min(u, v), max(u, v)});
                }
            }
        }
    }

public:
    BridgeFinder(int n) : n(n), adj(n), disc(n, -1), low(n, -1), timer(0) {}

    void add_edge(int u, int v, int edge_id) {
        if (u < 0 || u >= n || v < 0 || v >= n) return;
        if (u == v) return;
        adj[u].push_back({v, edge_id});
        adj[v].push_back({u, edge_id});
    }

    vector<pair<int, int>> find_bridges() {
        bridges.clear();
        fill(disc.begin(), disc.end(), -1);
        fill(low.begin(), low.end(), -1);
        timer = 0;
        for (int i = 0; i < n; ++i) {
            if (disc[i] == -1) {
                dfs(i, -1);
            }
        }
        sort(bridges.begin(), bridges.end());
        return bridges;
    }
};

int main() {
    int n = 5;
    BridgeFinder bf(n);
    bf.add_edge(0, 1, 1);
    bf.add_edge(1, 2, 2);
    bf.add_edge(2, 0, 3);
    bf.add_edge(1, 3, 4);
    bf.add_edge(3, 4, 5);

    auto bridges = bf.find_bridges();
    cout << "Bridges found:\n";
    for (auto& b : bridges) {
        cout << "(" << b.first << ", " << b.second << ")\n";
    }
    return 0;
}

