Time Complexity:
- The algorithm performs a single depth-first search across the graph. Thus, the time complexity is O(V + E),
  where V is the number of vertices and E is the number of edges.

Space Complexity:
- O(V + E) for storing adjacency lists containing vertex targets and edge identifiers.
- O(V) auxiliary space for discovery time arrays, low-link arrays, and the DFS recursion stack.
*/

Here is a production-grade implementation of Dinic's Algorithm in C++.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

class Dinic {
public:
    struct Edge {
        int to;
        long long capacity;
        long long flow;
        int rev;
    };

private:
    int n;
    std::vector<std::vector<Edge>> adj;
    std::vector<int> level;
    std::vector<int> ptr;

    bool bfs(int s, int t) {
        std::fill(level.begin(), level.end(), -1);
        level[s] = 0;
        std::queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (auto& edge : adj[v]) {
                if (edge.capacity - edge.flow > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[v] + 1;
                    q.push(edge.to);
                }
            }
        }
        return level[t] != -1;
    }

    long long dfs(int v, int t, long long pushed) {
        if (pushed == 0) return 0;
        if (v == t) return pushed;
        for (int& cid = ptr[v]; cid < adj[v].size(); ++cid) {
            auto& edge = adj[v][cid];
            int tr = edge.to;
            if (level[v] + 1 != level[tr] || edge.capacity - edge.flow == 0) continue;
            long long tr_pushed = dfs(tr, t, std::min(pushed, edge.capacity - edge.flow));
            if (tr_pushed == 0) continue;
            edge.flow += tr_pushed;
            adj[tr][edge.rev].flow -= tr_pushed;
            return tr_pushed;
        }
        return 0;
    }

public:
    Dinic(int n) : n(n), adj(n), level(n), ptr(n) {}

    void add_edge(int from, int to, long long capacity) {
        if (from < 0 || from >= n || to < 0 || to >= n) return;
        adj[from].push_back({to, capacity, 0, (int)adj[to].size()});
        adj[to].push_back({from, 0, 0, (int)adj[from].size() - 1});
    }

    long long max_flow(int s, int t) {
        if (s < 0 || s >= n || t < 0 || t >= n || s == t) return 0;
        long long flow = 0;
        while (bfs(s, t)) {
            std::fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, t, 1e18)) {
                flow += pushed;
            }
        }
        return flow;
    }
};

int main() {
    Dinic dinic(4);
    dinic.add_edge(0, 1, 10);
    dinic.add_edge(0, 2, 5);
    dinic.add_edge(1, 2, 15);
    dinic.add_edge(1, 3, 5);
    dinic.add_edge(2, 3, 10);
    std::cout << "Max Flow: " << dinic.max_flow(0, 3) << std::endl;
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(V^2 E)$ in the general case, and $\mathcal{O}(V^2 \sqrt{E})$ for unit networks. Each BFS phase runs in $\mathcal{O}(E)$ time, and the DFS blocking flow traverses edges efficiently using current-arc pointers, guaranteeing a bound on phases.
- **Space Complexity**: $\mathcal{O}(V + E)$ to store the adjacency list, level arrays, and current-arc pointers.

