```cpp
#include <iostream>
#include <vector>
#include <algorithm>

class BridgeFinder {
private:
    int n;
    std::vector<std::vector<int>> adj;
    std::vector<int> tin;
    std::vector<int> low;
    std::vector<bool> visited;
    int timer;
    std::vector<std::pair<int, int>> bridges;

    void dfs(int v, int p = -1) {
        visited[v] = true;
        tin[v] = low[v] = timer++;
        for (int to : adj[v]) {
            if (to == p) continue;
            if (visited[to]) {
                low[v] = std::min(low[v], tin[to]);
            } else {
                dfs(to, v);
                low[v] = std::min(low[v], low[to]);
                if (low[to] > tin[v]) {
                    bridges.push_back({std::min(v, to), std::max(v, to)});
                }
            }
        }
    }

public:
    BridgeFinder(int nodes) : n(nodes), adj(nodes), tin(nodes, -1), low(nodes, -1), visited(nodes, false), timer(0) {}

    void add_edge(int u, int v) {
        if (u < 0 || u >= n || v < 0 || v >= n) return;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<std::pair<int, int>> find_bridges() {
        bridges.clear();
        timer = 0;
        std::fill(visited.begin(), visited.end(), false);
        std::fill(tin.begin(), tin.end(), -1);
        std::fill(low.begin(), low.end(), -1);

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                dfs(i);
            }
        }
        return bridges;
    }
};

