import ast
from enum import Enum, auto
from typing import List, Dict, Callable, Any

class TokenType(Enum):
    INTEGER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type_: TokenType, value: Any):
        self.type = type_
        self.value = value

class Precedence(Enum):
    LOWEST = 0
    SUM = 1
    PRODUCT = 2
    PREFIX = 3

PRECEDENCE_MAP = {
    TokenType.PLUS: Precedence.SUM,
    TokenType.MINUS: Precedence.SUM,
    TokenType.MULTIPLY: Precedence.PRODUCT,
    TokenType.DIVIDE: Precedence.PRODUCT,
}

class ASTNode:
    pass

class IntegerLiteral(ASTNode):
    def __init__(self, value: int):
        self.value = value
    def __repr__(self) -> str:
        return f"IntegerLiteral({self.value})"

class PrefixExpression(ASTNode):
    def __init__(self, operator: str, right: ASTNode):
        self.operator = operator
        self.right = right
    def __repr__(self) -> str:
        return f"PrefixExpression({self.operator}, {repr(self.right)})"

class InfixExpression(ASTNode):
    def __init__(self, left: ASTNode, operator: str, right: ASTNode):
        self.left = left
        self.operator = operator
        self.right = right
    def __repr__(self) -> str:
        return f"InfixExpression({repr(self.left)}, {self.operator}, {repr(self.right)})"

class PrattParser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.position = 0
        self.prefix_parse_fns: Dict[TokenType, Callable[[], ASTNode]] = {}
        self.infix_parse_fns: Dict[TokenType, Callable[[ASTNode], ASTNode]] = {}

        self.register_prefix(TokenType.INTEGER, self._parse_integer_literal)
        self.register_prefix(TokenType.MINUS, self._parse_prefix_expression)
        self.register_prefix(TokenType.LPAREN, self._parse_grouped_expression)

        self.register_infix(TokenType.PLUS, self._parse_infix_expression)
        self.register_infix(TokenType.MINUS, self._parse_infix_expression)
        self.register_infix(TokenType.MULTIPLY, self._parse_infix_expression)
        self.register_infix(TokenType.DIVIDE, self._parse_infix_expression)

    def _peek_token(self) -> Token:
        if self.position >= len(self.tokens):
            return Token(TokenType.EOF, "")
        return self.tokens[self.position]

    def _advance_token(self) -> Token:
        current = self._peek_token()
        self.position += 1
        return current

    def register_prefix(self, token_type: TokenType, fn: Callable[[], ASTNode]):
        self.prefix_parse_fns[token_type] = fn

    def register_infix(self, token_type: TokenType, fn: Callable[[ASTNode], ASTNode]):
        self.infix_parse_fns[token_type] = fn

    def _peek_precedence(self) -> Precedence:
        token = self._peek_token()
        return PRECEDENCE_MAP.get(token.type, Precedence.LOWEST)

    def parse_expression(self, precedence: Precedence) -> ASTNode:
        token = self._peek_token()
        prefix = self.prefix_parse_fns.get(token.type)
        if not prefix:
            raise SyntaxError(f"No prefix parse function for {token.type}")
        left_exp = prefix()

        while precedence.value < self._peek_precedence().value:
            infix_token = self._peek_token()
            infix = self.infix_parse_fns.get(infix_token.type)
            if not infix:
                return left_exp
            self._advance_token()
            left_exp = infix(left_exp)

        return left_exp

    def _parse_integer_literal(self) -> ASTNode:
        tok = self._advance_token()
        return IntegerLiteral(int(tok.value))

    def _parse_prefix_expression(self) -> ASTNode:
        tok = self._advance_token()
        return PrefixExpression(str(tok.value), self.parse_expression(Precedence.PREFIX))

    def _parse_grouped_expression(self) -> ASTNode:
        self._advance_token()
        exp = self.parse_expression(Precedence.LOWEST)
        if self._peek_token().type != TokenType.RPAREN:
            raise SyntaxError("Expected closing parenthesis")
        self._advance_token()
        return exp

    def _parse_infix_expression(self, left: ASTNode) -> ASTNode:
        tok = self.tokens[self.position - 1]
        precedence = PRECEDENCE_MAP[tok.type]
        right = self.parse_expression(precedence)
        op_str = "+" if tok.type == TokenType.PLUS else "-" if tok.type == TokenType.MINUS else "*" if tok.type == TokenType.MULTIPLY else "/"
        return InfixExpression(left, op_str, right)
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the number of tokens. Each token is visited and processed in bounded conditional checks.
- **Space Complexity**: $\mathcal{O}(D)$ where $D$ is the maximum nesting depth of expressions and operator stack frames.

Here is the complete recursive descent parser implementation with proper scoping and error detection:

```python
import ast
from enum import Enum, auto
from typing import List, Optional, Any

class TokenType(Enum):
    LET = auto()
    IDENT = auto()
    ASSIGN = auto()
    IF = auto()
    ELSE = auto()
    LBRACE = auto()
    RBRACE = auto()
    SEMICOLON = auto()
    INT = auto()
    EOF = auto()

class Token:
    def __init__(self, type_: TokenType, value: str):
        self.type = type_
        self.value = value

class AST:
    pass

class LetStatement(AST):
    def __init__(self, name: str, value: AST):
        self.name = name
        self.value = value

class AssignStatement(AST):
    def __init__(self, name: str, value: AST):
        self.name = name
        self.value = value

class IfStatement(AST):
    def __init__(self, condition: AST, consequence: List[AST], alternative: Optional[List[AST]] = None):
        self.condition = condition
        self.consequence = consequence
        self.alternative = alternative

class IntLiteral(AST):
    def __init__(self, value: int):
        self.value = value

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.position = 0

    def _peek(self) -> Token:
        if self.position >= len(self.tokens):
            return Token(TokenType.EOF, "")
        return self.tokens[self.position]

    def _advance(self) -> Token:
        tok = self._peek()
        self.position += 1
        return tok

    def _expect(self, t_type: TokenType) -> Token:
        tok = self._peek()
        if tok.type != t_type:
            raise SyntaxError(f"Expected token {t_type}, got {tok.type}")
        return self._advance()

    def parse_program(self) -> List[AST]:
        statements: List[AST] = []
        while self._peek().type != TokenType.EOF:
            stmt = self._parse_statement()
            if stmt:
                statements.append(stmt)
        return statements

    def _parse_statement(self) -> Optional[AST]:
        tok = self._peek()
        if tok.type == TokenType.LET:
            return self._parse_let_statement()
        elif tok.type == TokenType.IF:
            return self._parse_if_statement()
        elif tok.type == TokenType.IDENT:
            # Lookahead for assignment vs expression statement
            if self.position + 1 < len(self.tokens) and self.tokens[self.position + 1].type == TokenType.ASSIGN:
                return self._parse_assign_statement()
        return None

    def _parse_let_statement(self) -> LetStatement:
        self._advance()
        ident = self._expect(TokenType.IDENT)
        name = ident.value
        self._expect(TokenType.ASSIGN)
        val = self._parse_expression()
        if self._peek().type == TokenType.SEMICOLON:
            self._advance()
        return LetStatement(name, val)

    def _parse_assign_statement(self) -> AssignStatement:
        ident = self._advance()
        name = ident.value
        self._advance()
        val = self._parse_expression()
        if self._peek().type == TokenType.SEMICOLON:
            self._advance()
        return AssignStatement(name, val)

    def _parse_if_statement(self) -> IfStatement:
        self._advance()
        condition = self._parse_expression()
        self._expect(TokenType.LBRACE)
        consequence = self._parse_block_statement()
        alternative = None
        if self._peek().type == TokenType.ELSE:
            self._advance()
            self._expect(TokenType.LBRACE)
            alternative = self._parse_block_statement()
        return IfStatement(condition, consequence, alternative)

    def _parse_block_statement(self) -> List[AST]:
        statements: List[AST] = []
        while self._peek().type != TokenType.RBRACE and self._peek().type != TokenType.EOF:
            stmt = self._parse_statement()
            if stmt:
                statements.append(stmt)
            else:
                self._advance()
        self._expect(TokenType.RBRACE)
        return statements

    def _parse_expression(self) -> AST:
        tok = self._advance()
        if tok.type == TokenType.INT:
            return IntLiteral(int(tok.value))
        raise SyntaxError(f"Unexpected token in expression: {tok.type}")
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the total token count. Each recursive helper processes elements linearly with a bounded call tree.
- **Space Complexity**: $\mathcal{O}(M)$ where $M$ is the maximum block nesting depth.

Here is the complete C++ implementation of the stack-based virtual machine with robust error validation:

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>
#include <cstdint>

enum class Opcode : uint8_t {
    OP_CONSTANT,
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV,
    OP_LOAD,
    OP_STORE,
    OP_JUMP_IF_FALSE,
    OP_JUMP,
    OP_HALT
};

class VirtualMachine {
private:
    std::vector<uint8_t> code;
    std::vector<int32_t> stack;
    std::vector<int32_t> globals;
    size_t ip;

    void ensure_stack(size_t elements) {
        if (stack.size() < elements) {
            throw std::runtime_error("Stack underflow error detected.");
        }
    }

public:
    VirtualMachine(std::vector<uint8_t> bytecode, size_t global_count)
        : code(std::move(bytecode)), ip(0), globals(global_count, 0) {}

    void run() {
        while (ip < code.size()) {
            Opcode instruction = static_cast<Opcode>(code[ip++]);
            switch (instruction) {
                case Opcode::OP_CONSTANT: {
                    if (ip + 3 >= code.size()) {
                        throw std::runtime_error("Malformed bytecode: truncated constant.");
                    }
                    int32_t val = (code[ip] << 24) | (code[ip+1] << 16) | (code[ip+2] << 8) | code[ip+3];
                    ip += 4;
                    stack.push_back(val);
                    break;
                }
                case Opcode::OP_ADD: {
                    ensure_stack(2);
                    int32_t b = stack.back(); stack.pop_back();
                    int32_t a = stack.back(); stack.pop_back();
                    stack.push_back(a + b);
                    break;
                }
                case Opcode::OP_SUB: {
                    ensure_stack(2);
                    int32_t b = stack.back(); stack.pop_back();
                    int32_t a = stack.back(); stack.pop_back();
                    stack.push_back(a - b);
                    break;
                }
                case Opcode::OP_MUL: {
                    ensure_stack(2);
                    int32_t b = stack.back(); stack.pop_back();
                    int32_t a = stack.back(); stack.pop_back();
                    stack.push_back(a * b);
                    break;
                }
                case Opcode::OP_DIV: {
                    ensure_stack(2);
                    int32_t b = stack.back(); stack.pop_back();
                    int32_t a = stack.back(); stack.pop_back();
                    if (b == 0) {
                        throw std::runtime_error("Division by zero exception.");
                    }
                    stack.push_back(a / b);
                    break;
                }
                case Opcode::OP_LOAD: {
                    if (ip >= code.size()) throw std::runtime_error("Truncated LOAD operand.");
                    uint8_t idx = code[ip++];
                    if (idx >= globals.size()) throw std::runtime_error("Global index out of bounds.");
                    stack.push_back(globals[idx]);
                    break;
                }
                case Opcode::OP_STORE: {
                    if (ip >= code.size()) throw std::runtime_error("Truncated STORE operand.");
                    uint8_t idx = code[ip++];
                    ensure_stack(1);
                    int32_t val = stack.back();
                    if (idx >= globals.size()) throw std::runtime_error("Global index out of bounds.");
                    globals[idx] = val;
                    break;
                }
                case Opcode::OP_JUMP_IF_FALSE: {
                    if (ip + 1 >= code.size()) throw std::runtime_error("Truncated JUMP address.");
                    uint16_t target = (code[ip] << 8) | code[ip+1];
                    ip += 2;
                    ensure_stack(1);
                    int32_t condition = stack.back(); stack.pop_back();
                    if (condition == 0) {
                        ip = target;
                    }
                    break;
                }
                case Opcode::OP_JUMP: {
                    if (ip + 1 >= code.size()) throw std::runtime_error("Truncated JUMP address.");
                    uint16_t target = (code[ip] << 8) | code[ip+1];
                    ip = target;
                    break;
                }
                case Opcode::OP_HALT: {
                    return;
                }
                default:
                    throw std::runtime_error("Unknown opcode encountered.");
            }
        }
    }

    int32_t get_top_stack() {
        ensure_stack(1);
        return stack.back();
    }
};
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(I)$ where $I$ is the number of instructions executed. Each opcode is resolved in $\mathcal{O}(1)$ time via optimized branch dispatching.
- **Space Complexity**: $\mathcal{O}(V + S)$ where $V$ is the size of the global variables array and $S$ is the maximum active evaluation stack depth.

Here is the complete symbol resolver and semantic analyzer implementation with strict invariants:

```python
import ast
from typing import Dict, Set, List, Any

class SemanticError(Exception):
    pass

class SymbolTable:
    def __init__(self, parent: 'SymbolTable' = None):
        self.symbols: Set[str] = set()
        self.parent = parent

    def define(self, name: str):
        if name in self.symbols:
            raise SemanticError(f"Redeclaration of symbol: {name}")
        self.symbols.add(name)

    def resolve(self, name: str) -> bool:
        if name in self.symbols:
            return True
        if self.parent:
            return self.parent.resolve(name)
        return False

class SemanticAnalyzer:
    def __init__(self):
        self.current_scope = SymbolTable()

    def visit(self, node: Any) -> Any:
        method_name = f"visit_{type(node).__name__}"
        visitor = getattr(self, method_name, self.generic_visit)
        return visitor(node)

    def generic_visit(self, node: Any):
        raise SemanticError(f"No visit method defined for {type(node).__name__}")

    def visit_Program(self, node: Any):
        for stmt in node.statements:
            self.visit(stmt)

    def visit_LetStatement(self, node: Any):
        self.visit(node.value)
        try:
            self.current_scope.define(node.name)
        except SemanticError as e:
            raise SemanticError(f"Semantic analysis error: {e}")

    def visit_Identifier(self, node: Any):
        if not self.current_scope.resolve(node.name):
            raise SemanticError(f"Undeclared identifier: {node.name}")

    def visit_BinaryExpression(self, node: Any):
        self.visit(node.left)
        self.visit(node.right)

    def visit_IntLiteral(self, node: Any):
        pass

class MockProgram:
    def __init__(self, statements: List[Any]):
        self.statements = statements

class MockLet:
    def __init__(self, name: str, value: Any):
        self.name = name
        self.value = value

class MockIdentifier:
    def __init__(self, name: str):
        self.name = name

class MockBinaryExpr:
    def __init__(self, left: Any, right: Any):
        self.left = left
        self.right = right

class MockInt:
    def __init__(self, val: int):
        self.val = val
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the number of nodes in the Abstract Syntax Tree. Every node is visited exactly once.
- **Space Complexity**: $\mathcal{O}(S)$ where $S$ is the total number of nested scopes and defined variables.

```cpp
#include <iostream>
#include <string>
#include <string_view>
#include <vector>
#include <unordered_map>
#include <cctype>
#include <stdexcept>

enum class TokenType {
    END_OF_FILE,
    IDENTIFIER,
    KEYWORD_FN,
    KEYWORD_LET,
    KEYWORD_IF,
    KEYWORD_ELSE,
    INT_LITERAL,
    FLOAT_LITERAL,
    STRING_LITERAL,
    PLUS,
    MINUS,
    STAR,
    SLASH,
    ASSIGN,
    EQUAL,
    SEMICOLON,
    LPAREN,
    RPAREN,
    LBRACE,
    RBRACE,
    UNKNOWN
};

struct SourceLocation {
    size_t line;
    size_t column;
};

struct Token {
    TokenType type;
    std::string_view lexeme;
    SourceLocation location;
};

class Lexer {
public:
    explicit Lexer(std::string_view source) 
        : source_(source), cursor_(0), line_(1), column_(1) {}

    Token next_token() {
        skip_whitespace_and_comments();

        if (is_at_end()) {
            return Token{TokenType::END_OF_FILE, "", {line_, column_}};
        }

        SourceLocation start_loc = {line_, column_};
        char c = advance();

        if (std::isalpha(c) || c == '_') {
            return lex_identifier_or_keyword(start_loc);
        }
        if (std::isdigit(c)) {
            return lex_number(start_loc);
        }
        if (c == '"') {
            return lex_string(start_loc);
        }

        switch (c) {
            case '+': return Token{TokenType::PLUS, source_.substr(cursor_ - 1, 1), start_loc};
            case '-': return Token{TokenType::MINUS, source_.substr(cursor_ - 1, 1), start_loc};
            case '*': return Token{TokenType::STAR, source_.substr(cursor_ - 1, 1), start_loc};
            case '/': return Token{TokenType::SLASH, source_.substr(cursor_ - 1, 1), start_loc};
            case ';': return Token{TokenType::SEMICOLON, source_.substr(cursor_ - 1, 1), start_loc};
            case '(': return Token{TokenType::LPAREN, source_.substr(cursor_ - 1, 1), start_loc};
            case ')': return Token{TokenType::RPAREN, source_.substr(cursor_ - 1, 1), start_loc};
            case '{': return Token{TokenType::LBRACE, source_.substr(cursor_ - 1, 1), start_loc};
            case '}': return Token{TokenType::RBRACE, source_.substr(cursor_ - 1, 1), start_loc};
            case '=':
                if (match('=')) {
                    return Token{TokenType::EQUAL, source_.substr(cursor_ - 2, 2), start_loc};
                }
                return Token{TokenType::ASSIGN, source_.substr(cursor_ - 1, 1), start_loc};
            default:
                throw std::runtime_error("Unexpected character at line " + std::to_string(line_) + ", col " + std::to_string(column_));
        }
    }

private:
    std::string_view source_;
    size_t cursor_;
    size_t line_;
    size_t column_;

    bool is_at_end() const {
        return cursor_ >= source_.size();
    }

    char peek() const {
        if (is_at_end()) return '\0';
        return source_[cursor_];
    }

    char peek_next() const {
        if (cursor_ + 1 >= source_.size()) return '\0';
        return source_[cursor_ + 1];
    }

    char advance() {
        char c = source_[cursor_++];
        if (c == '\n') {
            line_++;
            column_ = 1;
        } else {
            column_++;
        }
        return c;
    }

    bool match(char expected) {
        if (is_at_end()) return false;
        if (source_[cursor_] != expected) return false;
        advance();
        return true;
    }

    void skip_whitespace_and_comments() {
        while (!is_at_end()) {
            char c = peek();
            if (c == ' ' || c == '\r' || c == '\t' || c == '\n') {
                advance();
            } else if (c == '/' && peek_next() == '/') {
                // Line comment
                while (!is_at_end() && peek() != '\n') {
                    advance();
                }
            } else {
                break;
            }
        }
    }

    Token lex_identifier_or_keyword(SourceLocation start_loc) {
        size_t start = cursor_ - 1;
        while (!is_at_end() && (std::isalnum(peek()) || peek() == '_')) {
            advance();
        }
        size_t length = cursor_ - start;
        std::string_view lexeme = source_.substr(start, length);

        TokenType type = TokenType::IDENTIFIER;
        if (lexeme == "fn") type = TokenType::KEYWORD_FN;
        else if (lexeme == "let") type = TokenType::KEYWORD_LET;
        else if (lexeme == "if") type = TokenType::KEYWORD_IF;
        else if (lexeme == "else") type = TokenType::KEYWORD_ELSE;

        return Token{type, lexeme, start_loc};
    }

    Token lex_number(SourceLocation start_loc) {
        size_t start = cursor_ - 1;
        bool is_float = false;

        while (!is_at_end() && std::isdigit(peek())) {
            advance();
        }

        if (peek() == '.' && std::isdigit(peek_next())) {
            is_float = true;
            advance(); // consume '.'
            while (!is_at_end() && std::isdigit(peek())) {
                advance();
            }
        }

        size_t length = cursor_ - start;
        return Token{is_float ? TokenType::FLOAT_LITERAL : TokenType::INT_LITERAL, source_.substr(start, length), start_loc};
    }

    Token lex_string(SourceLocation start_loc) {
        size_t start = cursor_ - 1;
        while (!is_at_end() && peek() != '"') {
            if (peek() == '\n') {
                throw std::runtime_error("Unterminated string literal at line " + std::to_string(line_));
            }
            if (peek() == '\\') {
                advance(); // consume escape character
            }
            advance();
        }

        if (is_at_end()) {
            throw std::runtime_error("Unterminated string literal at end of file");
        }

        advance(); // consume closing quote
        size_t length = cursor_ - start;
        return Token{TokenType::STRING_LITERAL, source_.substr(start, length), start_loc};
    }
};

int main() {
    std::string_view code = "let x = 42.5; // comment\nfn test() { if x == 42.5 { "hello" } }";
    Lexer lexer(code);
    try {
        while (true) {
            Token token = lexer.next_token();
            if (token.type == TokenType::END_OF_FILE) break;
            std::cout << "Token Type: " << static_cast<int>(token.type) 
                      << " | Lexeme: \"" << token.lexeme << "\"" 
                      << " | Line: " << token.location.line 
                      << " | Col: " << token.location.column << "\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Lexer Error: " << e.what() << "\n";
    }
    return 0;
}
```
### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of characters in the source string. Each character is examined at most a constant number of times.
- **Space Complexity:** $\mathcal{O}(1)$ auxiliary space. Tokens use `std::string_view` referencing the original contiguous memory buffer without allocations.

```python
from enum import Enum, auto
from typing import List, Optional

class TokenType(Enum):
    INT = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type_: TokenType, value: str):
        self.type = type_
        self.value = value

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def integer(self) -> str:
        result = ""
        while self.current_char is not None and self.current_char.isdigit():
            result += self.current_char
            self.advance()
        return result

    def get_next_token(self) -> Token:
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit():
                return Token(TokenType.INT, self.integer())
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, "+")
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, "-")
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY, "*")
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE, "/")
            if self.current_char == '^':
                self.advance()
                return Token(TokenType.POWER, "^")
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, "(")
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ")")
            raise SyntaxError(f"Invalid character: {self.current_char}")
        return Token(TokenType.EOF, "")

class ASTNode:
    pass

class NumNode(ASTNode):
    def __init__(self, token: Token):
        self.token = token
        self.value = int(token.value)

    def __repr__(self):
        return f"Num({self.value})"

class BinOpNode(ASTNode):
    def __init__(self, left: ASTNode, op: Token, right: ASTNode):
        self.left = left
        self.token = op
        self.op = op
        self.right = right

    def __repr__(self):
        return f"BinOp({self.left}, {self.op.value}, {self.right})"

class UnaryOpNode(ASTNode):
    def __init__(self, op: Token, expr: ASTNode):
        self.token = op
        self.op = op
        self.expr = expr

    def __repr__(self):
        return f"UnaryOp({self.op.value}, {self.expr})"

class Precedence(Enum):
    LOWEST = 0
    SUM = 1
    PRODUCT = 2
    PREFIX = 3
    POWER = 4

PRECEDENCE_MAP = {
    TokenType.PLUS: Precedence.SUM,
    TokenType.MINUS: Precedence.SUM,
    TokenType.MULTIPLY: Precedence.PRODUCT,
    TokenType.DIVIDE: Precedence.PRODUCT,
    TokenType.POWER: Precedence.POWER
}

class PrattParser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()
        self.peek_token = self.lexer.get_next_token()

    def consume(self):
        self.current_token = self.peek_token
        self.peek_token = self.lexer.get_next_token()

    def get_precedence(self, token_type: TokenType) -> Precedence:
        return PRECEDENCE_MAP.get(token_type, Precedence.LOWEST)

    def parse_expression(self, precedence: Precedence = Precedence.LOWEST) -> ASTNode:
        token = self.current_token
        self.consume()

        left = self.parse_prefix(token)

        while precedence.value < self.get_precedence(self.current_token.type).value:
            infix_token = self.current_token
            self.consume()
            left = self.parse_infix(infix_token, left)

        return left

    def parse_prefix(self, token: Token) -> ASTNode:
        if token.type == TokenType.INT:
            return NumNode(token)
        if token.type in (TokenType.PLUS, TokenType.MINUS):
            expr = self.parse_expression(Precedence.PREFIX)
            return UnaryOpNode(token, expr)
        if token.type == TokenType.LPAREN:
            expr = self.parse_expression(Precedence.LOWEST)
            if self.current_token.type != TokenType.RPAREN:
                raise SyntaxError("Expected closing parenthesis")
            self.consume()
            return expr
        raise SyntaxError(f"Unexpected token in prefix position: {token.type}")

    def parse_infix(self, token: Token, left: ASTNode) -> ASTNode:
        prec = self.get_precedence(token.type)
        # Right-associative power operator handling
        if token.type == TokenType.POWER:
            right = self.parse_expression(Precedence(prec.value - 1))
        else:
            right = self.parse_expression(prec)
        return BinOpNode(left, token, right)

if __name__ == '__main__':
    parser = PrattParser(Lexer("2 ^ 3 ^ 2 + 5 * -3"))
    ast = parser.parse_expression()
    print(ast)
```
### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of tokens in the expression. Each token is visited and processed a constant number of times.
- **Space Complexity:** $\mathcal{O}(D)$ where $D$ is the maximum depth of operator precedence nesting, corresponding to call stack overhead during recursive parsing steps.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <stdexcept>

enum class NodeType {
    PROGRAM,
    VAR_DECL,
    ASSIGNMENT,
    IF_STMT,
    BINARY_OP,
    IDENTIFIER,
    NUMBER
};

struct ASTNode {
    NodeType type;
    virtual ~ASTNode() = default;
};

struct ProgramNode : public ASTNode {
    std::vector<std::unique_ptr<ASTNode>> statements;
    ProgramNode() { type = NodeType::PROGRAM; }
};

struct VarDeclNode : public ASTNode {
    std::string name;
    std::unique_ptr<ASTNode> initializer;
    VarDeclNode(std::string n, std::unique_ptr<ASTNode> init) 
        : name(std::move(n)), initializer(std::move(init)) { type = NodeType::VAR_DECL; }
};

struct BinaryOpNode : public ASTNode {
    std::string op;
    std::unique_ptr<ASTNode> left;
    std::unique_ptr<ASTNode> right;
    BinaryOpNode(std::string o, std::unique_ptr<ASTNode> l, std::unique_ptr<ASTNode> r)
        : op(std::move(o)), left(std::move(l)), right(std::move(r)) { type = NodeType::BINARY_OP; }
};

struct NumberNode : public ASTNode {
    int value;
    explicit NumberNode(int v) : value(v) { type = NodeType::NUMBER; }
};

struct IdentifierNode : public ASTNode {
    std::string name;
    explicit IdentifierNode(std::string n) : name(std::move(n)) { type = NodeType::IDENTIFIER; }
};

class Parser {
public:
    explicit Parser(std::vector<std::string> tokens) 
        : tokens_(std::move(tokens)), cursor_(0) {}

    std::unique_ptr<ProgramNode> parse() {
        auto program = std::make_unique<ProgramNode>();
        while (!is_at_end()) {
            program->statements.push_back(parse_statement());
        }
        return program;
    }

private:
    std::vector<std::string> tokens_;
    size_t cursor_;

    bool is_at_end() const {
        return cursor_ >= tokens_.size() || tokens_[cursor_] == "EOF";
    }

    const std::string& peek() const {
        if (is_at_end()) return tokens_.back();
        return tokens_[cursor_];
    }

    std::string advance() {
        if (is_at_end()) return "EOF";
        return tokens_[cursor_++];
    }

    void expect(const std::string& expected) {
        if (advance() != expected) {
            throw std::runtime_error("Parser Error: Expected '" + expected + "' at token index " + std::to_string(cursor_));
        }
    }

    std::unique_ptr<ASTNode> parse_statement() {
        if (peek() == "let") {
            advance();
            std::string name = advance();
            expect("=");
            auto init = parse_expression();
            expect(";");
            return std::make_unique<VarDeclNode>(name, std::move(init));
        }
        throw std::runtime_error("Unknown statement starting with token: " + peek());
    }

    std::unique_ptr<ASTNode> parse_expression() {
        auto node = parse_term();
        while (peek() == "+" || peek() == "-") {
            std::string op = advance();
            auto right = parse_term();
            node = std::make_unique<BinaryOpNode>(op, std::move(node), std::move(right));
        }
        return node;
    }

    std::unique_ptr<ASTNode> parse_term() {
        std::string token = advance();
        if (token.empty()) {
            throw std::runtime_error("Unexpected end of input during term parsing");
        }

        // Check if integer literal
        bool is_num = true;
        for (char c : token) {
            if (!std::isdigit(c)) is_num = false;
        }

        if (is_num) {
            return std::make_unique<NumberNode>(std::stoi(token));
        } else {
            return std::make_unique<IdentifierNode>(token);
        }
    }
};

int main() {
    std::vector<std::string> tokens = {"let", "x", "=", "10", "+", "20", ";", "EOF"};
    try {
        Parser parser(tokens);
        auto ast = parser.parse();
        std::cout << "Parsing successful! Total statements: " << ast->statements.size() << "\n";
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n";
    }
    return 0;
}
```
### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the token sequence length. Each token is scanned once.
- **Space Complexity:** $\mathcal{O}(H)$ where $H$ is the AST height representing maximum recursive production rule depth.

```python
from enum import Enum, auto
from typing import List, Dict, Any

class OpCode(Enum):
    PUSH = auto()
    POP = auto()
    ADD = auto()
    SUB = auto()
    MUL = auto()
    DIV = auto()
    LOAD_GLOBAL = auto()
    STORE_GLOBAL = auto()
    JUMP = auto()
    JUMP_IF_FALSE = auto()
    PRINT = auto()
    HALT = auto()

class Instruction:
    def __init__(self, opcode: OpCode, operand: Any = None):
        self.opcode = opcode
        self.operand = operand

class VirtualMachine:
    def __init__(self, code: List[Instruction], stack_limit: int = 1024):
        self.code = code
        self.ip = 0
        self.stack: List[Any] = []
        self.globals: Dict[str, Any] = {}
        self.stack_limit = stack_limit

    def run(self):
        while self.ip < len(self.code):
            instr = self.code[self.ip]
            self.ip += 1

            if instr.opcode == OpCode.PUSH:
                if len(self.stack) >= self.stack_limit:
                    raise RuntimeError("Stack overflow exception")
                self.stack.append(instr.operand)

            elif instr.opcode == OpCode.POP:
                if not self.stack:
                    raise RuntimeError("Stack underflow exception")
                self.stack.pop()

            elif instr.opcode == OpCode.ADD:
                self._binary_op(lambda a, b: a + b)

            elif instr.opcode == OpCode.SUB:
                self._binary_op(lambda a, b: a - b)

            elif instr.opcode == OpCode.MUL:
                self._binary_op(lambda a, b: a * b)

            elif instr.opcode == OpCode.DIV:
                self._binary_op(lambda a, b: a / b)

            elif instr.opcode == OpCode.LOAD_GLOBAL:
                name = instr.operand
                if name not in self.globals:
                    raise NameError(f"Global variable '{name}' is not defined")
                self.stack.append(self.globals[name])

            elif instr.opcode == OpCode.STORE_GLOBAL:
                name = instr.operand
                if not self.stack:
                    raise RuntimeError(
                        "Stack underflow during STORE_GLOBAL"
                    )
                self.globals[name] = self.stack.pop()

            elif instr.opcode == OpCode.JUMP:
                self.ip = instr.operand

            elif instr.opcode == OpCode.JUMP_IF_FALSE:
                if not self.stack:
                    raise RuntimeError(
                        "Stack underflow during JUMP_IF_FALSE"
                    )
                condition = self.stack.pop()
                if not condition:
                    self.ip = instr.operand

            elif instr.opcode == OpCode.PRINT:
                if not self.stack:
                    raise RuntimeError("Stack underflow during PRINT")
                print(self.stack.pop())

            elif instr.opcode == OpCode.HALT:
                break
            else:
                raise TypeError(f"Unknown opcode: {instr.opcode}")

    def _binary_op(self, op_func):
        if len(self.stack) < 2:
            raise RuntimeError("Insufficient operands on stack for binary operation")
        b = self.stack.pop()
        a = self.stack.pop()
        self.stack.append(op_func(a, b))

if __name__ == '__main__':
    # Bytecode program computing: x = 10 + 5 * 2; print(x);
    bytecode = [
        Instruction(OpCode.PUSH, 10),
        Instruction(OpCode.PUSH, 5),
        Instruction(OpCode.PUSH, 2),
        Instruction(OpCode.MUL),
        Instruction(OpCode.ADD),
        Instruction(OpCode.STORE_GLOBAL, "x"),
        Instruction(OpCode.LOAD_GLOBAL, "x"),
        Instruction(OpCode.PRINT),
        Instruction(OpCode.HALT)
    ]
    vm = VirtualMachine(bytecode)
    vm.run()
```
### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(M)$ where $M$ is the number of executed instructions. Each bytecode instruction performs $\mathcal{O}(1)$ stack or store operations.
- **Space Complexity:** $\mathcal{O}(S + G)$ where $S$ is the maximum operand stack depth and $G$ is the number of defined global variables.

```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <stdexcept>

enum class OpCode {
    PUSH,
    ADD,
    SUB,
    MUL,
    PRINT,
    HALT
};

struct Instruction {
    OpCode opcode;
    int operand;
};

struct ASTNode {
    virtual ~ASTNode() = default;
    virtual void compile(std::vector<Instruction>& code) const = 0;
};

struct NumberNode : public ASTNode {
    int value;
    explicit NumberNode(int v) : value(v) {}
    void compile(std::vector<Instruction>& code) const override {
        code.push_back(Instruction{OpCode::PUSH, value});
    }
};

struct BinaryNode : public ASTNode {
    std::string op;
    std::unique_ptr<ASTNode> left;
    std::unique_ptr<ASTNode> right;

    BinaryNode(std::string o, std::unique_ptr<ASTNode> l, std::unique_ptr<ASTNode> r)
        : op(std::move(o)), left(std::move(l)), right(std::move(r)) {}

    void compile(std::vector<Instruction>& code) const override {
        left->compile(code);
        right->compile(code);
        if (op == "+") {
            code.push_back(Instruction{OpCode::ADD, 0});
        } else if (op == "-") {
            code.push_back(Instruction{OpCode::SUB, 0});
        } else if (op == "*") {
            code.push_back(Instruction{OpCode::MUL, 0});
        } else {
            throw std::runtime_error("Unsupported binary operator: " + op);
        }
    }
};

class VirtualMachine {
public:
    explicit VirtualMachine(const std::vector<Instruction>& code) : code_(code), ip_(0) {}

    void run() {
        while (ip_ < code_.size()) {
            const Instruction& instr = code_[ip_++];
            switch (instr.opcode) {
                case OpCode::PUSH:
                    stack_.push_back(instr.operand);
                    break;
                case OpCode::ADD:
                    {
                        int b = pop();
                        int a = pop();
                        stack_.push_back(a + b);
                    }
                    break;
                case OpCode::SUB:
                    {
                        int b = pop();
                        int a = pop();
                        stack_.push_back(a - b);
                    }
                    break;
                case OpCode::MUL:
                    {
                        int b = pop();
                        int a = pop();
                        stack_.push_back(a * b);
                    }
                    break;
                case OpCode::PRINT:
                    std::cout << "Output: " << pop() << "\n";
                    break;
                case OpCode::HALT:
                    return;
            }
        }
    }

private:
    std::vector<Instruction> code_;
    size_t ip_;
    std::vector<int> stack_;

    int pop() {
        if (stack_.empty()) {
            throw std::runtime_error("VM Stack underflow");
        }
        int val = stack_.back();
        stack_.pop_back();
        return val;
    }
};

int main() {
    // AST for: (5 + 3) * 2
    auto ast = std::make_unique<BinaryNode>(
        "*",
        std::make_unique<BinaryNode>(
            "+",
            std::make_unique<NumberNode>(5),
            std::make_unique<NumberNode>(3)
        ),
        std::make_unique<NumberNode>(2)
    );

    std::vector<Instruction> bytecode;
    ast->compile(bytecode);
    bytecode.push_back(Instruction{OpCode::PRINT, 0});
    bytecode.push_back(Instruction{OpCode::HALT, 0});

    VirtualMachine vm(bytecode);
    vm.run();
    return 0;
}
```
### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ for compilation phase where $N$ is the number of AST nodes, and $\mathcal{O}(K)$ for execution phase where $K$ is the number of generated bytecode instructions.
- **Space Complexity:** $\mathcal{O}(K)$ for storing the generated bytecode array and maximum evaluation stack depth during VM execution.

Here is the complete Pratt parser implementation in modern C++.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <cctype>
#include <stdexcept>

enum class TokenType {
    INT,
    PLUS,
    MINUS,
    STAR,
    SLASH,
    LPAREN,
    RPAREN,
    END
};

struct Token {
    TokenType type;
    int value;
    std::string text;
};

class Lexer {
    std::string src;
    size_t pos;
public:
    explicit Lexer(std::string s) : src(std::move(s)), pos(0) {}

    Token next_token() {
        while (pos < src.size() && std::isspace(static_cast<unsigned char>(src[pos]))) {
            pos++;
        }
        if (pos >= src.size()) {
            return {TokenType::END, 0, ""};
        }

        char c = src[pos];
        if (std::isdigit(static_cast<unsigned char>(c))) {
            int val = 0;
            while (pos < src.size() && std::isdigit(static_cast<unsigned char>(src[pos]))) {
                val = val * 10 + (src[pos] - '0');
                pos++;
            }
            return {TokenType::INT, val, std::to_string(val)};
        }

        pos++;
        switch (c) {
            case '+': return {TokenType::PLUS, 0, "+"};
            case '-': return {TokenType::MINUS, 0, "-"};
            case '*': return {TokenType::STAR, 0, "*"};
            case '/': return {TokenType::SLASH, 0, "/"};
            case '(': return {TokenType::LPAREN, 0, "("};
            case ')': return {TokenType::RPAREN, 0, ")"};
            default:
                throw std::runtime_error(std::string("Unexpected character: ") + c);
        }
    }
};

enum class Precedence {
    LOWEST = 0,
    SUM,
    PRODUCT,
    PREFIX
};

struct ASTNode {
    virtual ~ASTNode() = default;
    virtual int evaluate() const = 0;
};

struct IntNode : public ASTNode {
    int val;
    explicit IntNode(int v) : val(v) {}
    int evaluate() const override { return val; }
};

struct PrefixNode : public ASTNode {
    TokenType op;
    std::unique_ptr<ASTNode> right;
    PrefixNode(TokenType o, std::unique_ptr<ASTNode> r) : op(o), right(std::move(r)) {}
    int evaluate() const override {
        int r_val = right->evaluate();
        if (op == TokenType::MINUS) return -r_val;
        return r_val;
    }
};

struct InfixNode : public ASTNode {
    std::unique_ptr<ASTNode> left;
    TokenType op;
    std::unique_ptr<ASTNode> right;
    InfixNode(std::unique_ptr<ASTNode> l, TokenType o, std::unique_ptr<ASTNode> r)
        : left(std::move(l)), op(o), right(std::move(r)) {}
    int evaluate() const override {
        int l_val = left->evaluate();
        int r_val = right->evaluate();
        switch (op) {
            case TokenType::PLUS: return l_val + r_val;
            case TokenType::MINUS: return l_val - r_val;
            case TokenType::STAR: return l_val * r_val;
            case TokenType::SLASH:
                if (r_val == 0) throw std::runtime_error("Division by zero");
                return l_val / r_val;
            default: throw std::runtime_error("Unknown infix operator");
        }
    }
};

class Parser {
    Lexer lexer;
    Token curr;
    Token peek;

    void advance() {
        curr = peek;
        peek = lexer.next_token();
    }

    Precedence get_peek_precedence() const {
        switch (peek.type) {
            case TokenType::PLUS:
            case TokenType::MINUS: return Precedence::SUM;
            case TokenType::STAR:
            case TokenType::SLASH: return Precedence::PRODUCT;
            default: return Precedence::LOWEST;
        }
    }

    Precedence get_curr_precedence() const {
        switch (curr.type) {
            case TokenType::PLUS:
            case TokenType::MINUS: return Precedence::SUM;
            case TokenType::STAR:
            case TokenType::SLASH: return Precedence::PRODUCT;
            default: return Precedence::LOWEST;
        }
    }

    std::unique_ptr<ASTNode> parse_expression(Precedence precedence) {
        std::unique_ptr<ASTNode> left;

        if (curr.type == TokenType::INT) {
            left = std::make_unique<IntNode>(curr.value);
            advance();
        } else if (curr.type == TokenType::MINus || curr.type == TokenType::PLUS) {
            TokenType op = curr.type;
            advance();
            auto right = parse_expression(Precedence::PREFIX);
            left = std::make_unique<PrefixNode>(op, std::move(right));
        } else if (curr.type == TokenType::LPAREN) {
            advance();
            left = parse_expression(Precedence::LOWEST);
            if (curr.type != TokenType::RPAREN) {
                throw std::runtime_error("Missing closing parenthesis");
            }
            advance();
        } else {
            throw std::runtime_error("Unexpected token in expression");
        }

        while (precedence < get_curr_precedence()) {
            TokenType op = curr.type;
            Precedence prec = get_curr_precedence();
            advance();
            auto right = parse_expression(prec);
            left = std::make_unique<InfixNode>(std::move(left), op, std::move(right));
        }

        return left;
    }

public:;
    explicit Parser(std::string s) : lexer(std::move(s)) {
        curr = lexer.next_token();
        peek = lexer.next_token();
    }

    std::unique_ptr<ASTNode> parse() {
        return parse_expression(Precedence::LOWEST);
    }
};

int main() {
    try {
        Parser parser("- (2 + 3) * 4 - 5");
        auto ast = parser.parse();
        std::cout << "Result: " << ast->evaluate() << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of tokens in the input string. Each token is visited a constant number of times by the lexer and parser.
- **Space Complexity:** $\mathcal{O}(D)$ where $D$ is the maximum depth of the AST (recursion stack depth). In the worst case of nested parentheses or chains, this is $\mathcal{O}(N)$.

Here is a robust lexical analyzer in Python handling advanced tokenization.

```python
import ast

class Token:
    def __init__(self, type_, value, line, col):
        self.type = type_
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)}, line={self.line}, col={self.col})"

class Lexer:
    def __init__(self, source_code):
        self.src = source_code
        self.pos = 0
        self.line = 1
        self.col = 1
        self.length = len(source_code)

    def _error(self, message):
        raise SyntaxError(f"{message} at line {self.line}, col {self.col}")

    def _advance(self):
        if self.pos < self.length:
            if self.src[self.pos] == '\n':
                self.line += 1
                self.col = 1
            else:
                self.col += 1
            self.pos += 1

    def _peek(self):
        if self.pos + 1 < self.length:
            return self.src[self.pos + 1]
        return '\0'

    def tokenize(self):
        tokens = []
        while self.pos < self.length:
            c = self.src[self.pos]

            if c == '\n' or c == ' ' or c == '\t' or c == '\r':
                self._advance()
                continue

            # Comments
            if c == '/' and self._peek() == '/':
                while self.pos < self.length and self.src[self.pos] != '\n':
                    self._advance()
                continue

            # Identifiers and Keywords
            if c.isalpha() or c == '_':
                start_col = self.col
                start_line = self.line
                start_pos = self.pos
                while self.pos < self.length and (self.src[self.pos].isalnum() or self.src[self.pos] == '_'):
                    self._advance()
                val = self.src[start_pos:self.pos]
                t_type = "KEYWORD" if val in {"if", "else", "while", "return", "fn"} else "IDENTIFIER"
                tokens.append(Token(t_type, val, start_line, start_col))
                continue

            # Numeric Literals
            if c.isdigit():
                start_col = self.col
                start_line = self.line
                start_pos = self.pos
                is_float = False
                while self.pos < self.length and (self.src[self.pos].isdigit() or self.src[self.pos] == '.'):
                    if self.src[self.pos] == '.':
                        if is_float:
                            self._error("Invalid floating point literal")
                        is_float = True
                    self._advance()
                val_str = self.src[start_pos:self.pos]
                val = float(val_str) if is_float else int(val_str)
                tokens.append(Token("FLOAT" if is_float else "INT", val, start_line, start_col))
                continue

            # String Literals
            if c == '"':
                start_col = self.col
                start_line = self.line
                self._advance()
                val_chars = []
                while self.pos < self.length and self.src[self.pos] != '"':
                    if self.src[self.pos] == '\\':
                        self._advance()
                        if self.pos >= self.length:
                            self._error("Unterminated string escape sequence")
                        escape_char = self.src[self.pos]
                        escapes = {'n': '\n', 't': '\t', 'r': '\r', '"': '"', '\\': '\\'}
                        if escape_char in escapes:
                            val_chars.append(escapes[escape_char])
                        else:
                            self._error(f"Invalid escape sequence \\{escape_char}")
                    else:
                        val_chars.append(self.src[self.pos])
                    self._advance()
                if self.pos >= self.length:
                    self._error("Unterminated string literal")
                self._advance() # consume closing quote
                tokens.append(Token("STRING", "".join(val_chars), start_line, start_col))
                continue

            # Operators and Delimiters
            start_col = self.col
            start_line = self.line
            if c in "+-*/=(){},;":
                tokens.append(Token("PUNCTUATION", c, start_line, start_col))
                self._advance()
                continue

            self._error(f"Unexpected character '{c}'")

        tokens.append(Token("EOF", "", self.line, self.col))
        return tokens

if __name__ == '__main__':
    code = 'fn compute() { \n    // Compute value\n    let x = "Hello\\nWorld";\n    return x;\n}'
    lexer = Lexer(code)
    for tok in lexer.tokenize():
        print(tok)
```

