- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of characters in the input source code string. Each character is scanned a constant number of times.
- **Space Complexity:** $\mathcal{O}(T)$ where $T$ is the total number of tokens generated, stored within the resulting token collection list.

Here is a complete recursive descent parser emitting Three-Address Code in C++.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <stdexcept>

struct Instruction {
    std::string op;
    std::string arg1;
    std::string arg2;
    std::string result;
};

class TACGenerator {
    std::vector<Instruction> instructions;
    int temp_counter = 0;
    int label_counter = 0;

public:
    std::string new_temp() {
        return "t" + std::to_string(temp_counter++);
    }

    std::string new_label() {
        return "L" + std::to_string(label_counter++);
    }

    void emit(const std::string& op, const std::string& arg1, const std::string& arg2, const std::string& result) {
        instructions.push_back({op, arg1, arg2, result});
    }

    void print() const {
        for (const auto& instr : instructions) {
            if (instr.op == "ASSIGN") {
                std::cout << instr.result << " = " << instr.arg1 << "\n";
            } else if (instr.op == "LABEL") {
                std::cout << instr.result << ":\n";
            } else if (instr.op == "GOTO") {
                std::cout << "GOTO " << instr.result << "\n";
            } else if (instr.op == "GOTOFALSE") {
                std::cout << "IF_FALSE " << instr.arg1 << " GOTO " << instr.result << "\n";
            } else {
                std::cout << instr.result << " = " << instr.arg1 << " " << instr.op << " " << instr.arg2 << "\n";
            }
        }
    }
};

class Parser {
    std::string src;
    size_t pos;
    TACGenerator& tac;

    void advance() {
        if (pos < src.size()) pos++;
    }

    char peek() const {
        if (pos < src.size()) return src[pos];
        return '\0';
    }

    void skip_whitespace() {
        while (pos < src.size() && std::isspace(static_cast<unsigned char>(src[pos]))) {
            pos++;
        }
    }

    std::string parse_factor() {
        skip_whitespace();
        if (std::isdigit(static_cast<unsigned char>(peek()))) {
            std::string val;
            while (pos < src.size() && std::isdigit(static_cast<unsigned char>(src[pos]))) {
                val += src[pos];
                pos++;
            }
            return val;
        } else if (std::isalpha(static_cast<unsigned char>(peek()))) {
            std::string name;
            while (pos < src.size() && std::isalnum(static_cast<unsigned char>(src[pos]))) {
                name += src[pos];
                pos++;
            }
            return name;
        } else if (peek() == '(') {
            advance();
            std::string result = parse_expr();
            skip_whitespace();
            if (peek() != ')') throw std::runtime_error("Expected closing parenthesis");
            advance();
            return result;
        }
        throw std::runtime_error("Invalid factor in expression");
    }

    std::string parse_term() {
        std::string left = parse_factor();
        skip_whitespace();
        while (peek() == '*' || peek() == '/') {
            char op = peek();
            advance();
            std::string right = parse_factor();
            std::string temp = tac.new_temp();
            tac.emit(std::string(1, op), left, right, temp);
            left = temp;
            skip_whitespace();
        }
        return left;
    }

    std::string parse_expr() {
        std::string left = parse_term();
        skip_whitespace();
        while (peek() == '+' || peek() == '-') {
            char op = peek();
            advance();
            std::string right = parse_term();
            std::string temp = tac.new_temp();
            tac.emit(std::string(1, op), left, right, temp);
            left = temp;
            skip_whitespace();
        }
        return left;
    }

public:
    Parser(std::string s, TACGenerator& t) : src(std::move(s)), pos(0), tac(t) {}

    void parse_assignment() {
        skip_whitespace();
        std::string var_name;
        while (pos < src.size() && std::isalnum(static_cast<unsigned char>(src[pos]))) {
            var_name += src[pos];
            pos++;
        }
        skip_whitespace();
        if (peek() != '=') throw std::runtime_error("Expected assignment operator");
        advance();
        std::string expr_res = parse_expr();
        tac.emit("ASSIGN", expr_res, "", var_name);
    }
};

int main() {
    TACGenerator tac;
    Parser parser("result = a + b * 3 - (c / 2)", tac);
    try {
        parser.parse_assignment();
        tac.print();
    } catch (const std::exception& e) {
        std::cerr << "Parsing Error: " << e.what() << std::endl;
    }
    return 0;
}
