- **Space Complexity:** $\mathcal{O}(N)$ for storing temporary variables, intermediate representations, and the generated TAC instruction vector.

Here is the complete implementation of the Lexer, Pratt Parser, AST, and Evaluator in Python.

```python
from enum import Enum, auto
import ast
import math

class TokenType(Enum):
    INTEGER = auto()
    IDENTIFIER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type: TokenType, value: any, pos: int):
        self.type = type
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type.name}, {repr(self.value)}, pos={self.pos})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self, msg: str):
        raise SyntaxError(f"Lexer error at position {self.pos}: {msg}")

    def advance(self):
        self.pos += 1
        if self.pos >= len(self.text):
            self.current_char = None
        else:
            self.current_char = self.text[self.pos]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def integer(self) -> Token:
        result = ""
        pos = self.pos
        while self.current_char is not None and self.current_char.isdigit():
            result += self.current_char
            self.advance()
        return Token(TokenType.INTEGER, int(result), pos)

    def identifier(self) -> Token:
        result = ""
        pos = self.pos
        while self.current_char is not None and (self.current_char.isalnum() or self.current_char == '_'):
            result += self.current_char
            self.advance()
        return Token(TokenType.IDENTIFIER, result, pos)

    def get_next_token(self) -> Token:
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit():
                return self.integer()

            if self.current_char.isalpha() or self.current_char == '_':
                return self.identifier()

            pos = self.pos
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, '+', pos)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, '-', pos)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY, '*', pos)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE, '/', pos)
            if self.current_char == '^':
                self.advance()
                return Token(TokenType.POWER, '^', pos)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, '(', pos)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ')', pos)

            self.error(f"Unexpected character '{self.current_char}'")

        return Token(TokenType.EOF, None, self.pos)

class ASTNode:
    pass

class NumNode(ASTNode):
    def __init__(self, token: Token):
        self.token = token
        self.value = token.value
    def __repr__(self):
        return f"NumNode({self.value})"

class VarNode(ASTNode):
    def __init__(self, token: Token):
        self.token = token
        self.name = token.value
    def __repr__(self):
        return f"VarNode({self.name})"

class UnaryOpNode(ASTNode):
    def __init__(self, op_token: Token, expr: ASTNode):
        self.op_token = op_token
        self.expr = expr
    def __repr__(self):
        return f"UnaryOpNode({self.op_token.value}, {self.expr})"

class BinOpNode(ASTNode):
    def __init__(self, left: ASTNode, op_token: Token, right: ASTNode):
        self.left = left
        self.op_token = op_token
        self.right = right
    def __repr__(self):
        return f"BinOpNode({self.left}, {self.op_token.value}, {self.right})"

class Precedence(Enum):
    LOWEST = 0
    SUM = 1       # +, -
    PRODUCT = 2   # *, /
    PREFIX = 3    # Unary +, -
    POWER = 4     # ^

PRECEDENCE_MAP = {
    TokenType.PLUS: Precedence.SUM,
    TokenType.MINUS: Precedence.SUM,
    TokenType.MULTIPLY: Precedence.PRODUCT,
    TokenType.DIVIDE: Precedence.PRODUCT,
    TokenType.POWER: Precedence.POWER,
}

class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.peek_token = self.lexer.get_next_token()
        self.current_token = None
        self.advance()

    def advance(self):
        self.current_token = self.peek_token
        self.peek_token = self.lexer.get_next_token()

    def error(self, msg: str):
        raise SyntaxError(f"Parser error at position {self.current_token.pos}: {msg}")

    def get_token_precedence(self, token_type: TokenType) -> Precedence:
        return PRECEDENCE_MAP.get(token_type, Precedence.LOWEST)

    def parse(self) -> ASTNode:
        expr = self.parse_expression(Precedence.LOWEST)
        if self.current_token.type != TokenType.EOF:
            self.error(f"Unexpected trailing token {self.current_token}")
        return expr

    def parse_expression(self, precedence: Precedence) -> ASTNode:
        # Parse Prefix / Null Denotation (nud)
        token = self.current_token
        self.advance()

        left = None
        if token.type == TokenType.INTEGER:
            left = NumNode(token)
        elif token.type == TokenType.IDENTIFIER:
            left = VarNode(token)
        elif token.type in (TokenType.PLUS, TokenType.MINUS):
            expr = self.parse_expression(Precedence.PREFIX)
            left = UnaryOpNode(token, expr)
        elif token.type == TokenType.LPAREN:
            left = self.parse_expression(Precedence.LOWEST)
            if self.current_token.type != TokenType.RPAREN:
                self.error("Expected closing parenthesis")
            self.advance()
        else:
            self.error(f"Unexpected token {token} in expression")

        # Parse Infix / Left Denotation (led)
        while precedence.value < self.get_token_precedence(self.current_token.type).value:
            op_token = self.current_token
            self.advance()

            # Handle right-associativity for power operator
            next_precedence = self.get_token_precedence(op_token.type)
            if op_token.type == TokenType.POWER:
                # Decrease precedence to allow right-associative binding
                next_precedence = Precedence(next_precedence.value - 1)

            right = self.parse_expression(next_precedence)
            left = BinOpNode(left, op_token, right)

        return left

class Evaluator:
    def __init__(self, env: dict = None):
        self.env = env if env is not None else {}

    def visit(self, node: ASTNode) -> float:
        method_name = f"visit_{type(node).__name__}"
        visitor = getattr(self, method_name, self.generic_visit)
        return visitor(node)

    def generic_visit(self, node: ASTNode):
        raise NotImplementedError(f"No visit_{type(node).__name__} method defined")

    def visit_NumNode(self, node: NumNode) -> float:
        return float(node.value)

    def visit_VarNode(self, node: VarNode) -> float:
        if node.name not in self.env:
            raise NameError(f"Undefined variable '{node.name}'")
        return float(self.env[node.name])

    def visit_UnaryOpNode(self, node: UnaryOpNode) -> float:
        val = self.visit(node.expr)
        if node.op_token.type == TokenType.PLUS:
            return +val
        elif node.op_token.type == TokenType.MINUS:
            return -val
        raise ValueError(f"Unknown unary operator {node.op_token}")

    def visit_BinOpNode(self, node: BinOpNode) -> float:
        left_val = self.visit(node.left)
        right_val = self.visit(node.right)
        op = node.op_token.type
        if op == TokenType.PLUS:
            return left_val + right_val
        elif op == TokenType.MINUS:
            return left_val - right_val
        elif op == TokenType.MULTIPLY:
            return left_val * right_val
        elif op == TokenType.DIVIDE:
            if right_val == 0:
                raise ZeroDivisionError("Division by zero")
            return left_val / right_val
        elif op == TokenType.POWER:
            return left_val ** right_val
        raise ValueError(f"Unknown binary operator {node.op_token}")

if __name__ == '__main__':
    code = "-3 + 2 ^ 3 ^ 2 * (x - 1)"
    lexer = Lexer(code)
    parser = Parser(lexer)
    ast_root = parser.parse()
    print("AST:", ast_root)
    evaluator = Evaluator({'x': 4})
    result = evaluator.visit(ast_root)
    print("Result:", result)
```

### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of tokens in the input string. Each token is scanned by the lexer once and processed by the Pratt parser a constant number of times.
- **Space Complexity:** $\mathcal{O}(D)$ where $D$ is the maximum depth of the Abstract Syntax Tree (or operator precedence stack recursion depth), which is $\mathcal{O}(N)$ in the worst case of unparenthesized chain expressions.

Here is a complete, production-ready Lexer implemented in modern C++20.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <sstream>
#include <cctype>
#include <stdexcept>

enum class TokenType {
    // Keywords
    KW_IF, KW_ELSE, KW_WHILE, KW_RETURN, KW_FN,
    // Literals
    IDENTIFIER, INT_LITERAL, FLOAT_LITERAL, STRING_LITERAL,
    // Operators & Punctuation
    PLUS, MINUS, STAR, SLASH, ASSIGN, EQ, NEQ, LT, GT,
    LPAREN, RPAREN, LBRACE, RBRACE, SEMICOLON, COMMA,
    // Special
    END_OF_FILE, UNKNOWN
};

std::string tokenTypeToString(TokenType type) {
    switch (type) {
        case TokenType::KW_IF: return "KW_IF";
        case TokenType::KW_ELSE: return "KW_ELSE";
        case TokenType::KW_WHILE: return "KW_WHILE";
        case TokenType::KW_RETURN: return "KW_RETURN";
        case TokenType::KW_FN: return "KW_FN";
        case TokenType::IDENTIFIER: return "IDENTIFIER";
        case TokenType::INT_LITERAL: return "INT_LITERAL";
        case TokenType::FLOAT_LITERAL: return "FLOAT_LITERAL";
        case TokenType::STRING_LITERAL: return "STRING_LITERAL";
        case TokenType::PLUS: return "PLUS";
        case TokenType::MINUS: return "MINUS";
        case TokenType::STAR: return "STAR";
        case TokenType::SLASH: return "SLASH";
        case TokenType::ASSIGN: return "ASSIGN";
        case TokenType::EQ: return "EQ";
        case TokenType::NEQ: return "NEQ";
        case TokenType::LT: return "LT";
        case TokenType::GT: return "GT";
        case TokenType::LPAREN: return "LPAREN";
        case TokenType::RPAREN: return "RPAREN";
        case TokenType::LBRACE: return "LBRACE";
        case TokenType::RBRACE: return "RBRACE";
        case TokenType::SEMICOLON: return "SEMICOLON";
        case TokenType::COMMA: return "COMMA";
        case TokenType::END_OF_FILE: return "EOF";
        default: return "UNKNOWN";
    }
}

struct SourceLocation {
    size_t line;
    size_t column;
};

struct Token {
    TokenType type;
    std::string lexeme;
    SourceLocation location;
};

class Lexer {
public:
    explicit Lexer(std::string source)
        : source_(std::move(source)), pos_(0), line_(1), column_(1) {
        initKeywords();
    }

    std::vector<Token> tokenize() {
        std::vector<Token> tokens;
        while (true) {
            skipWhitespaceAndComments();
            if (isAtEnd()) {
                tokens.push_back({TokenType::END_OF_FILE, "", {line_, column_}});
                break;
            }

            size_t startLine = line_;
            size_t startCol = column_;
            char c = peek();

            if (std::isalpha(c) || c == '_') {
                tokens.push_back(lexIdentifierOrKeyword(startLine, startCol));
            } else if (std::isdigit(c)) {
                tokens.push_back(lexNumber(startLine, startCol));
            } else if (c == '"') {
                tokens.push_back(lexString(startLine, startCol));
            } else {
                tokens.push_back(lexPunctuatorOrOperator(startLine, startCol));
            }
        }
        return tokens;
    }

private:
    std::string source_;
    size_t pos_;
    size_t line_;
    size_t column_;
    std::unordered_map<std::string, TokenType> keywords_;

    void initKeywords() {
        keywords_["if"] = TokenType::KW_IF;
        keywords_["else"] = TokenType::KW_ELSE;
        keywords_["while"] = TokenType::KW_WHILE;
        keywords_["return"] = TokenType::KW_RETURN;
        keywords_["fn"] = TokenType::KW_FN;
    }

    bool isAtEnd() const {
        return pos_ >= source_.length();
    }

    char peek() const {
        if (isAtEnd()) return '\0';
        return source_[pos_];
    }

    char advance() {
        char c = source_[pos_++];
        if (c == '\n') {
            line_++;
            column_ = 1;
        } else {
            column_++;
        }
        return c;
    }

    bool match(char expected) {
        if (isAtEnd()) return false;
        if (source_[pos_] != expected) return false;
        advance();
        return true;
    }

    void skipWhitespaceAndComments() {
        while (!isAtEnd()) {
            char c = peek();
            if (c == ' ' || c == '\r' || c == '\t' || c == '\n') {
                advance();
            } else if (c == '/' && pos_ + 1 < source_.length() && source_[pos_ + 1] == '/') {
                // Single-line comment
                while (!isAtEnd() && peek() != '\n') {
                    advance();
                }
            } else {
                break;
            }
        }
    }

    Token lexIdentifierOrKeyword(size_t startLine, size_t startCol) {
        size_t startPos = pos_;
        while (!isAtEnd() && (std::isalnum(peek()) || peek() == '_')) {
            advance();
        }
        std::string lexeme = source_.substr(startPos, pos_ - startPos);
        auto it = keywords_.find(lexeme);
        TokenType type = (it != keywords_.end()) ? it->second : TokenType::IDENTIFIER;
        return {type, lexeme, {startLine, startCol}};
    }

    Token lexNumber(size_t startLine, size_t startCol) {
        size_t startPos = pos_;
        bool isFloat = false;

        while (!isAtEnd() && std::isdigit(peek())) {
            advance();
        }

        if (!isAtEnd() && peek() == '.' && pos_ + 1 < source_.length() && std::isdigit(source_[pos_ + 1])) {
            isFloat = true;
            advance(); // consume '.'
            while (!isAtEnd() && std::isdigit(peek())) {
                advance();
            }
        }

        std::string lexeme = source_.substr(startPos, pos_ - startPos);
        TokenType type = isFloat ? TokenType::FLOAT_LITERAL : TokenType::INT_LITERAL;
        return {type, lexeme, {startLine, startCol}};
    }

    Token lexString(size_t startLine, size_t startCol) {
        advance(); // consume opening quote
        std::string lexeme;
        while (!isAtEnd() && peek() != '"') {
            char c = advance();
            if (c == '\\') {
                if (isAtEnd()) {
                    throw std::runtime_error("Unterminated string escape sequence");
                }
                char escaped = advance();
                switch (escaped) {
                    case 'n': lexeme += '\n'; break;
                    case 't': lexeme += '\t'; break;
                    case '"': lexeme += '"'; break;
                    case '\\': lexeme += '\\'; break;
                    default: lexeme += escaped; break;
                }
            } else {
                lexeme += c;
            }
        }

        if (isAtEnd()) {
            throw std::runtime_error("Unterminated string literal");
        }
        advance(); // consume closing quote
        return {TokenType::STRING_LITERAL, lexeme, {startLine, startCol}};
    }

    Token lexPunctuatorOrOperator(size_t startLine, size_t startCol) {
        char c = advance();
        switch (c) {
            case '+': return {TokenType::PLUS, "+", {startLine, startCol}};
            case '-': return {TokenType::MINUS, "-", {startLine, startCol}};
            case '*': return {TokenType::STAR, "*", {startLine, startCol}};
            case '/': return {TokenType::SLASH, "/", {startLine, startCol}};
            case '=':
                if (match('=')) return {TokenType::EQ, "==", {startLine, startCol}};
                return {TokenType::ASSIGN, "=", {startLine, startCol}};
            case '!':
                if (match('=')) return {TokenType::NEQ, "!=", {startLine, startCol}};
                throw std::runtime_error("Unexpected character '!'");
            case '<': return {TokenType::LT, "<", {startLine, startCol}};
            case '>': return {TokenType::GT, ">", {startLine, startCol}};
            case '(':
                if (match('=')) {}
                return {TokenType::LPAREN, "(", {startLine, startCol}};
            case ')': return {TokenType::RPAREN, ")", {startLine, startCol}};
            case '{': return {TokenType::LBRACE, "{", {startLine, startCol}};
            case '}': return {TokenType::RBRACE, "}", {startLine, startCol}};
            case ';': return {TokenType::SEMICOLON, ";", {startLine, startCol}};
            case ',': return {TokenType::COMMA, ",", {startLine, startCol}};
            default:
                std::string msg = "Unexpected character: ";
                msg += c;
                throw std::runtime_error(msg);
        }
    }
};

int main() {
    std::string code = R"(
        fn compute(x, y) {
            // Compute sum
            let result = x + y;
            return "Done: \n" + result;
        }
    )";

    try {
        Lexer lexer(code);
        auto tokens = lexer.tokenize();
        for (const auto& t : tokens) {
            std::cout << "Type: " << tokenTypeToString(t.type) 
                      << " | Lexeme: '" << t.lexeme << "' | Line: " 
                      << t.location.line << ", Col: " << t.location.column << "\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Lexer Error: " << e.what() << "\n";
    }
    return 0;
}
