enum class Type { INT, BOOL, VOID, UNKNOWN };

std::string typeToString(Type t) {
    switch (t) {
        case Type::INT: return "int";
        case Type::BOOL: return "bool";
        case Type::VOID: return "void";
        default: return "unknown";
    }
