// Forward Declarations
class ASTVisitor;

class ASTNode {
public:
    virtual ~ASTNode() = default;
    virtual void accept(ASTVisitor* visitor) = 0;
};

class ProgramNode : public ASTNode {
public:
    std::vector<std::unique_ptr<ASTNode>> statements;
    void accept(ASTVisitor* visitor) override;
};

class VarDeclNode : public ASTNode {
public:
    std::string name;
    Type type;
    std::unique_ptr<ASTNode> initializer;
    VarDeclNode(std::string n, Type t, std::unique_ptr<ASTNode> init)
        : name(std::move(n)), type(t), initializer(std::move(init)) {}
    void accept(ASTVisitor* visitor) override;
};

class AssignNode : public ASTNode {
public:
    std::string name;
    std::unique_ptr<ASTNode> expr;
    AssignNode(std::string n, std::unique_ptr<ASTNode> e)
        : name(std::move(n)), expr(std::move(e)) {}
    void accept(ASTVisitor* visitor) override;
};

class PrintNode : public ASTNode {
public:
    std::unique_ptr<ASTNode> expr;
    explicit PrintNode(std::unique_ptr<ASTNode> e) : expr(std::move(e)) {}
    void accept(ASTVisitor* visitor) override;
};

class BinOpNode : public ASTNode {
public:
    std::string op;
    std::unique_ptr<ASTNode> left;
    std::unique_ptr<ASTNode> right;
    BinOpNode(std::string o, std::unique_ptr<ASTNode> l, std::unique_ptr<ASTNode> r)
        : op(std::move(o)), left(std::move(l)), right(std::move(r)) {}
    void accept(ASTVisitor* visitor) override;
};

class NumNode : public ASTNode {
public:
    int value;
    explicit NumNode(int v) : value(v) {}
    void accept(ASTVisitor* visitor) override;
};

class IdentifierNode : public ASTNode {
public:
    std::string name;
    explicit IdentifierNode(std::string n) : name(std::move(n)) {}
    void accept(ASTVisitor* visitor) override;
};

class ASTVisitor {
public:
    virtual void visit(ProgramNode* node) = 0;
    virtual void visit(VarDeclNode* node) = 0;
    virtual void visit(AssignNode* node) = 0;
    virtual void visit(PrintNode* node) = 0;
    virtual void visit(BinOpNode* node) = 0;
    virtual void visit(NumNode* node) = 0;
    virtual void visit(IdentifierNode* node) = 0;
};

void ProgramNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void VarDeclNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void AssignNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void PrintNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void BinOpNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void NumNode::accept(ASTVisitor* visitor) { visitor->visit(this); }
void IdentifierNode::accept(ASTVisitor* visitor) { visitor->visit(this); }

class SymbolTable {
public:
    void enterScope() {
        scopes_.emplace_back();
    }
    void exitScope() {
        if (!scopes_.empty()) scopes_.pop_back();
    }
    bool declare(const std::string& name, Type type) {
        if (scopes_.empty()) enterScope();
        auto& current = scopes_.back();
        if (current.find(name) != current.end()) return false;
        current[name] = type;
        return true;
    }
    Type lookup(const std::string& name) {
        for (auto it = scopes_.rbegin(); it != scopes_.rend(); ++it) {
            auto found = it->find(name);
            if (found != it->end()) return found->second;
        }
        return Type::UNKNOWN;
    }
private:
    std::vector<std::unordered_map<std::string, Type>> scopes_;
};

class TypeChecker : public ASTVisitor {
public:
    Type currentExprType;

    void visit(ProgramNode* node) override {
        symbols_.enterScope();
        for (auto& stmt : node->statements) {
            stmt->accept(this);
        }
        symbols_.exitScope();
    }

    void visit(VarDeclNode* node) override {
        node->initializer->accept(this);
        if (currentExprType != node->type) {
            throw std::runtime_error("Type mismatch in variable declaration for '" + node->name + "'");
        }
        if (!symbols_.declare(node->name, node->type)) {
            throw std::runtime_error("Variable '" + node->name + "' already declared in scope.");
        }
    }

    void visit(AssignNode* node) override {
        Type varType = symbols_.lookup(node->name);
        if (varType == Type::UNKNOWN) {
            throw std::runtime_error("Undeclared variable '" + node->name + "'");
        }
        node->expr->accept(this);
        if (currentExprType != varType) {
            throw std::runtime_error("Type mismatch in assignment to '" + node->name + "'");
        }
    }

    void visit(PrintNode* node) override {
        node->expr->accept(this);
    }

    void visit(BinOpNode* node) override {
        node->left->accept(this);
        Type leftType = currentExprType;
        node->right->accept(this);
        Type rightType = currentExprType;

        if (node->op == "+" || node->op == "-" || node->op == "*") {
            if (leftType != Type::INT || rightType != Type::INT) {
                throw std::runtime_error("Arithmetic operators require integer operands");
            }
            currentExprType = Type::INT;
        } else if (node->op == "<") {
            if (leftType != Type::INT || rightType != Type::INT) {
                throw std::runtime_error("Comparison operators require integer operands");
            }
            currentExprType = Type::BOOL;
        } else {
            throw std::runtime_error("Unknown operator: " + node->op);
        }
    }

    void visit(NumNode* node) override {
        currentExprType = Type::INT;
    }

    void visit(IdentifierNode* node) override {
        Type t = symbols_.lookup(node->name);
        if (t == Type::UNKNOWN) {
            throw std::runtime_error("Undeclared identifier '" + node->name + "'");
        }
        currentExprType = t;
    }

private:
    SymbolTable symbols_;
};

int main() {
    // Manually construct an AST for demonstration: 
    // { int x = 10 + 5; x = x + 2; print(x); }
    auto prog = std::make_unique<ProgramNode>();

    auto initExpr = std::make_unique<BinOpNode>("+", std::make_unique<NumNode>(10), std::make_unique<NumNode>(5));
    prog->statements.push_back(std::make_unique<VarDeclNode>("x", Type::INT, std::move(initExpr)));

    auto assignExpr = std::make_unique<BinOpNode>("+", std::make_unique<IdentifierNode>("x"), std::make_unique<NumNode>(2));
    prog->statements.push_back(std::make_unique<AssignNode>("x", std::move(assignExpr)));

    prog->statements.push_back(std::make_unique<PrintNode>(std::make_unique<IdentifierNode>("x")));

    try {
        TypeChecker checker;
        prog->accept(&checker);
        std::cout << "Type checking completed successfully!\n";
    } catch (const std::exception& e) {
        std::cerr << "Semantic Error: " << e.what() << "\n";
    }

    return 0;
}
