- **Space Complexity:** $\mathcal{O}(D + S)$ where $D$ is the maximum AST depth and $S$ is the symbol table scope nesting depth.

Here is the complete, runnable Python implementation of a stack-based Bytecode VM with a simple compiler, full error checking, and safety bounds validation.

```python
import ast
from typing import List, Any, Dict

class OpCode:
    LOAD_CONST = 1
    ADD = 2
    SUB = 3
    MUL = 4
    DIV = 5
    EQ = 6
    LT = 7
    PRINT = 8
    JUMP = 9
    JUMP_IF_FALSE = 10
    HALT = 11

class BytecodeVM:
    def __init__(self, code: List[tuple], constants: List[Any]):
        self.code = code
        self.constants = constants
        self.stack: List[Any] = []
        self.ip = 0

    def run(self) -> None:
        code_len = len(self.code)
        while self.ip < code_len:
            instruction = self.code[self.ip]
            op = instruction[0]
            arg = instruction[1] if len(instruction) > 1 else None

            self.ip += 1

            if op == OpCode.LOAD_CONST:
                if arg < 0 or arg >= len(self.constants):
                    raise IndexError(f"Constant index out of bounds: {arg}")
                self.stack.append(self.constants[arg])

            elif op == OpCode.ADD:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on ADD")
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(a + b)

            elif op == OpCode.SUB:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on SUB")
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(a - b)

            elif op == OpCode.MUL:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on MUL")
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(a * b)

            elif op == OpCode.DIV:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on DIV")
                b = self.stack.pop()
                a = self.stack.pop()
                if b == 0:
                    raise ZeroDivisionError("Division by zero in VM")
                self.stack.append(a // b)

            elif op == OpCode.EQ:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on EQ")
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(1 if a == b else 0)

            elif op == OpCode.LT:
                if len(self.stack) < 2:
                    raise RuntimeError("Stack underflow on LT")
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(1 if a < b else 0)

            elif op == OpCode.PRINT:
                if len(self.stack) < 1:
                    raise RuntimeError("Stack underflow on PRINT")
                val = self.stack.pop()
                print(f"OUT: {val}")

            elif op == OpCode.JUMP:
                if arg < 0 or arg >= code_len:
                    raise ValueError(f"Invalid jump target: {arg}")
                self.ip = arg

            elif op == OpCode.JUMP_IF_FALSE:
                if len(self.stack) < 1:
                    raise RuntimeError("Stack underflow on JUMP_IF_FALSE")
                val = self.stack.pop()
                if arg < 0 or arg >= code_len:
                    raise ValueError(f"Invalid jump target: {arg}")
                if not val:
                    self.ip = arg

            elif op == OpCode.HALT:
                break
            else:
                raise RuntimeError(f"Unknown opcode: {op}")

class Compiler:
    def __init__(self):
        self.code: List[tuple] = []
        self.constants: List[Any] = []

    def add_const(self, val: Any) -> int:
        self.constants.append(val)
        return len(self.constants) - 1

    def compile_node(self, node: ast.AST):
        if isinstance(node, ast.Constant):
            c_idx = self.add_const(node.value)
            self.code.append((OpCode.LOAD_CONST, c_idx))
        elif isinstance(node, ast.BinOp):
            self.compile_node(node.left)
            self.compile_node(node.right)
            if isinstance(node.op, ast.Add):
                self.code.append((OpCode.ADD,))
            elif isinstance(node.op, ast.Sub):
                self.code.append((OpCode.SUB,))
            elif isinstance(node.op, ast.Mult):
                self.code.append((OpCode.MUL,))
            elif isinstance(node.op, ast.Div):
                self.code.append((OpCode.DIV,))
            else:
                raise NotImplementedError(f"Unsupported binary op: {type(node.op)}")
        elif isinstance(node, ast.Expr):
            self.compile_node(node.value)
            self.code.append((OpCode.PRINT,))
        elif isinstance(node, ast.Module):
            for stmt in node.body:
                self.compile_node(stmt)
        else:
            raise NotImplementedError(f"Unsupported AST node: {type(node)}")

if __name__ == "__main__":
    source = "(10 + 20) * 2 - 5"
    parsed_ast = ast.parse(source)
    compiler = Compiler()
    compiler.compile_node(parsed_ast)
    compiler.code.append((OpCode.HALT,))

    vm = BytecodeVM(compiler.code, compiler.constants)
    vm.run()
```

