- **Space Complexity**: $\mathcal{O}(V + C)$ where $V$ is the maximum depth of the VM operand stack and $C$ is the size of the bytecode instructions and constant pool.

Here is the complete, runnable Python implementation of a recursive descent parser with panic-mode error recovery and AST construction.

```python
import ast
from typing import List, Optional

class TokenType:
    INT = 'INT'
    ID = 'ID'
    ASSIGN = 'ASSIGN'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    SEMI = 'SEMI'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    LBRACE = 'LBRACE'
    RBRACE = 'RBRACE'
    IF = 'IF'
    ELSE = 'ELSE'
    WHILE = 'WHILE'
    EQ = 'EQ'
    EOF = 'EOF'

class Token:
    def __init__(self, type_: str, value: any, line: int, col: int):
        self.type = type_
        self.value = value
        self.line = line
        self.col = col

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def error(self, msg: str):
        raise SyntaxError(f"{msg} at line {self.line}, col {self.col}")

    def advance(self):
        if self.pos < len(self.text):
            if self.text[self.pos] == '\n':
                self.line += 1
                self.col = 1
            else:
                self.col += 1
            self.pos += 1

    def peek(self) -> str:
        if self.pos >= len(self.text):
            return ''
        return self.text[self.pos]

    def get_next_token(self) -> Token:
        while self.peek():
            c = self.peek()
            if c.isspace():
                self.advance()
                continue
            if c.isalpha():
                start_line, start_col = self.line, self.col
                val = ''
                while self.peek().isalnum():
                    val += self.peek()
                    self.advance()
                if val == 'if':
                    return Token(TokenType.IF, val, start_line, start_col)
                if val == 'else':
                    return Token(TokenType.ELSE, val, start_line, start_col)
                if val == 'while':
                    return Token(TokenType.WHILE, val, start_line, start_col)
                return Token(TokenType.ID, val, start_line, start_col)
            if c.isdigit():
                start_line, start_col = self.line, self.col
                val = ''
                while self.peek().isdigit():
                    val += self.peek()
                    self.advance()
                return Token(TokenType.INT, int(val), start_line, start_col)
            if c == '=':
                start_line, start_col = self.line, self.col
                self.advance()
                if self.peek() == '=':
                    self.advance()
                    return Token(TokenType.EQ, '==', start_line, start_col)
                return Token(TokenType.ASSIGN, '=', start_line, start_col)

            start_line, start_col = self.line, self.col
            self.advance()
            if c == '+': return Token(TokenType.PLUS, '+', start_line, start_col)
            if c == '-': return Token(TokenType.MINUS, '-', start_line, start_col)
            if c == ';': return Token(TokenType.SEMI, ';', start_line, start_col)
            if c == '(':
                return Token(TokenType.LPAREN, '(', start_line, start_col)
            if c == ')':
                return Token(TokenType.RPAREN, ')', start_line, start_col)
            if c == '{': return Token(TokenType.LBRACE, '{', start_line, start_col)
            if c == '}': return Token(TokenType.RBRACE, '}', start_line, start_col)

            self.error(f"Unexpected character '{c}'")
        return Token(TokenType.EOF, None, self.line, self.col)

class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()
        self.errors: List[str] = []

    def consume(self, token_type: str):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            raise SyntaxError(f"Expected token {token_type}, got {self.current_token.type} at line {self.current_token.line}")

    def synchronize(self):
        while self.current_token.type != TokenType.EOF:
            if self.current_token.type == TokenType.SEMI:
                self.consume(TokenType.SEMI)
                return
            if self.current_token.type in (TokenType.IF, TokenType.WHILE, TokenType.RBRACE):
                return
            self.current_token = self.lexer.get_next_token()

    def parse(self) -> List[Any]:
        statements = []
        while self.current_token.type != TokenType.EOF:
            try:
                statements.append(self.statement())
            except SyntaxError as e:
                self.errors.append(str(e))
                self.synchronize()
        return statements

    def statement(self):
        if self.current_token.type == TokenType.ID:
            return self.assignment_statement()
        elif self.current_token.type == TokenType.IF:
            return self.if_statement()
        elif self.current_token.type == TokenType.WHILE:
            return self.while_statement()
        else:
            raise SyntaxError(f"Invalid statement starting with {self.current_token.type}")

    def assignment_statement(self):
        var_name = self.current_token.value
        self.consume(TokenType.ID)
        self.consume(TokenType.ASSIGN)
        expr = self.expression()
        self.consume(TokenType.SEMI)
        return ("assign", var_name, expr)

    def if_statement(self):
        self.consume(TokenType.IF)
        self.consume(TokenType.LPAREN)
        cond = self.expression()
        self.consume(TokenType.RPAREN)
        self.consume(TokenType.LBRACE)
        body = []
        while self.current_token.type != TokenType.RBRACE and self.current_token.type != TokenType.EOF:
            body.append(self.statement())
        self.consume(TokenType.RBRACE)
        return ("if", cond, body)

    def while_statement(self):
        self.consume(TokenType.WHILE)
        self.consume(TokenType.LPAREN)
        cond = self.expression()
        self.consume(TokenType.RPAREN)
        self.consume(TokenType.LBRACE)
        body = []
        while self.current_token.type != TokenType.RBRACE and self.current_token.type != TokenType.EOF:
            body.append(self.statement())
        self.consume(TokenType.RBRACE)
        return ("while", cond, body)

    def expression(self):
        node = self.term()
        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS, TokenType.EQ):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.consume(TokenType.PLUS)
                node = ("binop", "+", node, self.term())
            elif token.type == TokenType.MINUS:
                self.consume(TokenType.MINUS)
                node = ("binop", "-", node, self.term())
            elif token.type == TokenType.EQ:
                self.consume(TokenType.EQ)
                node = ("binop", "==", node, self.term())
        return node

    def term(self):
        token = self.current_token
        if token.type == TokenType.INT:
            self.consume(TokenType.INT)
            return ("int", token.value)
        elif token.type == TokenType.ID:
            self.consume(TokenType.ID)
            return ("id", token.value)
        elif token.type == TokenType.LPAREN:
            self.consume(TokenType.LPAREN)
            node = self.expression()
            self.consume(TokenType.RPAREN)
            return node
        else:
            raise SyntaxError(f"Unexpected token in expression: {token.type}")

if __name__ == '__main__':
    prog = "x = 10 + ; y = 20 == 20;"
    lexer = Lexer(prog)
    parser = Parser(lexer)
    stmts = parser.parse()
    print("Parsed Statements:", stmts)
    print("Recovery Errors Encountered:", parser.errors)
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the number of tokens. Each token is processed in constant time during parsing and panic-mode synchronization.
- **Space Complexity**: $\mathcal{O}(D)$ where $D$ is the maximum recursive descent function call stack depth.

Here is the complete, runnable C++17 implementation of a nested symbol table supporting block scopes, variable shadowing, scoping chains, and rigorous error handling.

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <stdexcept>

enum class SymbolType {
    Integer,
    Float,
    Boolean
};

std::string symbol_type_to_string(SymbolType type) {
    switch (type) {
        case SymbolType::Integer: return "Integer";
        case SymbolType::Float: return "Float";
        case SymbolType::Boolean: return "Boolean";
    }
    return "Unknown";
}

struct Symbol {
    std::string name;
    SymbolType type;
};

class Scope : public std::enable_shared_from_this<Scope> {
    std::unordered_map<std::string, Symbol> symbols;
    std::shared_ptr<Scope> enclosing_scope;

public:
    explicit Scope(std::shared_ptr<Scope> enclosing = nullptr)
        : enclosing_scope(std::move(enclosing)) {}

    bool define(const std::string& name, SymbolType type) {
        if (symbols.find(name) != symbols.end()) {
            return false; // Already defined in current scope
        }
        symbols[name] = Symbol{name, type};
        return true;
    }

    const Symbol* resolve(const std::string& name) {
        auto it = symbols.find(name);
        if (it != symbols.end()) {
            return &(it->second);
        }
        if (enclosing_scope != nullptr) {
            return enclosing_scope->resolve(name);
        }
        return nullptr;
    }

    std::shared_ptr<Scope> get_enclosing() const {
        return enclosing_scope;
    }
};

class SymbolTable {
    std::shared_ptr<Scope> current_scope;

public:
    SymbolTable() {
        // Global scope
        current_scope = std::make_shared<Scope>(nullptr);
    }

    void enter_scope() {
        current_scope = std::make_shared<Scope>(current_scope);
    }

    void exit_scope() {
        if (current_scope->get_enclosing() == nullptr) {
            throw std::runtime_error("Cannot exit global scope");
        }
        current_scope = current_scope->get_enclosing();
    }

    void declare(const std::string& name, SymbolType type) {
        if (!current_scope->define(name, type)) {
            throw std::runtime_error("Redefinition of symbol: " + name);
        }
    }

    Symbol lookup(const std::string& name) {
        const Symbol* sym = current_scope->resolve(name);
        if (sym == nullptr) {
            throw std::runtime_error("Unresolved reference to symbol: " + name);
        }
        return *sym;
    }
};

int main() {
    try {
        SymbolTable symtab;

        symtab.declare("global_var", SymbolType::Integer);
        std::cout << "Declared global_var of type Integer.\n";

        symtab.enter_scope();
        symtab.declare("local_var", SymbolType::Float);
        std::cout << "Declared local_var in inner scope.\n";

        // Test shadowing
        symtab.declare("global_var", SymbolType::Boolean);
        std::cout << "Shadowed global_var in inner scope with type Boolean.\n";

        Symbol v1 = symtab.lookup("global_var");
        std::cout << "Resolved global_var in inner scope: " << symbol_type_to_string(v1.type) << "\n";

        symtab.exit_scope();

        Symbol v2 = symtab.lookup("global_var");
        std::cout << "Resolved global_var after exiting inner scope: " << symbol_type_to_string(v2.type) << "\n";

        // This will throw unresolved exception
        symtab.lookup("local_var");

    } catch (const std::exception& e) {
        std::cerr << "Symbol Table Error: " << e.what() << std::endl;
    }

    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(K)$ where $K$ is the nesting depth of scopes during symbol lookup and insertion, with table lookups taking expected $\mathcal{O}(1)$ time per scope level.
- **Space Complexity**: $\mathcal{O}(S)$ where $S$ is the total number of defined symbols stored across all active scopes.

Here is the complete implementation of a Pratt parser with a custom lexer, token definitions, AST classes, and expression evaluator in Python.

```python
import enum
import math
import ast

class TokenType(enum.Enum):
    NUMBER = "NUMBER"
    IDENTIFIER = "IDENTIFIER"
    PLUS = "+"
    MINUS = "-"
    MULTIPLY = "*"
    DIVIDE = "/"
    CARET = "^"
    LPAREN = "("
    RPAREN = ")"
    EOF = "EOF"

class Token:
    def __init__(self, type: TokenType, value: str, position: int):
        self.type = type
        self.value = value
        self.position = position

    def __repr__(self):
        return f"Token({self.type.name}, {repr(self.value)}, pos={self.position})"

class LexerError(Exception):
    pass

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def _advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def _skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self._advance()

    def _lexer_number(self) -> Token:
        result = ""
        start_pos = self.pos
        decimal_point_seen = False
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if decimal_point_seen:
                    raise LexerError(f"Invalid malformed number at position {self.pos}")
                decimal_point_seen = True
            result += self.current_char
            self._advance()
        return Token(TokenType.NUMBER, result, start_pos)

    def _lexer_identifier(self) -> Token:
        result = ""
        start_pos = self.pos
        while self.current_char is not None and (self.current_char.isalnum() or self.current_char == '_'):
            result += self.current_char
            self._advance()
        return Token(TokenType.IDENTIFIER, result, start_pos)

    def get_next_token(self) -> Token:
        while self.current_char is not None:
            if self.current_char.isspace():
                self._skip_whitespace()
                continue

            if self.current_char.isalpha() or self.current_char == '_':
                return self._lexer_identifier()

            if self.current_char.isdigit():
                return self._lexer_number()

            if self.current_char == '+':
                tok = Token(TokenType.PLUS, "+", self.pos)
                self._advance()
                return tok

            if self.current_char == '-':
                tok = Token(TokenType.MINUS, "-", self.pos)
                self._advance()
                return tok

            if self.current_char == '*':
                tok = Token(TokenType.MULTIPLY, "*", self.pos)
                self._advance()
                return tok

            if self.current_char == '/':
                tok = Token(TokenType.DIVIDE, "/", self.pos)
                self._advance()
                return tok

            if self.current_char == '^':
                tok = Token(TokenType.CARET, "^", self.pos)
                self._advance()
                return tok

            if self.current_char == '(':
                tok = Token(TokenType.LPAREN, "(", self.pos)
                self._advance()
                return tok

            if self.current_char == ')':
                tok = Token(TokenType.RPAREN, ")", self.pos)
                self._advance()
                return tok

            raise LexerError(f"Unexpected character '{self.current_char}' at position {self.pos}")

        return Token(TokenType.EOF, "", self.pos)

class ASTNode:
    pass

class NumberNode(ASTNode):
    def __init__(self, value: str):
        self.value = float(value) if '.' in value else int(value)

    def __repr__(self):
        return f"NumberNode({self.value})"

class IdentifierNode(ASTNode):
    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return f"IdentifierNode({self.name})"

class UnaryOpNode(ASTNode):
    def __init__(self, op: Token, expr: ASTNode):
        self.op = op
        self.expr = expr

    def __repr__(self):
        return f"UnaryOpNode({self.op.value}, {self.expr})"

class BinaryOpNode(ASTNode):
    def __init__(self, left: ASTNode, op: Token, right: ASTNode):
        self.left = left
        self.op = op
        self.right = right

    def __repr__(self):
        return f"BinaryOpNode({self.left}, {self.op.value}, {self.right})"

class Precedence(enum.IntEnum):
    LOWEST = 0
    SUM = 1        # +, -
    PRODUCT = 2    # *, /
    PREFIX = 3     # unary +, -
    EXPONENT = 4   # ^

class ParseError(Exception):
    pass

class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()
        self.peek_token = self.lexer.get_next_token()

        self.prefix_parselets = {}
        self.infix_parselets = {}

        self.register_prefix(TokenType.NUMBER, self._parse_literal)
        self.register_prefix(TokenType.IDENTIFIER, self._parse_identifier)
        self.register_prefix(TokenType.PLUS, self._parse_unary)
        self.register_prefix(TokenType.MINUS, self._parse_unary)
        self.register_prefix(TokenType.LPAREN, self._parse_grouping)

        self.register_infix(TokenType.PLUS, self._parse_binary, Precedence.SUM, False)
        self.register_infix(TokenType.MINUS, self._parse_binary, Precedence.SUM, False)
        self.register_infix(TokenType.MULTIPLY, self._parse_binary, Precedence.PRODUCT, False)
        self.register_infix(TokenType.DIVIDE, self._parse_binary, Precedence.PRODUCT, False)
        self.register_infix(TokenType.CARET, self._parse_binary, Precedence.EXPONENT, True)

    def _advance(self):
        self.current_token = self.peek_token
        self.peek_token = self.lexer.get_next_token()

    def register_prefix(self, token_type: TokenType, parselet):
        self.prefix_parselets[token_type] = parselet

    def register_infix(self, token_type: TokenType, parselet, precedence: Precedence, is_right_assoc: bool):
        self.infix_parselets[token_type] = (parselet, precedence, is_right_assoc)

    def _get_precedence(self, token_type: TokenType) -> Precedence:
        if token_type in self.infix_parselets:
            return self.infix_parselets[token_type][1]
        return Precedence.LOWEST

    def parse_expression(self, precedence: Precedence = Precedence.LOWEST) -> ASTNode:
        prefix_func = self.prefix_parselets.get(self.current_token.type)
        if prefix_func is None:
            raise ParseError(f"Unexpected token {self.current_token.type} at position {self.current_token.position}")

        left = prefix_func(self.current_token)

        while precedence < self._get_precedence(self.peek_token.type):
            infix_entry = self.infix_parselets.get(self.peek_token.type)
            if infix_entry is None:
                break

            infix_func, prec, is_right_assoc = infix_entry
            self._advance()
            left = infix_func(left, self.current_token, prec, is_right_assoc)

        return left

    def _parse_literal(self, token: Token) -> ASTNode:
        self._advance()
        return NumberNode(token.value)

    def _parse_identifier(self, token: Token) -> ASTNode:
        self._advance()
        return IdentifierNode(token.value)

    def _parse_unary(self, token: Token) -> ASTNode:
        op_token = token
        self._advance()
        expr = self.parse_expression(Precedence.PREFIX)
        return UnaryOpNode(op_token, expr)

    def _parse_grouping(self, token: Token) -> ASTNode:
        self._advance()
        expr = self.parse_expression(Precedence.LOWEST)
        if self.current_token.type != TokenType.RPAREN:
            raise ParseError(f"Expected closing parenthesis, got {self.current_token.type} at position {self.current_token.position}")
        self._advance()
        return expr

    def _parse_binary(self, left: ASTNode, token: Token, precedence: Precedence, is_right_assoc: bool) -> ASTNode:
        op_token = token
        self._advance()
        next_precedence = precedence - 1 if is_right_assoc else precedence
        right = self.parse_expression(next_precedence)
        return BinaryOpNode(left, op_token, right)

if __name__ == "__main__":
    expr_str = "-3 + 5 * (2 ^ 3 ^ 2) - x / 2"
    lexer = Lexer(expr_str)
    parser = Parser(lexer)
    ast_tree = parser.parse_expression()
    print("Parsed AST:", ast_tree)
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ is the number of tokens in the input stream. Each token is visited and processed a constant number of times during lexing and Pratt parsing.
- **Space Complexity**: $\mathcal{O}(D)$ where $D$ is the maximum depth of nested expressions (recursion stack depth) and AST allocations. In the worst-case degenerate grammar, this is $\mathcal{O}(N)$.

Here is the complete, high-performance consistent hashing ring implemented in C++ with virtual nodes.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <stdexcept>
#include <functional>

class ConsistentHashRing {
private:
    uint32_t murmur_hash(const std::string& key) const {
        uint32_t hash = 2166136261u;
        for (char c : key) {
            hash ^= static_cast<uint32_t>(c);
            hash *= 16777619u;
        }
        return hash;
    }

    int replicas;
    std::map<uint32_t, std::string> ring;
    std::set<std::string> nodes;

public:
    explicit ConsistentHashRing(int vnodes = 100) : replicas(vnodes) {
        if (vnodes <= 0) {
            throw std::invalid_argument("Replica count must be greater than zero.");
        }
    }

    void add_node(const std::string& node) {
        if (node.empty()) {
            throw std::invalid_argument("Node identifier cannot be empty.");
        }
        if (nodes.count(node)) {
            return;
        }
        nodes.insert(node);
        for (int i = 0; i < replicas; ++ichl++) {
            std::string vnode_key = node + "#" + std::to_string(i);
            uint32_t hash = murmur_hash(vnode_key);
            ring[hash] = node;
        }
    }

    void remove_node(const std::string& node) {
        if (!nodes.count(node)) {
            return;
        }
        nodes.erase(node);
        for (int i = 0; i < replicas; ++i) {
            std::string vnode_key = node + "#" + std::to_string(i);
            uint32_t hash = murmur_hash(vnode_key);
            ring.erase(hash);
        }
    }

    std::string get_node(const std::string& key) const {
        if (ring.empty()) {
            throw std::runtime_error("Hash ring contains no nodes.");
        }
        uint32_t hash = murmur_hash(key);
        auto it = ring.lower_bound(hash);
        if (it == ring.end()) {
            it = ring.begin();
        }
        return it->second;
    }
};
```

### Complexity Analysis
- **Time Complexity**: 
  - `add_node`: $O(V \log(N \cdot V))$ where $V$ is the number of virtual nodes and $N$ is the physical node count.
  - `get_node`: $O(\log(N \cdot V))$ utilizing binary search on the red-black tree map.
- **Space Complexity**: $O(N \cdot V)$ space to maintain the token mapping ring.

