            if current_time - last_seen > self.timeout_seconds:
                dead_nodes.add(node_id)
        return dead_nodes

    def remove_node(self, node_id: str) -> None:
        if node_id in self.heartbeats:
            del self.heartbeats[node_id]

    def is_alive(self, node_id: str) -> bool:
