class WALIndexManager {
private:
    struct LogIndexRecord {
        uint64_t term;
        uint64_t file_offset;
        uint32_t payload_size;
    };

    std::vector<LogIndexRecord> index;
    uint64_t base_index;

public:
    explicit WALIndexManager(uint64_t starting_index = 1) : base_index(starting_index) {}

    void append(uint64_t term, uint64_t file_offset, uint32_t payload_size) {
        index.push_back({term, file_offset, payload_size});
    }

    std::pair<uint64_t, uint32_t> get_location(uint64_t log_index) const {
        if (log_index < base_index || log_index >= base_index + index.size()) {
            throw std::out_of_range("Requested log index is out of bounds.");
        }
        size_t internal_idx = static_cast<size_t>(log_index - base_index);
        const auto& record = index[internal_idx];
        return {record.file_offset, record.payload_size};
    }

    uint64_t get_term(uint64_t log_index) const {
        if (log_index < base_index || log_index >= base_index + index.size()) {
            throw std::out_of_range("Requested log index is out of bounds.");
        }
        size_t internal_idx = static_cast<size_t>(log_index - base_index);
        return index[internal_idx].term;
    }

    uint64_t last_index() const {
        if (index.empty()) {
            return base_index > 0 ? base_index - 1 : 0;
        }
        return base_index + index.size() - 1;
    }
};
