import hashlib
import bisect

class ConsistentHashRing:
    def __init__(self, replicas: int = 100):
        self.replicas = replicas
        self.ring = []
        self.node_map = {}

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode('utf-8')).hexdigest(), 16)

    def add_node(self, node: str):
        for i in range(self.replicas):
            virtual_key = f"{node}-vnode-{i}"
            hash_val = self._hash(virtual_key)
            bisect.insort(self.ring, hash_val)
            self.node_map[hash_val] = node

    def remove_node(self, node: str):
        to_remove = []
        for hash_val, mapped_node in self.node_map.items():
            if mapped_node == node:
                to_remove.append(hash_val)

        for hash_val in to_remove:
            idx = bisect.bisect_left(self.ring, hash_val)
            if idx < len(self.ring) and self.ring[idx] == hash_val:
                self.ring.pop(idx)
            del self.node_map[hash_val]

    def get_node(self, key: str) -> str:
        if not self.ring:
            raise ValueError("Hash ring is empty")

        hash_val = self._hash(key)
        idx = bisect.bisect_right(self.ring, hash_val)

        if idx == len(self.ring):
            idx = 0

        return self.node_map[self.ring[idx]]
```

