```cpp
#include <chrono>
#include <mutex>
#include <algorithm>

class TokenBucket {
private:
    double capacity;
    double tokens;
    double refill_rate_per_second;
    std::chrono::steady_clock::time_point last_refill;
    std::mutex mtx;

    void refill() {
        auto now = std::chrono::steady_clock::now();
        double elapsed = std::chrono::duration<double>(now - last_refill).count();
        last_refill = now;
        tokens = std::min(capacity, tokens + elapsed * refill_rate_per_second);
    }

public:
    TokenBucket(double capacity, double refill_rate_per_second)
        : capacity(capacity), tokens(capacity), refill_rate_per_second(refill_rate_per_second), last_refill(std::chrono::steady_clock::now()) {}

    bool consume(double count) {
        std::lock_guard<std::mutex> lock(mtx);
        refill();
        if (tokens >= count) {
            tokens -= count;
            return true;
        }
        return false;
    }
};
```

