from typing import Dict, Set
from enum import Enum

class CausalRelation(Enum):
    LESS_THAN = -1
    CONCURRENT = 0
    GREATER_THAN = 1
    EQUAL = 2

class VectorClock:
    def __init__(self, node_id: str, clock: Dict[str, int] = None):
        if not node_id:
            raise ValueError("node_id must be provided")
        self.node_id = node_id
        self.clock: Dict[str, int] = dict(clock) if clock else {}
        if self.node_id not in self.clock:
            self.clock[self.node_id] = 0

    def tick(self) -> 'VectorClock':
        self.clock[self.node_id] += 1
        return self

    def update(self, incoming: 'VectorClock') -> 'VectorClock':
        if not isinstance(incoming, VectorClock):
            raise TypeError("Incoming clock must be an instance of VectorClock")
        all_keys: Set[str] = set(self.clock.keys()).union(set(incoming.clock.keys()))
        for k in all_keys:
            self.clock[k] = max(self.clock.get(k, 0), incoming.clock.get(k, 0))
        return self

    def compare(self, other: 'VectorClock') -> CausalRelation:
        if not isinstance(other, VectorClock):
            raise TypeError("Other clock must be an instance of VectorClock")

        all_keys = set(self.clock.keys()).union(set(other.clock.keys()))

        self_less_or_equal = True
        other_less_or_equal = True

        for k in all_keys:
            v_self = self.clock.get(k, 0)
            v_other = other.clock.get(k, 0)
            if v_self > v_other:
                other_less_or_equal = False
            if v_self < v_other:
                self_less_or_equal = False

        if self_less_or_equal and other_less_or_equal:
            return CausalRelation.EQUAL
        elif self_less_or_equal:
            return CausalRelation.LESS_THAN
        elif other_less_or_equal:
            return CausalRelation.GREATER_THAN
        else:
            return CausalRelation.CONCURRENT

    def __repr__(self) -> str:
        return f"VectorClock({self.clock})"

if __name__ == "__main__":
    vc1 = VectorClock("A")
    vc2 = VectorClock("B")
    vc1.tick()
    vc2.update(vc1)
    vc2.tick()
    print(vc1.compare(vc2))  # CausalRelation.LESS_THAN
```

