import random
import time
from typing import Dict, List

class NodeMetadata:
    def __init__(self, node_id: str, address: str, heartbeat: int):
        self.node_id = node_id
        self.address = address
        self.heartbeat = heartbeat
        self.last_updated = time.time()
        self.is_alive = True

class GossipCluster:
    def __init__(self, local_id: str, fanout: int = 3):
        if not local_id:
            raise ValueError("local_id is mandatory")
        self.local_id = local_id
        self.fanout = fanout
        self.members: Dict[str, NodeMetadata] = {}

    def upsert_member(self, node_id: str, address: str, heartbeat: int):
        if node_id == self.local_id:
            return
        if node_id in self.members:
            existing = self.members[node_id]
            if heartbeat > existing.heartbeat:
                existing.heartbeat = heartbeat
                existing.address = address
                existing.last_updated = time.time()
                existing.is_alive = True
        else:
            self.members[node_id] = NodeMetadata(node_id, address, heartbeat)

    def get_random_peers(self, count: int = None) -> List[NodeMetadata]:
        target_count = count if count is not None else self.fanout
        alive_nodes = [m for m in self.members.values() if m.is_alive]
        if not alive_nodes:
            return []
        selected_count = min(target_count, len(alive_nodes))
        return random.sample(alive_nodes, selected_count)

    def check_failure_detector(self, t_out: float = 5.0):
        current_time = time.time()
        for member in self.members.values():
            if current_time - member.last_updated > t_out:
                member.is_alive = False

