class VectorClock:
    def __init__(self, node_id: str, initial_clock: dict = None):
        if not node_id:
            raise ValueError("Node ID cannot be empty")
        self.node_id = node_id
        self.clock = dict(initial_clock) if initial_clock else {node_id: 0}

    def increment(self):
