        for k in all_keys:
            self.clock[k] = max(self.clock.get(k, 0), other.clock.get(k, 0))
        self.clock[self.node_id] = self.clock.get(self.node_id, 0) + 1
        return self

    def compare(self, other: 'VectorClock') -> str:
