#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>
#include <cstring>
#include <arpa/inet.h>

class NetworkFrameCodec {
public:
    static constexpr size_t MAX_FRAME_SIZE = 1024 * 1024;

    static std::vector<uint8_t> encode(const std::string& payload) {
        if (payload.size() > MAX_FRAME_SIZE) {
            throw std::overflow_error("Payload exceeds maximum allowable frame size");
        }
        uint32_t net_length = htonl(static_cast<uint32_t>(payload.size()));
        std::vector<uint8_t> frame;
        frame.resize(sizeof(uint32_t) + payload.size());

        std::memcpy(frame.data(), &net_length, sizeof(uint32_t));
        std::memcpy(frame.data() + sizeof(uint32_t), payload.data(), payload.size());
        return frame;
    }

    static std::string decode(const uint8_t* buffer, size_t buffer_size, size_t& bytes_consumed) {
        if (buffer_size < sizeof(uint32_t)) {
            throw std::underflow_error("Buffer too small for length header");
        }

        uint32_t net_length;
        std::memcpy(&net_length, buffer, sizeof(uint32_t));
        uint32_t payload_length = ntohl(net_length);

        if (payload_length > MAX_FRAME_SIZE) {
            throw std::runtime_error("Decoded payload length exceeds protocol limits");
        }

        if (buffer_size < sizeof(uint32_t) + payload_length) {
            bytes_consumed = 0;
            throw std::underflow_error("Incomplete frame in stream buffer");
        }

        bytes_consumed = sizeof(uint32_t) + payload_length;
        return std::string(reinterpret_cast<const char*>(buffer + sizeof(uint32_t)), payload_length);
    }
};

int main() {
    std::string msg = "Hello Distributed Systems";
    auto encoded = NetworkFrameCodec::encode(msg);
    size_t consumed = 0;
    std::string decoded = NetworkFrameCodec::decode(encoded.data(), encoded.size(), consumed);
    return 0;
}
