class RaftLogReplication:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.current_term = 1
        self.log = []
        self.commit_index = 0
        self.last_applied = 0

    def append_entries(self, term: int, leader_id: str, prev_log_index: int, prev_log_term: int, entries: list, leader_commit: int) -> dict:
        if term < self.current_term:
            return {"term": self.current_term, "success": False}

        if term > self.current_term:
            self.current_term = term

        if prev_log_index > 0:
            if prev_log_index > len(self.log):
                return {"term": self.current_term, "success": False}
            if self.log[prev_log_index - 1]["term"] != prev_log_term:
                return {"term": self.current_term, "success": False}

        insert_index = prev_log_index
        for entry in entries:
            if insert_index < len(self.log):
                if self.log[insert_index]["term"] != entry["term"]:
                    self.log = self.log[:insert_index]
                    self.log.append(entry)
            else:
                self.log.append(entry)
            insert_index += 1

        if leader_commit > self.commit_index:
            self.commit_index = min(leader_commit, len(self.log))

        return {"term": self.current_term, "success": True}

