#include <cstdlib>
#include <new>

class LockFreeAllocator {
private:
    struct Block {
        std::atomic<Block*> next;
    };

    std::atomic<Block*> freelist{nullptr};

public:
    LockFreeAllocator(size_t pool_size) {
        for (size_t i = 0; i < pool_size; ++i) {
            Block* block = static_cast<Block*>(std::malloc(sizeof(Block)));
            block->next.store(freelist.load(std::memory_order_relaxed));
            freelist.store(block, std::memory_order_release);
        }
    }

    ~LockFreeAllocator() {
        Block* current = freelist.load();
        while (current) {
            Block* next = current->next.load();
            std::free(current);
            current = next;
        }
    }

    Block* allocate() {
        Block* old_head;
        do {
            old_head = freelist.load(std::memory_order_acquire);
            if (!old_head) return nullptr;
        } while (!freelist.compare_exchange_weak(old_head, old_head->next.load(std::memory_order_relaxed),
                                               std::memory_order_release, std::memory_order_relaxed));
        return old_head;
    }

    void deallocate(Block* block) {
        Block* old_head;
        do {
            old_head = freelist.load(std::memory_order_relaxed);
            block->next.store(old_head, std::memory_order_relaxed);
        } while (!freelist.compare_exchange_weak(old_head, block,
                                               std::memory_order_release, std::memory_order_relaxed));
    }
};

