                    if (next == nullptr) continue;
                    result = next->data;
                    if (head.compare_exchange_weak(first, next)) {
                        // Reclaim memory safely in production via Hazard Pointers or Epoch-based GC
                        delete first;
                        return true;
                    }
                }
            }
        }
    }
};

int main() {
    LockFreeQueue<int> q;
    std::vector<std::thread> producers;
    std::vector<std::thread> consumers;

    for (int i = 0; i < 3; ++i) {
        producers.emplace_back([&q, i]() {
            for (int j = 0; j < 100; ++j) {
                q.enqueue(i * 100 + j);
            }
        });
    }

    for (int i = 0; i < 3; ++i) {
        consumers.emplace_back([&q]() {
            int val;
            for (int j = 0; j < 100; ++j) {
                while (!q.dequeue(val)) {
                    std::this_thread::yield();
                }
            }
        });
    }

    for (auto& t : producers) t.join();
    for (auto& t : consumers) t.join();

    std::cout << "Lock-free queue operations completed successfully.\n";
    return 0;
}
```

### 3. Failure Modes and Mitigation
- **Memory Reclamation Hazards**: The naive `delete first` in the dequeue loop introduces a severe use-after-free race condition if a preempted thread still references `first`. In production systems, this requires **Hazard Pointers** (thread-local pointer protection arrays) or **Epoch-Based Reclamation (EBR)** to defer memory deallocation until all active threads exit the critical epoch.

### 1. Mathematical Formulation of Priority Inversion

Consider three real-time threads with static priorities $P_H > P_M > P_L$, where $P_H$ is highest and $P_L$ is lowest. 
1. Thread $L$ acquires a shared mutex $M$ and enters its critical section.
2. Thread $H$ preempts $L$, attempts to acquire mutex $M$, and blocks, transitioning to the waiting state.
3. A medium-priority thread $M$ becomes ready and preempts $L$ because $P_M > P_L$.

**The Inversion Bound**: Thread $H$ (highest priority) is indirectly delayed by Thread $M$ (medium priority) despite having no direct dependency. In non-deterministic systems, this unbounded priority inversion can cause critical real-time deadline misses (Rate Monotonic Scheduling violations).

**Priority Inheritance Protocol (PIP)**: When a high-priority thread blocks on a resource held by a lower-priority thread, the lower-priority thread temporarily inherits the priority of the blocked high-priority thread ($P_L \leftarrow P_H$), preventing medium-priority preemption until the resource is released.

