class PriorityMutex {
public:
    explicit PriorityMutex(int owner_initial_priority = 0) 
        : owner_(nullptr), current_priority_(owner_initial_priority), locked_(false) {}

    void lock(int thread_priority, std::atomic<int>& thread_effective_priority) {
        std::unique_lock<std::mutex> lk(internal_mtx_);
        while (locked_) {
            // Priority Inheritance: Elevate owner priority
            if (owner_ && thread_priority > current_priority_) {
                current_priority_ = thread_priority;
