    std::function<void(int)> recursive_task = [&](int n) {
        if (n <= 0) return;
        TrampolineExecutor::execute([&, n]() {
            std::cout << "Executing step: " << n << " on thread: " << std::this_thread::get_id() << "\n";
            recursive_task(n - 1);
        });
    };

    std::thread worker([&]() {
        recursive_task(20);
    });

    worker.join();
    std::cout << "Trampolining execution completed successfully without starvation.\n";
    return 0;
}
