// Simulating cache coherence pressure under high reader-writer contention
struct SharedState {
    alignas(64) std::atomic<uint64_t> shared_counter{0};
    alignas(64) std::atomic<bool> stop_flag{false};
};

void reader_worker(const SharedState& state, uint64_t& local_sum) {
    uint64_t reads = 0;
    while (!state.stop_flag.load(std::memory_order_relaxed)) {
        local_sum += state.shared_counter.load(std::memory_order_acquire);
        ++reads;
