## 1. Architectural Design of an L1-Residue SPSC Ring Buffer

To achieve maximum throughput and minimum latency in high-frequency trading or telemetry pipelines, an SPSC ring buffer must eliminate:
1. **Lock Contention**: Achieved via atomic head and tail indices.
2. **False Sharing**: Producer pointer (`head_`) and consumer pointer (`tail_`) must reside on completely separate 64-byte cache lines to prevent MESI state bouncing.
3. **Memory Order Overhead**: Use `std::memory_order_acquire` for reads and `std::memory_order_release` for writes, avoiding sequential consistency (`std::memory_order_seq_cst`) penalties.

---

## 2. Complete Runnable Implementation

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <new>

template <typename T, size_t Capacity>
class SPSCRingBuffer {
private:
    static_uff((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two");

    // Align producer pointer on its own cache line
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> head_{0};

    // Align consumer pointer on its own cache line
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> tail_{0};

    std::vector<T> buffer_{Capacity};

public:
    SPSCRingBuffer() = default;

    bool push(const T& item) {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if ((current_head - current_tail) >= Capacity) {
            return false; // Full
        }

        buffer_[current_head & (Capacity - 1)] = item;
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if (current_tail == current_head) {
            return false; // Empty
        }

        item = buffer_[current_tail & (Capacity - 1)];
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }
};

int main() {
    SPSCRingBuffer<uint64_t, 1024> ring_buffer;
    std::atomic<bool> running{true};
    uint64_t consumed_sum = 0;

    std::thread producer([&]() {
        for (uint64_t i = 0; i < 1'000'000; ++i) {
            while (!ring_buffer.push(i)) {
                std::this_thread::yield();
            }
        }
    });

    std::thread consumer([&]() {
        uint64_t val;
        uint64_t count = 0;
        while (count < 1'000'000) {
            if (ring_buffer.pop(val)) {
                consumed_sum += val;
                ++count;
            } else {
                std::this_thread::yield();
            }
        }
        running.store(false);
    });

    producer.join();
    consumer.join();

    std::cout << "SPSC Ring Buffer test passed. Consumed sum: " << consumed_sum << "\n";
    return 0;
}
```

