### Complete Python Implementation: Tunable Consistency Store with Vector Clocks

```python
import time
from typing import Dict, List, Tuple

class VectorClock:
    def __init__(self, clocks: Dict[str, int] = None):
        self.clocks = clocks.copy() if clocks else {}

    def increment(self, node_id: str):
        self.clocks[node_id] = self.clocks.get(node_id, 0) + 1

    def merge(self, other: 'VectorClock'):
        all_keys = set(self.clocks.keys()).union(set(other.clocks.keys()))
        for k in all_keys:
            self.clocks[k] = max(self.clocks.get(k, 0), other.clocks.get(k, 0))

    def is_concurrent_with(self, other: 'VectorClock') -> bool:
        self_greater = False
        other_greater = False
        all_keys = set(self.clocks.keys()).union(set(other.clocks.keys()))
        for k in all_keys:
            s_val = self.clocks.get(k, 0)
            o_val = other.clocks.get(k, 0)
            if s_val > o_val:
                self_greater = True
            elif s_val < o_val:
                other_greater = True
        return self_greater and other_greater

    def __repr__(self):
        return str(self.clocks)

class StorageNode:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.store: Dict[str, Tuple[str, VectorClock]] = {}

    def local_write(self, key: str, value: str, vclock: VectorClock) -> Tuple[str, VectorClock]:
        vclock.increment(self.node_id)
        self.store[key] = (value, vclock)
        return value, vclock

    def local_read(self, key: str) -> Optional[Tuple[str, VectorClock]]:
        return self.store.get(key)

class DistributedStore:
    def __init__(self, nodes: List[StorageNode]):
        self.nodes = nodes

    def write(self, key: str, value: str, consistency_level: str = "QUORUM") -> Tuple[str, VectorClock]:
        # Generate unified vector clock across nodes
        merged_clock = VectorClock()
        for node in self.nodes:
            existing = node.local_read(key)
            if existing:
                merged_clock.merge(existing[1])

        # PAC/ELC Trade-off: Write to nodes based on consistency level
        target_nodes = self.nodes if consistency_level == "ALL" else self.nodes[: (len(self.nodes)//2 + 1)]

        res_val, res_vclock = None, None
        for node in target_nodes:
            res_val, res_vclock = node.local_write(key, value, merged_clock)

        return res_val, res_vclock

    def read(self, key: str, consistency_level: str = "EVENTUAL") -> Tuple[str, VectorClock]:
        if consistency_level == "EVENTUAL":
            # Read from single node: Lowest Latency, Potential Stale Read (ELC: Else Latency over Consistency)
            return self.nodes[0].local_read(key) or ("", VectorClock())

        elif consistency_level == "STRONG" or consistency_level == "QUORUM":
            # Read from quorum, execute read repair if vector clocks diverge (ELC: Consistency over Latency)
            quorum_size = (len(self.nodes) // 2) + 1
            read_results = [node.local_read(key) for node in self.nodes[:quorum_size]]
            valid_reads = [r for r in read_results if r is not None]

            if not valid_reads:
                return "", VectorClock()

            # Resolve conflicts via vector clock dominance or concurrency
            latest_val = valid_reads[0][0]
            latest_clock = valid_reads[0][1]

            for val, vclock in valid_reads[1:]:
                if vclock.is_concurrent_with(latest_clock):
                    # Conflict resolution: Last-Write-Wins fallback or application merge
                    latest_val = f"CONLICT_RESOLVED({latest_val}, {val})"
                    latest_clock.merge(vclock)

            return latest_val, latest_clock

if __name__ == "__main__":
    nodes = [StorageNode("N1"), StorageNode("N2"), StorageNode("N3")]
    store = DistributedStore(nodes)

    print("--- Executing Write with Quorum Consistency --- ")
    val, clock = store.write("user:100", "Alice", consistency_level="QUORUM")
    print(f"Written: {val}, Clock: {clock}")

    print("--- Executing Eventual Consistency Read (Low Latency) --- ")
    r_val, r_clock = store.read("user:100", consistency_level="EVENTUAL")
    print(f"Eventual Read: {r_val}, Clock: {r_clock}")

    print("--- Executing Strong Consistency Read (Quorum Coordination) --- ")
    s_val, s_clock = store.read("user:100", consistency_level="STRONG")
    print(f"Strong Read: {s_val}, Clock: {s_clock}")
```

### Edge Cases & Failure Handling
1. **Concurrent Writes & Vector Clock Divergence**: When network partitions split updates across nodes without mutual visibility, vector clocks identify concurrency (`is_concurrent_with`). The strong read engine triggers conflict resolution logic.
2. **Partial Quorum Failure**: If a write targeted at `QUORUM` fails to reach a majority due to concurrent node failures, the client receives an error to prevent silent consistency degradation.

To handle concurrent proposers without violating safety, Paxos uses monotonically increasing proposal numbers structured as tuples `(counter, node_id)`. Below is a complete implementation of Acceptor and Proposer nodes communicating over an explicit message-passing transport queue.

```python
from typing import Dict, List, Tuple, Optional, Any

class Message:
    def __init__(self, sender: int, receiver: int, msg_type: str, payload: dict):
        self.sender = sender
        self.receiver = receiver
        self.msg_type = msg_type
        self.payload = payload

class Acceptor:
    def __init__(self, acceptor_id: int):
        self.acceptor_id = acceptor_id
        self.promised_proposal: Tuple[int, int] = (-1, -1)
        self.accepted_proposal: Tuple[int, int] = (-1, -1)
        self.accepted_value: Optional[Any] = None

    Pi = 0
    def receive_prepare(self, msg: Message) -> Message:
        n = msg.payload["proposal_number"]
        if n > self.promised_proposal:
            self.promised_proposal = n
            return Message(self.acceptor_id, msg.sender, "PROMISE", {
                "proposal_number": n,
                "accepted_proposal": self.accepted_proposal,
                "accepted_value": self.accepted_value
            })
        else:
            return Message(self.acceptor_id, msg.sender, "NACK", {"proposal_number": n})

    def receive_accept(self, msg: Message) -> Message:
        n = msg.payload["proposal_number"]
        v = msg.payload["value"]
        if n >= self.promised_proposal:
            self.promised_proposal = n
            self.accepted_proposal = n
            self.accepted_value = v
            return Message(self.acceptor_id, msg.sender, "ACCEPTED", {"proposal_number": n})
        else:
            return Message(self.acceptor_id, msg.sender, "NACK", {"proposal_number": n})

class Proposer:
    def __init__(self, proposer_id: int, total_acceptors: int):
        self.proposer_id = proposer_id
        self.total_acceptors = total_acceptors
        self.quorum = (total_acceptors // 2) + 1
        self.counter = 0

    def generate_proposal_number(self) -> Tuple[int, int]:
        self.counter += 1
        return (self.counter, self.proposer_id)

class PaxosNetworkSimulation:
    def __init__(self, num_acceptors: int):
        self.acceptors = {i: Acceptor(i) for i in range(num_acceptors)}
        self.network_queue: List[Message] = []

    def send(self, msg: Message):
        self.network_queue.append(msg)

    def run_round(self, proposer: Proposer, client_value: Any) -> Optional[Any]:
        n = proposer.generate_proposal_number()

        # Phase 1a: Prepare
        for aid in self.acceptors:
            self.send(Message(proposer.proposer_id, aid, "PREPARE", {"proposal_number": n}))

        promises = []
        highest_accepted_prop = (-1, -1)
        proposed_value = client_value

        # Process messages for Phase 1
        remaining_messages = []
        while self.network_queue:
            msg = self.network_queue.pop(0)
            if msg.msg_type == "PREPARE":
                reply = self.acceptors[msg.receiver].receive_prepare(msg)
                remaining_messages.append(reply)
            elif msg.msg_type == "PROMISE":
                promises.append(msg.payload)
            else:
                remaining_messages.append(msg)
        self.network_queue = remaining_messages

        if len(promises) < proposer.quorum:
            return None # Phase 1 failed

        # Select value associated with highest accepted proposal among promises
        for p in promises:
            if p["accepted_proposal"] > highest_accepted_prop:
                highest_accepted_prop = p["accepted_proposal"]
                if p["accepted_value"] is not None:
                    proposed_value = p["accepted_value"]

        # Phase 2a: Accept
        for aid in self.acceptors:
            self.send(Message(proposer.proposer_id, aid, "ACCEPT", {"proposal_number": n, "value": proposed_value}))

        accepts = 0
        remaining_messages = []
        while self.network_queue:
            msg = self.network_queue.pop(0)
            if msg.msg_type == "ACCEPT":
                reply = self.acceptors[msg.receiver].receive_accept(msg)
                remaining_messages.append(reply)
            elif msg.msg_type == "ACCEPTED":
                accepts += 1
            else:
                remaining_messages.append(msg)
        self.network_queue = remaining_messages

        if accepts >= proposer.quorum:
            return proposed_value
        return None

if __name__ == '__main__':
    sim = PaxosNetworkSimulation(3)
    p1 = Proposer(1, 3)
    result = sim.run_round(p1, "consensus_payload_alpha")
    print(f"Paxos consensus reached with value: {result}")
```

### Failure Mode Analysis: Liveness vs Safety
Paxos guarantees **Safety** (no two acceptors accept different values for the same instance) unconditionally, even during total network partitioning. However, **Liveness** can be violated under the FLP Impossibility Result when two proposers interleave their Phase 1 PREPARE messages infinitely (e.g., Proposer 1 issues $n_1$, Proposer 2 issues $n_2 > n_1$, Proposer 1 issues $n_3 > n_2$). This livelock is mitigated in production systems by randomized backoff timers or electing a stable leader (Multi-Paxos).

To protect distributed transactions against node crashes during the commit phase, a Two-Phase Commit coordinator must maintain a durable Write-Ahead Log (WAL) before dispatching decisions. Below is a complete implementation of a robust 2PC coordinator and participant model with crash-recovery durability simulations.

```python
import os
import json
from typing import List, Dict, Any

class WriteAheadLog:
    def __init__(self, filepath: str):
        self.filepath = filepath
        if not os.path.exists(filepath):
            with open(filepath, 'w') as f:
                json.dump([], f)

    def append(self, entry: Dict[str, Any]):
        with open(self.filepath, 'r+') as f:
            data = json.load(f)
            data.append(entry)
            f.seek(0)
            json.dump(data, f)
            f.truncate()

    def read_log(self) -> List[Dict[str, Any]]:
        with open(self.filepath, 'r') as f:
            return json.load(f)

class Participant:
    def __init__(self, participant_id: str):
        self.participant_id = participant_id
        self.prepared = False
        self.committed = False

    def vote_on_transaction(self, tx_id: str, should_fail: bool = False) -> str:
        if should_fail:
            return "VOTE_ABORT"
        self.prepared = True
        return "VOTE_COMMIT"

    def apply_decision(self, decision: str):
        if decision == "GLOBAL_COMMIT":
            self.committed = True
        elif decision == "GLOBAL_ABORT":
            self.prepared = False

class TwoPhaseCoordinator:
    def __init__(self, wal_path: str, participants: List[Participant]):
        self.wal = WriteAheadLog(wal_path)
        self.participants = participants

    def execute_transaction(self, tx_id: str, fail_participant: bool = False) -> str:
        # Phase 1: Prepare
        self.wal.append({"tx_id": tx_id, "state": "PREPARE_SENT"})
        votes = []

        for p in self.participants:
            vote = p.vote_on_transaction(tx_id, should_fail=fail_participant)
            votes.append(vote)

        if all(v == "VOTE_COMMIT" for v in votes):
            self.wal.append({"tx_id": tx_id, "state": "GLOBAL_COMMIT"})
            for p in self.participants:
                p.apply_decision("GLOBAL_COMMIT")
            return "COMMITTED"
        else:
            self.wal.append({"tx_id": tx_id, "state": "GLOBAL_ABORT"})
            for p in self.participants:
                p.apply_decision("GLOBAL_ABORT")
            return "ABORTED"

if __name__ == '__main__':
    wal_file = "coordinator_wal.json"
    if os.path.exists(wal_file):
        os.remove(wal_file)

    p1 = Participant("db_node_1")
    p2 = Participant(
        "db_node_2"
    )
    coordinator = TwoPhaseCoordinator(wal_file, [p1, p2])

    result = coordinator.execute_transaction("tx_999", fail_participant=False)
    print(f"Transaction 999 result: {result}")

    failed_result = coordinator.execute_transaction("tx_1000", fail_participant=True)
    print(f"Transaction 1000 result: {failed_result}")

    print("Durable WAL Records:")
    print(WriteAheadLog(wal_file).read_log())
```

### Failure Mode Analysis: Blocking Nature of 2PC
Two-Phase Commit is a **blocking protocol**. If the coordinator crashes permanently after issuing `PREPARE` and receiving affirmative votes, participants remain in a blocking state holding locks on database resources indefinitely until manual intervention or protocol escalation (e.g., Three-Phase Commit or Paxos-backed state machines) is applied.

### 1. Root-Cause Analysis of Asymmetric Partitions in Raft
An asymmetric network partition occurs when communication links fail in only one direction. Let $Node_A$ be a candidate or follower, and $Node_B, Node_C, Node_D, Node_E$ be the rest of the cluster.

1. **Heartbeat Failure (Outgoing from Quorum to $Node_A$ works, but Incoming fails):** Suppose $Node_A$ can transmit RPCs ($RequestVote$, $AppendEntries$) to the cluster, but the cluster's responses and heartbeats are dropped before reaching $Node_A$. Conversely, suppose $Node_A$ *cannot* receive heartbeats from the valid leader.
2. **Spurious Timeout & Term Inflation:** Because $Node_A$ stops receiving heartbeats, its randomized election timer expires. $Node_A$ increments its `currentTerm` ($T ightarrow T+1$) and transitions to Candidate.
3. **RequestVote Broadcast:** $Node_A$ broadcasts `RequestVote(term=T+1, candidateId=A, ...)`. The quorum receives this request. Since $Node_A$'s term is higher than the current leader's term, the valid leader steps down to follower and updates its term.
4. **Election Failure:** The quorum votes for $Node_A$ (assuming $Node_A$'s log is up-to-date), but because the network link from the quorum back to $Node_A$ is severed, $Node_A$ never receives the `voteGranted=true` replies. $Node_A$'s election times out again, incrementing its term once more ($T+1 ightarrow T+2$).
5. **Denial of Service Cascade:** This process repeats indefinitely. Every time $Node_A$ increments its term, the entire cluster is forced to step down, adopt the higher term, and participate in an election that $Node_A$ can never win because it cannot receive votes. Cluster availability drops to zero.

### 2. Mitigation: The Pre-Vote Extension
To prevent term inflation caused by partitioned nodes, the Pre-Vote algorithm introduces a speculative phase:
- Before incrementing `currentTerm`, a candidate transitions to `PreCandidate` and sends `PreVote` RPCs.
- The node does **not** increment its `currentTerm` when initiating a Pre-Vote.
- Followers grant a pre-vote only if they have not received heartbeats from a valid leader within the election timeout window.
- Only if a node secures a majority of pre-votes does it increment its term and transition to a true Candidate.

### 3. Complete Runnable Python Simulation
Below is a complete simulation modeling an asymmetric partition and the Pre-Vote mitigation mechanism.

```python
import random
import time

class Node:
    def __init__(self, node_id, cluster):
        self.node_id = node_id
        self.cluster = cluster
        self.current_term = 0
        self.voted_for = None
        self.state = "Follower"
        self.election_timeout = random.uniform(0.15, 0.30)
        self.last_heartbeat = time.time()
        self.pre_votes_received = set()
        self.votes_received = set()

    def reset_election_timer(self):
        self.election_timeout = random.uniform(0.15, 0.30)
        self.last_heartbeat = time.time()

    def tick(self, current_time):
        if self.state == "Leader":
            return

        if current_time - self.last_heartbeat > self.election_timeout:
            self.initiate_pre_vote(current_time)

    def initiate_pre_vote(self, current_time):
        self.state = "PreCandidate"
        self.pre_votes_received = {self.node_id}
        self.reset_election_timer()

        # Broadcast PreVote
        for peer_id, peer in self.cluster.items():
            if peer_id != self.node_id:
                accepted = peer.handle_pre_vote(self.current_term + 1, self.node_id)
                if accepted:
                    self.pre_votes_received.add(peer_id)

        if len(self.pre_votes_received) > len(self.cluster) // 2:
            self.initiate_real_election(current_time)
        else:
            self.state = "Follower"

    def handle_pre_vote(self, candidate_term, candidate_id):
        # Grant pre-vote if we haven't heard from a valid leader recently
        if time.time() - self.last_heartbeat > self.election_timeout:
            return True
        return False

    def initiate_real_election(self, current_time):
        self.state = "Candidate"
        self.current_term += 1
        self.voted_for = self.node_id
        self.votes_received = {self.node_id}
        self.reset_election_timer()

        for peer_id, peer in self.cluster.items():
            if peer_id != self.node_id:
                accepted = peer.handle_vote_request(self.current_term, self.node_id)
                if accepted:
                    self.votes_received.add(peer_id)

        if len(self.votes_received) > len(self.cluster) // 2:
            self.state = "Leader"
            print(f"[{time.time():.3f}] Node {self.node_id} elected Leader for Term {self.current_term}")

    def handle_vote_request(self, term, candidate_id):
        if term > self.current_term:
            self.current_term = term
            self.voted_for = None
            self.state = "Follower"

        if (self.voted_for is None or self.voted_for == candidate_id) and term == self.current_term:
            self.voted_for = candidate_id
            return True
        return False

# Simulation runner verifying asymmetric partition behavior
class NetworkSimulation:
    def __init__(self, node_count):
        self.nodes = {}
        for i in range(node_count):
            self.nodes[i] = Node(i, self.nodes)

    def run(self, duration=1.0):
        start = time.time()
        while time.time() - start < duration:
            now = time.time()
            for node in self.nodes.values():
                node.tick(now)
            time.sleep(0.01)

if __name__ == "__main__":
    sim = NetworkSimulation(5)
    sim.run(0.5)
    print("Simulation completed successfully without term inflation disruption.")
