#include <linux/bpf.h>
#include <linux/kernel.h>
#include <linux/errno.h>

#define MAX_ALLOWED_BPF_STACK_CONSUMPTION 2048 // Bytes

int bpf_check_stack_depth_limit(struct bpf_verifier_env *env, int insn_idx, int subprog)
{
    struct bpf_subprog_info *subprogs = env->subprog_info;
    int total_stack = subprogs[subprog].stack_depth;

    if (total_stack > MAX_ALLOWED_BPF_STACK_CONSUMPTION) {
        verbose(env, "Kernel stack overflow risk: subprog %d requests %d bytes (max: %d)\n",
                subprog, total_stack, MAX_ALLOWED_BPF_STACK_CONSUMPTION);
        return -E2BIG;
    }

    return 0;
}

/* Runtime guard injected into helper entry preamble */
notrace int bpf_security_stack_guard_check(void)
{
    unsigned long stack_left = stack_pointer_remaining();

    if (unlikely(stack_left < 1024)) {
        WARN_ONCE(1, "eBPF runtime stack exhaustion imminent: %lu bytes remaining\n", stack_left);
        return -ENOMEM;
    }
    return 0;
}
```

