#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/netfilter.h>
#include <linux/skbuff.h>

// Scoped automatic SKB cleanup helper for modern kernels
static inline void skb_cleanup_drop(struct sk_buff **skb)
{
    if (*skb) {
        kfree_skb(*skb);
        *skb = NULL;
    }
}

#define __cleanup_skb __attribute__((cleanup(skb_cleanup_drop)))

unsigned int secure_nf_hook_fn(void *priv,
                               struct sk_buff *skb,
                               const struct nf_hook_state *state)
{
    __cleanup_skb struct sk_buff *tracked_skb = skb;
    int ret;

    // Explicitly take ownership using NF_STOLEN semantics
    // We assign tracked_skb to clean up automatically if we exit via error

    if (unlikely(!pskb_may_pull(tracked_skb, sizeof(struct iphdr)))) {
        // Error path: tracked_skb will be automatically freed when going out of scope
        return NF_DROP;
    }

    ret = queue_packet_to_workqueue(tracked_skb);
    if (unlikely(ret < 0)) {
        // Error path: workqueue full. tracked_skb automatically freed here.
        return NF_DROP;
    }

    // Successfully queued: disarm the automatic cleanup guard by releasing ownership
    // Ownership is now transferred entirely to the workqueue consumer.
    no_free_ptr(tracked_skb);

    return NF_STOLEN;
}
```

