struct ipc_message {
    size_t length;
    char payload[MAX_PAYLOAD_SIZE];
};

int hardened_receive_ipc_message(const char __user *user_buf, size_t user_len) {
    struct ipc_message *msg;

    // Strict bounds check: user length must not exceed maximum payload capacity
    if (user_len == 0 || user_len > MAX_PAYLOAD_SIZE)
        return -EINVAL;

    msg = kmalloc(sizeof(*msg), GFP_KERNEL);
    if (!msg)
        return -ENOMEM;

    msg->length = user_len;

    // Zero out payload buffer to prevent information disclosure (infoleak)
    memset(msg->payload, 0, MAX_PAYLOAD_SIZE);

    if (copy_from_user(msg->payload, user_buf, user_len)) {
        kfree(msg);
        return -EFAULT;
    }

    // Process message safely...
    pr_info("Successfully processed IPC message of length %zu\n", msg->length);

    kfree(msg);
    return 0;
}

