struct graph_node {
    int id;
    struct graph_node *left;
    struct graph_node *right;
};

// Unsafe Recursive Approach (For illustration of anti-pattern)
void traverse_recursive(struct graph_node *node) {
    if (!node) return;
    // Consumes stack frame per node
    traverse_recursive(node->left);
    traverse_recursive(node->right);
}

// Safe Iterative Approach with Explicit Bounded Worklist
