int traverse_iterative(struct graph_node *root) {
    struct graph_node *stack[MAX_STACK_DEPTH];
    int top = -1;

    if (!root)
        return 0;

    stack[++top] = root;

    while (top >= 0) {
        if (top >= MAX_STACK_DEPTH - 1) {
            pr_err("Worklist overflow prevented!\n");
            return -ENOMEM;
        }

        struct graph_node *curr = stack[top--];

        // Process current node
        pr_info("Visiting node ID: %d\n", curr->id);

        if (curr->right)
            stack[++top] = curr->right;
        if (curr->left)
            stack[++top] = curr->left;
    }

    return 0;
}

static int __init rca_stack_init(void) {
