    root->id = 1;
    traverse_iterative(root);
    kfree(root);
    return 0;
}

static void __exit rca_stack_exit(void) {
    pr_info("Unloading stack RCA module\n");
}

module_init(rca_stack_init);
module_exit(rca_stack_exit);
