```c
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/slab.h>
#include <linux/types.h>

MODULE_LICENSE("GPL");

enum request_state {
    REQ_STATE_INIT = 0,
    REQ_STATE_SUBMITTED,
    REQ_STATE_COMPLETED,
    REQ_STATE_CANCELLED,
    REQ_STATE_FREED
};

struct block_request {
    int id;
    atomic_t state;
    char *buffer;
};

struct block_request *block_request_alloc(int id) {
    struct block_request *req;

    req = kmalloc(sizeof(struct block_request), GFP_KERNEL);
    if (!req)
        return NULL;

    req->id = id;
    atomic_set(&req->state, REQ_STATE_INIT);
    req->buffer = kzalloc(512, GFP_KERNEL);
    if (!req->buffer) {
        kfree(req);
        return NULL;
    }
    return req;
}

bool block_request_try_free(struct block_request *req) {
    int old_state = atomic_cmpxchg(&req->state, REQ_STATE_COMPLETED, REQ_STATE_FREED);
    if (old_state == REQ_STATE_COMPLETED)
        goto free_mem;

    old_state = atomic_cmpxchg(&req->state, REQ_STATE_CANCELLED, REQ_STATE_FREED);
    if (old_state == REQ_STATE_CANCELLED)
        goto free_mem;

    return false;

free_mem:
    kfree(req->buffer);
    kfree(req);
    return true;
}

bool block_request_complete(struct block_request *req) {
    int old_state = atomic_cmpxchg(&req->state, REQ_STATE_SUBMITTED, REQ_STATE_COMPLETED);
    if (old_state == REQ_STATE_SUBMITTED) {
        block_request_try_free(req);
        return true;
    }
    return false;
}

bool block_request_cancel(struct block_request *req) {
    int old_state = atomic_cmpxchg(&req->state, REQ_STATE_SUBMITTED, REQ_STATE_CANCELLED);
    if (old_state == REQ_STATE_SUBMITTED) {
        block_request_try_free(req);
        return true;
    }
    return false;
}

