## 3. Bounds-Checked Ring Buffer Implementation
```c
#include <linux/kernel.h>
#include <linux/slab.h>
#include <linux/string.h>

struct secure_ring_buffer {
    size_t capacity;
    size_t head;
    size_t tail;
    size_t element_size;
    void *data;
};

struct secure_ring_buffer *secure_ring_create(size_t capacity, size_t element_size)
{
    struct secure_ring_buffer *ring;
    ring = kmalloc(sizeof(*ring), GFP_KERNEL);
    if (!ring)
        return NULL;

    ring->capacity = capacity;
    ring->element_size = element_size;
    ring->head = 0;
    ring->tail = 0;
    ring->data = kmalloc_array(capacity, element_size, GFP_KERNEL);
    if (!ring->data) {
        kfree(ring);
        return NULL;
    }
    return ring;
}

int secure_ring_push(struct secure_ring_buffer *ring, const void *src, size_t len)
{
    if (len > ring->element_size)
        return -EINVAL;

    size_t next_tail = (ring->tail + 1) % ring->capacity;
    if (next_tail == ring->head)
        return -ENOBUFS;

    void *dest = ring->data + (ring->tail * ring->element_size);
    memcpy(dest, src, len);
    // Zero out remaining padding bytes to prevent information leaks
    if (len < ring->element_size) {
        memset(dest + len, 0, ring->element_size - len);
    }

    ring->tail = next_tail;
    return 0;
}

void secure_ring_destroy(struct secure_ring_buffer *ring)
{
    if (ring) {
        kfree(ring->data);
        kfree(ring);
    }
}
```

## 4. Trade-offs and Edge Cases
Enforcing strict element size bounds and zero-padding unused bytes eliminates both heap overflow vectors and kernel information disclosure vulnerabilities, with a negligible CPU overhead penalty for padding operations.
